@Slf4j
@PluginDescriptor(
	name = "RuneJourney",
	description = "Your account's personal history, goals and adaptive plans, automatically recorded while you play",
	tags = {"journey", "goals", "planner", "history", "timeline", "milestones", "recap"},
	internalName = "runejourney"
)
public class RuneJourneyPlugin extends Plugin
{
	/**
	 * Save unsaved progress roughly every 30 seconds.
	 */
	private static final int SAVE_INTERVAL_TICKS = 50;
	/**
	 * Refresh the sidebar at most every ~3 seconds while playing.
	 */
	private static final int UI_INTERVAL_TICKS = 5;
	/**
	 * Refresh purchase goal prices roughly every 5 minutes.
	 */
	private static final int PRICE_REFRESH_TICKS = 500;
	private static final EnumSet<WorldType> UNTRACKED_WORLDS = EnumSet.of(
		WorldType.BETA_WORLD, WorldType.NOSAVE_MODE, WorldType.TOURNAMENT_WORLD, WorldType.QUEST_SPEEDRUNNING,
		WorldType.LAST_MAN_STANDING, WorldType.PVP_ARENA);

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private JourneyService service;

	@Inject
	private JourneyStore store;

	@Inject
	private ScreenshotService screenshots;

	@Inject
	private IncomeTracker incomeTracker;

	@Inject
	private SupplyTracker supplyTracker;

	@Inject
	private WealthTracker wealthTracker;

	@Inject
	private ReportWindowManager reportWindows;

	@Inject
	private ScreenshotWindowManager screenshotWindows;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RuneJourneyOverlay overlay;

	@Inject
	private WrappedPlayer wrappedPlayer;

	@Inject
	private RuneJourneyConfig config;

	private final Map<Skill, Integer> lastStatXp = new EnumMap<>(Skill.class);
	/**
	 * Grand Exchange updates that arrive during login, before the profile is ready.
	 */
	private final List<GrandExchangeOfferChanged> pendingOffers = new ArrayList<>();

	@Getter
	private ExecutorService executor;

	private RuneJourneyPanel panel;
	private NavigationButton navButton;

	private volatile String loadingKey;
	private int lastUiVersion = -1;
	private int lastUiTick;

	@Override
	protected void startUp() throws Exception
	{
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "RuneJourney");
			t.setDaemon(true);
			return t;
		});
		store.setRoot(getPluginDirectory());
		screenshots.setExecutor(executor);
		wrappedPlayer.setExecutor(executor, service::getProfileKey);

		panel = injector.getInstance(RuneJourneyPanel.class);
		navButton = NavigationButton.builder()
			.tooltip("RuneJourney")
			.icon(Icons.navIcon())
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			loadProfile();
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		wrappedPlayer.close();
		overlayManager.remove(overlay);
		overlay.setData(null);
		reportWindows.close();
		screenshotWindows.close();
		incomeTracker.reset();
		supplyTracker.reset();
		wealthTracker.reset();
		lastStatXp.clear();
		pendingOffers.clear();
		// Finish the play session first so its records are included in the final save
		service.resetSessionState();
		Runnable writes = service.collectWrites();
		if (writes != null)
		{
			executor.submit(writes);
		}
		// Let the final save finish without blocking the shutdown thread
		executor.shutdown();
		screenshots.clear();
		screenshots.setExecutor(null);
		service.unload();
		loadingKey = null;
		lastUiVersion = -1;
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		service.resetSessionState();
		Runnable writes = service.collectWrites();
		if (writes != null && executor != null && !executor.isShutdown())
		{
			event.waitFor(executor.submit(writes));
		}
	}

	@Provides
	RuneJourneyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RuneJourneyConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadProfile();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			incomeTracker.reset();
			supplyTracker.reset();
			wealthTracker.reset();
			lastStatXp.clear();
			pendingOffers.clear();
			// The in-game view can't show on the login screen
			if (wrappedPlayer.isPlayingInGame())
			{
				wrappedPlayer.close();
			}
			service.resetSessionState();
			save();
			screenshots.clear();
			refreshPanel(true);
		}
	}

	private String profileKey()
	{
		long hash = client.getAccountHash();
		if (hash == -1)
		{
			return null;
		}
		EnumSet<WorldType> types = client.getWorldType();
		for (WorldType t : UNTRACKED_WORLDS)
		{
			if (types.contains(t))
			{
				return null;
			}
		}
		String key = Long.toString(hash);
		if (types.contains(WorldType.SEASONAL))
		{
			key += "-seasonal";
		}
		else if (types.contains(WorldType.DEADMAN))
		{
			key += "-deadman";
		}
		else if (types.contains(WorldType.FRESH_START_WORLD))
		{
			key += "-fsw";
		}
		return key;
	}

	private void loadProfile()
	{
		String key = profileKey();
		if (key == null)
		{
			if (service.getProfileKey() != null)
			{
				service.resetSessionState();
				save();
				service.unload();
				overlay.setData(null);
			}
			pendingOffers.clear();
			return;
		}
		if (key.equals(service.getProfileKey()) || key.equals(loadingKey))
		{
			return;
		}

		service.resetSessionState();
		save();
		service.unload();
		overlay.setData(null);
		loadingKey = key;
		service.beginLoad(key);
		executor.submit(() ->
		{
			try
			{
				JourneyStore.Loaded loaded = store.load(key);
				// Only installs if no other account or shutdown has happened since the load started
				if (service.installIfCurrent(key, loaded))
				{
					loadingKey = null;
					refreshPanel(true);
				}
			}
			catch (IOException e)
			{
				log.warn("Unable to load RuneJourney profile", e);
				loadingKey = null;
			}
		});
	}

	private void save()
	{
		Runnable writes = service.collectWrites();
		if (writes != null && executor != null && !executor.isShutdown())
		{
			executor.submit(writes);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = client.getTickCount();
		if (!service.isReady())
		{
			return;
		}

		if (!service.isBaselineSet())
		{
			if (client.getLocalPlayer() != null)
			{
				service.updatePlayerName(client.getLocalPlayer().getName());
			}
			Map<String, Long> xp = new HashMap<>();
			long sum = 0;
			for (Skill s : Skills.ALL)
			{
				long v = client.getSkillExperience(s);
				xp.put(s.name(), v);
				sum += v;
			}
			if (sum <= 0)
			{
				return;
			}
			service.setBaseline(xp, tick);
			readCounters();
			refreshPurchasePrices();
			for (GrandExchangeOfferChanged offer : pendingOffers)
			{
				handleOffer(offer);
			}
			pendingOffers.clear();
		}

		incomeTracker.onTick(tick);
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			wealthTracker.onTick();
		}
		service.onTick(tick);
		screenshots.onTick(tick);

		if (tick % SAVE_INTERVAL_TICKS == 0)
		{
			save();
		}
		if (tick % PRICE_REFRESH_TICKS == 0)
		{
			refreshPurchasePrices();
		}
		if (tick - lastUiTick >= UI_INTERVAL_TICKS)
		{
			lastUiTick = tick;
			refreshPanel(false);
			overlay.setData(config.showOverlay() ? service.overlayData() : null);
		}
	}

	private void refreshPanel(boolean force)
	{
		RuneJourneyPanel p = panel;
		if (p == null)
		{
			return;
		}
		int version = service.getVersion();
		if (!force && version == lastUiVersion)
		{
			return;
		}
		lastUiVersion = version;
		SwingUtilities.invokeLater(() -> p.refresh(force));
	}

	/**
	 * Clue tiers and the varbits holding their completion counts.
	 */
	private static final Map<Integer, String> CLUE_VARBITS = new HashMap<>();

	static
	{
		CLUE_VARBITS.put(VarbitID.COLLECTION_CLUES_BEGINNER_COMPLETED, "Beginner");
		CLUE_VARBITS.put(VarbitID.COLLECTION_CLUES_EASY_COMPLETED, "Easy");
		CLUE_VARBITS.put(VarbitID.COLLECTION_CLUES_MEDIUM_COMPLETED, "Medium");
		CLUE_VARBITS.put(VarbitID.COLLECTION_CLUES_HARD_COMPLETED, "Hard");
		CLUE_VARBITS.put(VarbitID.COLLECTION_CLUES_ELITE_COMPLETED, "Elite");
		CLUE_VARBITS.put(VarbitID.COLLECTION_CLUES_MASTER_COMPLETED, "Master");
	}

	/**
	 * Variables whose bits flag each completed combat task.
	 */
	private static final int[] CA_TASK_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
		VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
		VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
		VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19, VarPlayerID.CA_TASK_COMPLETED_20,
	};

	private int completedCombatTasks()
	{
		int count = 0;
		for (int varp : CA_TASK_VARPS)
		{
			count += Integer.bitCount(client.getVarpValue(varp));
		}
		return count;
	}

	private static boolean isCaTaskVarp(int varp)
	{
		for (int v : CA_TASK_VARPS)
		{
			if (v == varp)
			{
				return true;
			}
		}
		return false;
	}

	private void readCounters()
	{
		service.onCounter(Counters.CA_TASKS, completedCombatTasks());
		service.onCounter(Counters.QUEST_POINTS, client.getVarpValue(VarPlayerID.QP));
		service.onCounter(Counters.COLLECTION_LOG, client.getVarpValue(VarPlayerID.COLLECTION_COUNT));
		CLUE_VARBITS.forEach((varbit, tier) -> service.onCounter(Counters.clues(tier), client.getVarbitValue(varbit)));
		// Price the bank and anything else held since last time, even if it hasn't been opened yet
		wealthTracker.invalidate();
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!service.isBaselineSet())
		{
			return;
		}
		if (event.getVarpId() == VarPlayerID.QP)
		{
			service.onCounter(Counters.QUEST_POINTS, event.getValue());
		}
		else if (event.getVarpId() == VarPlayerID.COLLECTION_COUNT)
		{
			service.onCounter(Counters.COLLECTION_LOG, event.getValue());
		}
		else if (event.getVarbitId() == -1 && isCaTaskVarp(event.getVarpId()))
		{
			service.onCounter(Counters.CA_TASKS, completedCombatTasks());
		}
		else if (event.getVarbitId() != -1 && CLUE_VARBITS.containsKey(event.getVarbitId()))
		{
			service.onCounter(Counters.clues(CLUE_VARBITS.get(event.getVarbitId())), event.getValue());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		// Net worth and cash are read by WealthTracker each tick, not from these events
		int id = event.getContainerId();
		if (id == InventoryID.INV)
		{
			incomeTracker.onInventory(event.getItemContainer());
			incomeTracker.discard(supplyTracker.onInventory(event.getItemContainer(), client.getTickCount()));
			return;
		}
		if (id != InventoryID.TRAIL_REWARDINV)
		{
			return;
		}
		List<ItemStack> stacks = new ArrayList<>();
		for (Item item : event.getItemContainer().getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				stacks.add(new ItemStack(item.getId(), item.getQuantity()));
			}
		}
		service.onClueReward(priced(stacks), client.getTickCount());
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		GrandExchangeOfferState state = event.getOffer().getState();
		if (!service.isReady() || !service.isBaselineSet())
		{
			// Offers are replayed while logging in; empty slots then aren't real collections
			if (state != GrandExchangeOfferState.EMPTY)
			{
				pendingOffers.add(event);
			}
			return;
		}
		handleOffer(event);
	}

	private void handleOffer(GrandExchangeOfferChanged event)
	{
		GrandExchangeOffer offer = event.getOffer();
		GrandExchangeOfferState state = offer.getState();
		boolean buy = state == GrandExchangeOfferState.BUYING || state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;
		String name = offer.getItemId() > 0 ? itemManager.getItemComposition(offer.getItemId()).getName() : null;
		service.onGrandExchangeOffer(event.getSlot(), offer.getItemId(), name, buy, state == GrandExchangeOfferState.EMPTY,
			offer.getQuantitySold(), offer.getSpent());
	}


	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST && service.isReady())
		{
			readCollectionLogPage();
		}
	}

	/**
	 * Reads the collection log page on screen: its title and which items are obtained (obtained
	 * items are drawn fully opaque, missing ones faded).
	 */
	private void readCollectionLogPage()
	{
		String title = null;
		for (int id : new int[]{InterfaceID.Collection.HEADER_TEXT, InterfaceID.Collection.HEADER})
		{
			Widget header = client.getWidget(id);
			if (header == null)
			{
				continue;
			}
			Widget[] children = header.getDynamicChildren();
			String text = children != null && children.length > 0 ? children[0].getText() : header.getText();
			text = text == null ? null : Text.removeTags(text).trim();
			if (text != null && !text.isEmpty() && !text.startsWith("Obtained"))
			{
				title = text;
				break;
			}
		}
		if (title == null)
		{
			return;
		}

		List<ClogItem> items = new ArrayList<>();
		for (int id : new int[]{InterfaceID.Collection.ITEMS, InterfaceID.Collection.ITEMS_CONTENTS})
		{
			Widget container = client.getWidget(id);
			if (container == null || container.getDynamicChildren() == null)
			{
				continue;
			}
			for (Widget w : container.getDynamicChildren())
			{
				if (w.getItemId() > 0)
				{
					String name = itemManager.getItemComposition(w.getItemId()).getName();
					items.add(new ClogItem(w.getItemId(), name, w.getOpacity() == 0));
				}
			}
			if (!items.isEmpty())
			{
				break;
			}
		}
		service.onCollectionLogPage(title, items);
	}

	/**
	 * Keeps purchase goals in step with the Grand Exchange price.
	 */
	private void refreshPurchasePrices()
	{
		for (JourneyService.PurchaseRef ref : service.purchaseRefs())
		{
			long price = itemManager.getItemPrice(ref.getItemId());
			if (price > 0)
			{
				service.setPurchaseTarget(ref.getGoalId(), price * ref.getQuantity());
			}
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Integer last = lastStatXp.put(event.getSkill(), event.getXp());
		if (last != null && event.getXp() > last)
		{
			incomeTracker.onXp(event.getSkill(), event.getXp() - last);
		}
		service.onXp(event.getSkill(), event.getXp(), client.getTickCount());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		ChatParser.Result r = ChatParser.parse(Text.removeTags(event.getMessage()));
		if (r == null)
		{
			return;
		}

		int tick = client.getTickCount();
		switch (r.getKind())
		{
			case KILL_COUNT:
				service.onKillCount(r.getName(), r.getCount(), tick);
				break;
			case PERSONAL_BEST:
				service.onPersonalBest(r.getName(), tick);
				break;
			case COLLECTION_LOG:
				service.onCollectionLog(r.getName(), tick);
				break;
			case QUEST:
				service.onQuest(r.getName(), tick);
				break;
			case DIARY_TIER:
				service.onDiary(r.getName(), r.getDetail(), tick);
				break;
			case COMBAT_TASK:
				service.onCombatTask(r.getName(), r.getDetail(), r.getCount(), tick);
				break;
			case PET:
				service.onPet(false, tick);
				break;
			case DUPLICATE_PET:
				service.onPet(true, tick);
				break;
			case SLAYER_TASK:
				service.onSlayerTask();
				break;
			case CLUE:
				service.onClueCompleted(r.getName(), r.getCount(), tick);
				break;
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		incomeTracker.onInterfaceOpened(event.getGroupId());
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		incomeTracker.onInterfaceClosed(event.getGroupId(), client.getTickCount());
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			service.onDeath(client.getTickCount());
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		supplyTracker.onMenuOptionClicked(event.getMenuOption(), event.getItemId(), client.getTickCount());
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		service.onLoot(event.getNpc().getName(), priced(event.getItems()), client.getTickCount());
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		// NPC loot is handled by NpcLootReceived, which works without the Loot Tracker plugin.
		// Player (PvP) loot is intentionally ignored.
		if (event.getType() == LootRecordType.NPC || event.getType() == LootRecordType.PLAYER)
		{
			return;
		}
		// Clue caskets are read from the reward screen so they're recorded even without the Loot Tracker
		if (event.getName() != null && event.getName().startsWith("Clue Scroll"))
		{
			return;
		}
		// Pickpocketing is counted as Thieving income by the income tracker
		if (event.getType() == LootRecordType.PICKPOCKET)
		{
			return;
		}
		incomeTracker.suppress(client.getTickCount());
		service.onLoot(event.getName(), priced(event.getItems()), client.getTickCount());
	}

	private List<JourneyService.LootItem> priced(Collection<ItemStack> items)
	{
		List<JourneyService.LootItem> result = new ArrayList<>();
		for (ItemStack stack : items)
		{
			ItemComposition comp = itemManager.getItemComposition(stack.getId());
			long price = (long) itemManager.getItemPrice(stack.getId()) * stack.getQuantity();
			result.add(new JourneyService.LootItem(stack.getId(), comp.getName(), stack.getQuantity(), price));
		}
		return result;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (RuneJourneyConfig.GROUP.equals(event.getGroup()))
		{
			refreshPanel(true);
		}
	}
}

package com.runejourney;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.api.Skill;

/**
 * Which skilling actions make money, and how much. Gathering skills earn the value of what they
 * produce (logs, ore, fish...); processing skills earn the value they add (product minus inputs).
 * Skills that only use items up, like Prayer or Firemaking, never count as income.
 */
final class SkillingRules
{
	enum Mode
	{
		/**
		 * Value of the products gained; anything used up (bait, seeds) is ignored.
		 */
		GATHER,
		/**
		 * Everything gained minus everything used, but only when something was made.
		 */
		PROCESS
	}

	@Value
	static class Change
	{
		String name;
		/**
		 * Positive when gained, negative when used up.
		 */
		int quantity;
		long unitPrice;
	}

	@Value
	static class Income
	{
		Skill skill;
		long value;
		/**
		 * The gained items that counted, for item goals.
		 */
		List<Change> products;
	}

	@Value
	private static class Rule
	{
		Mode mode;
		Predicate<String> product;
		/**
		 * Something that has to be used up for the products to count, or null if anything goes.
		 */
		Predicate<String> input;
	}

	private static final Map<Skill, Rule> RULES = new EnumMap<>(Skill.class);
	/**
	 * Made with Crafting but only worth anything as part of a birdhouse run, which is Hunter.
	 */
	private static final Pattern BIRDHOUSE = Pattern.compile("bird ?house$");
	private static final Pattern SALVAGE = Pattern.compile("salvage$");

	static
	{
		gather(Skill.WOODCUTTING, "logs$", "^bird nest", "^clue nest");
		gather(Skill.MINING, " ore$", "^coal$", "^uncut ", "essence$", "^clay$", "^sandstone", "^granite",
			"^amethyst$", "^unidentified minerals$", "^gold nugget", "^volcanic ash$", "^calcified deposit$");
		gather(Skill.FISHING, "^raw ", "^leaping ", " eel$", "^karambwanji$", "^clue bottle", "^casket$");
		gather(Skill.HUNTER, "chinchompa$", " fur$", " hide$", "^bird nest", "^grimy ", "impling jar$", "^raw ",
			"^kebbit ", "feather$", "^hunters' loot sack", "^clue nest");
		RULES.put(Skill.FARMING, new Rule(Mode.GATHER, SkillingRules::isHarvest, null));
		RULES.put(Skill.THIEVING, new Rule(Mode.GATHER, name -> true, null));
		// Salvage can't be sold, so hauling it in earns nothing; sorting it earns whatever comes out
		RULES.put(Skill.SAILING, new Rule(Mode.GATHER, name -> !SALVAGE.matcher(name).find(),
			name -> SALVAGE.matcher(name).find()));
		for (Skill s : new Skill[]{Skill.COOKING, Skill.CRAFTING, Skill.FLETCHING, Skill.HERBLORE, Skill.SMITHING,
			Skill.RUNECRAFT, Skill.MAGIC})
		{
			RULES.put(s, new Rule(Mode.PROCESS, name -> !BIRDHOUSE.matcher(name).find(), null));
		}
	}

	private static final Pattern NOT_HARVEST = Pattern.compile(
		"seed$|seedling|sapling$|compost|^bucket|plant pot$|^weeds$|^watering can|^empty ");

	private SkillingRules()
	{
	}

	private static void gather(Skill skill, String... patterns)
	{
		Pattern p = Pattern.compile(String.join("|", patterns));
		RULES.put(skill, new Rule(Mode.GATHER, name -> p.matcher(name).find(), null));
	}

	private static boolean isHarvest(String name)
	{
		return !NOT_HARVEST.matcher(name).find();
	}

	static boolean countsAsIncome(Skill skill)
	{
		return RULES.containsKey(skill);
	}

	/**
	 * Works out the income from one tick's item changes.
	 *
	 * @param skills skills that gained XP this tick, most XP first
	 * @return the income, or null if none of the skills made money from these changes
	 */
	static Income evaluate(List<Skill> skills, List<Change> changes)
	{
		for (Skill skill : skills)
		{
			Rule rule = RULES.get(skill);
			if (rule == null)
			{
				continue;
			}
			Income income = apply(skill, rule, changes);
			if (income != null)
			{
				return income;
			}
		}
		return null;
	}

	private static Income apply(Skill skill, Rule rule, List<Change> changes)
	{
		List<Change> products = new ArrayList<>();
		long gained = 0;
		long used = 0;
		boolean consumed = false;
		boolean inputUsed = rule.getInput() == null;
		boolean excluded = false;
		for (Change c : changes)
		{
			String name = c.getName() == null ? "" : c.getName().toLowerCase(Locale.ENGLISH);
			long value = c.getUnitPrice() * Math.abs(c.getQuantity());
			if (c.getQuantity() > 0)
			{
				if (rule.getProduct().test(name))
				{
					products.add(c);
					gained += value;
				}
				else if (rule.getMode() == Mode.PROCESS)
				{
					excluded = true;
				}
			}
			else
			{
				used += value;
				consumed = true;
				inputUsed |= rule.getInput() != null && rule.getInput().test(name);
			}
		}
		if (products.isEmpty() || excluded || !inputUsed)
		{
			return null;
		}
		if (rule.getMode() == Mode.GATHER)
		{
			return new Income(skill, gained, products);
		}
		// Processing has to turn something into something worth having; gaining items alone isn't it.
		// Inputs that can't be sold (dark essence, guardian essence) are worth nothing but still count as used.
		return !consumed || gained == 0 ? null : new Income(skill, gained - used, products);
	}
}

package com.runejourney;

import com.runejourney.service.JourneyService;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Values the food and potions the player eats and drinks. An Eat or Drink click is matched to the
 * next inventory change that removes that item; whatever it leaves behind (a lower-dose potion,
 * half a pie, an empty vial) is deducted, so a potion costs one dose rather than the whole potion.
 * Must only be used on the client thread.
 */
@Singleton
class SupplyTracker
{
	/**
	 * Clicks are matched to inventory changes for this long; the server applies them a tick later.
	 */
	private static final int PENDING_TICKS = 3;
	private static final Pattern DOSE = Pattern.compile("\\s*\\(\\d\\)$");
	private static final String[] PORTION_PREFIXES = {"half a ", "half an ", "1/2 ", "2/3 ", "slice of "};
	private static final Set<String> CONTAINERS = Set.of("vial", "pie dish", "bowl", "jug", "empty cup",
		"beer glass", "cocktail glass", "empty gourd vial");

	private final ItemManager itemManager;
	private final JourneyService service;

	private Map<Integer, Integer> lastInventory;
	private final List<Pending> pending = new ArrayList<>();

	@Inject
	SupplyTracker(ItemManager itemManager, JourneyService service)
	{
		this.itemManager = itemManager;
		this.service = service;
	}

	void reset()
	{
		lastInventory = null;
		pending.clear();
	}

	void onMenuOptionClicked(String option, int itemId, int tick)
	{
		if (itemId <= 0 || option == null)
		{
			return;
		}
		String o = Text.removeTags(option);
		if (o.equalsIgnoreCase("Eat") || o.equalsIgnoreCase("Drink"))
		{
			pending.add(new Pending(itemManager.canonicalize(itemId), tick));
		}
	}

	/**
	 * Records anything eaten or drunk in this inventory change.
	 *
	 * @return the item quantity changes that were supplies being used, so they aren't also counted
	 * as skilling income
	 */
	Map<Integer, Integer> onInventory(ItemContainer container, int tick)
	{
		Map<Integer, Integer> now = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				now.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		Map<Integer, Integer> previous = lastInventory;
		lastInventory = now;
		pending.removeIf(p -> tick - p.tick > PENDING_TICKS);
		Map<Integer, Integer> used = new HashMap<>();
		if (previous == null || pending.isEmpty())
		{
			return used;
		}

		Map<Integer, Integer> delta = new HashMap<>();
		for (Map.Entry<Integer, Integer> e : now.entrySet())
		{
			delta.put(e.getKey(), e.getValue() - previous.getOrDefault(e.getKey(), 0));
		}
		for (Map.Entry<Integer, Integer> e : previous.entrySet())
		{
			delta.putIfAbsent(e.getKey(), -e.getValue());
		}

		for (Iterator<Pending> it = pending.iterator(); it.hasNext(); )
		{
			int id = it.next().itemId;
			if (delta.getOrDefault(id, 0) >= 0)
			{
				continue;
			}
			it.remove();
			delta.merge(id, 1, Integer::sum);
			used.merge(id, -1, Integer::sum);

			String name = name(id);
			long cost = itemManager.getItemPrice(id);
			for (Map.Entry<Integer, Integer> e : delta.entrySet())
			{
				if (e.getValue() > 0 && isLeftover(name, name(e.getKey())))
				{
					cost -= itemManager.getItemPrice(e.getKey());
					e.setValue(e.getValue() - 1);
					used.merge(e.getKey(), 1, Integer::sum);
					break;
				}
			}
			service.onSupplyUsed(supplyName(name), 1, Math.max(0, cost));
		}
		return used;
	}

	private String name(int id)
	{
		String name = itemManager.getItemComposition(id).getName();
		return name != null ? name : "";
	}

	/**
	 * Potions are grouped by name across doses ("Prayer potion"), food keeps its own name.
	 */
	static String supplyName(String itemName)
	{
		return DOSE.matcher(itemName).replaceFirst("");
	}

	/**
	 * Whether an item that appeared when something was eaten or drunk is what it left behind.
	 */
	static boolean isLeftover(String consumed, String gained)
	{
		String g = gained.toLowerCase(Locale.ENGLISH);
		return CONTAINERS.contains(g) || core(consumed).equals(core(gained));
	}

	/**
	 * "Prayer potion(3)" and "Prayer potion(4)" share "prayer potion"; "Half a summer pie" and
	 * "Summer pie" share "summer pie"; "2/3 cake" and "Slice of cake" share "cake".
	 */
	private static String core(String name)
	{
		String c = DOSE.matcher(name.toLowerCase(Locale.ENGLISH)).replaceFirst("");
		for (String prefix : PORTION_PREFIXES)
		{
			if (c.startsWith(prefix))
			{
				return c.substring(prefix.length());
			}
		}
		return c;
	}

	private static final class Pending
	{
		final int itemId;
		final int tick;

		Pending(int itemId, int tick)
		{
			this.itemId = itemId;
			this.tick = tick;
		}
	}
}

package com.runejourney;

import com.runejourney.service.JourneyService;
import java.util.Arrays;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemManager;

/**
 * Keeps a ledger of every item the account holds, per container, and values it at GE prices.
 *
 * Containers are read directly at the end of each tick rather than from change events: items
 * moving between the bank and equipment arrive as several events, and not every bank change
 * reliably produces one, which left the bank's value stale and counted gear twice. Reading the
 * containers once everything has settled always matches what the game shows.
 * Must only be used on the client thread.
 */
@Slf4j
@Singleton
class WealthTracker
{
	static final String GRAND_EXCHANGE = "grand exchange";
	static final String POTION_STORAGE = "potion storage";

	private static final Map<Integer, String> PARTS = new LinkedHashMap<>();

	static
	{
		PARTS.put(InventoryID.BANK, JourneyService.BANK);
		PARTS.put(InventoryID.INV, "inventory");
		PARTS.put(InventoryID.WORN, "equipment");
		PARTS.put(InventoryID.LOOTING_BAG, "looting bag");
		PARTS.put(InventoryID.SEED_VAULT, "seed vault");
	}

	private final Client client;
	private final ItemManager itemManager;
	private final JourneyService service;
	/**
	 * Container contents as last read, to skip re-pricing when nothing moved.
	 */
	private final Map<Integer, int[]> lastSeen = new HashMap<>();
	private long[] lastOffers;
	private Map<Integer, Integer> lastPotions;
	/**
	 * Set once the login has settled, so Grand Exchange offers and the potion store have arrived.
	 */
	private boolean ready;
	private boolean potionsDue;
	private boolean dirty;

	@Inject
	WealthTracker(Client client, ItemManager itemManager, JourneyService service)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.service = service;
	}

	/**
	 * Re-price everything on the next tick, e.g. after logging in with holdings from last time.
	 */
	void invalidate()
	{
		dirty = true;
		ready = true;
		potionsDue = true;
	}

	void reset()
	{
		lastSeen.clear();
		lastOffers = null;
		lastPotions = null;
		ready = false;
		potionsDue = false;
		dirty = false;
	}

	/**
	 * Call on every game tick while logged in. Containers the game hasn't sent this session (the
	 * bank before it's opened, an unchecked looting bag) keep what was saved last time.
	 */
	void onTick()
	{
		boolean bankOpen = client.getWidget(InterfaceID.Bankmain.ITEMS) != null;
		for (Map.Entry<Integer, String> part : PARTS.entrySet())
		{
			ItemContainer container = client.getItemContainer(part.getKey());
			if (container == null)
			{
				continue;
			}
			Item[] items = container.getItems();
			int[] contents = new int[items.length * 2];
			for (int i = 0; i < items.length; i++)
			{
				contents[i * 2] = items[i].getId();
				contents[i * 2 + 1] = items[i].getQuantity();
			}
			if (Arrays.equals(contents, lastSeen.get(part.getKey())))
			{
				continue;
			}
			lastSeen.put(part.getKey(), contents);
			Map<Integer, Integer> held = holdings(items);
			service.onHoldings(part.getValue(), held);
			if (part.getKey() == InventoryID.BANK || part.getKey() == InventoryID.INV)
			{
				long cash = held.getOrDefault(ItemID.COINS, 0) + held.getOrDefault(ItemID.PLATINUM, 0) * 1000L;
				service.onCash(part.getKey() == InventoryID.BANK, cash);
			}
			// Potions only go in or out of storage through the bank
			potionsDue |= bankOpen;
			dirty = true;
		}
		if (ready)
		{
			readOffers();
			if (potionsDue)
			{
				potionsDue = false;
				readPotionStorage(bankOpen);
			}
		}

		if (!dirty)
		{
			return;
		}
		dirty = false;
		Map<String, Long> values = new HashMap<>();
		service.holdings().forEach((part, held) -> values.put(part, value(held)));
		log.debug("Net worth parts: {}", values);
		service.onWealth(values);
	}

	private void readOffers()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		long[] contents = new long[offers.length * 6];
		for (int i = 0; i < offers.length; i++)
		{
			GrandExchangeOffer o = offers[i];
			if (o != null && o.getState() != GrandExchangeOfferState.EMPTY)
			{
				contents[i * 6] = o.getState().ordinal() + 1;
				contents[i * 6 + 1] = o.getItemId();
				contents[i * 6 + 2] = o.getTotalQuantity();
				contents[i * 6 + 3] = o.getQuantitySold();
				contents[i * 6 + 4] = o.getPrice();
				contents[i * 6 + 5] = o.getSpent();
			}
		}
		if (Arrays.equals(contents, lastOffers))
		{
			return;
		}
		lastOffers = contents;
		Map<Integer, Long> held = new HashMap<>();
		for (GrandExchangeOffer o : offers)
		{
			if (o == null || o.getState() == GrandExchangeOfferState.EMPTY || o.getItemId() <= 0)
			{
				continue;
			}
			GrandExchangeOfferState s = o.getState();
			boolean buy = s == GrandExchangeOfferState.BUYING || s == GrandExchangeOfferState.BOUGHT
				|| s == GrandExchangeOfferState.CANCELLED_BUY;
			addOffer(held, buy, itemManager.canonicalize(o.getItemId()), o.getTotalQuantity(), o.getQuantitySold(),
				o.getPrice(), o.getSpent());
		}
		service.onHoldings(GRAND_EXCHANGE, toHoldings(held));
		dirty = true;
	}

	/**
	 * Adds what one Grand Exchange offer holds: the coins or items still waiting to trade, plus
	 * what has traded so far. The game doesn't say what's been collected, so anything bought or
	 * sold is counted as still in the offer; that's only off if part of an offer is collected
	 * before it finishes.
	 */
	static void addOffer(Map<Integer, Long> held, boolean buy, int itemId, int total, int sold, long price,
		long spent)
	{
		if (buy)
		{
			// Coins not yet spent, including the change when items sell for less than offered
			held.merge(itemId, (long) sold, Long::sum);
			held.merge(ItemID.COINS, Math.max(0, total * price - spent), Long::sum);
		}
		else
		{
			held.merge(itemId, (long) Math.max(0, total - sold), Long::sum);
			held.merge(ItemID.COINS, spent, Long::sum);
		}
	}

	/**
	 * Coins can add up past what one stack holds across eight offers, so they're kept as platinum
	 * tokens plus change.
	 */
	static Map<Integer, Integer> toHoldings(Map<Integer, Long> held)
	{
		Map<Integer, Integer> out = new HashMap<>();
		held.forEach((id, qty) ->
		{
			if (id == ItemID.COINS)
			{
				out.merge(ItemID.PLATINUM, (int) Math.min(Integer.MAX_VALUE, qty / 1000), Integer::sum);
				out.merge(ItemID.COINS, (int) (qty % 1000), Integer::sum);
			}
			else
			{
				out.merge(id, (int) Math.min(Integer.MAX_VALUE, qty), Integer::sum);
			}
		});
		out.values().removeIf(q -> q <= 0);
		return out;
	}

	/**
	 * The bank's potion store keeps doses rather than potions; the game's own script counts them.
	 */
	private void readPotionStorage(boolean bankOpen)
	{
		Map<Integer, Integer> held = new HashMap<>();
		for (int list : new int[]{EnumID.POTIONSTORE_POTIONS, EnumID.POTIONSTORE_UNFINISHED_POTIONS})
		{
			for (int potionEnumId : client.getEnum(list).getIntVals())
			{
				EnumComposition potion = client.getEnum(potionEnumId);
				client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
				int doses = client.getIntStack()[0];
				int[] byDose = new int[5];
				for (int d = 1; d <= 4; d++)
				{
					byDose[d] = potion.getIntValue(d);
				}
				addDoses(held, doses, byDose);
			}
		}
		int vials = client.getVarpValue(VarPlayerID.POTIONSTORE_VIALS);
		if (vials > 0)
		{
			held.merge(ItemID.VIAL_EMPTY, vials, Integer::sum);
		}
		// An empty store outside the bank may just not have been sent yet; keep what was saved
		if ((held.isEmpty() && !bankOpen) || held.equals(lastPotions))
		{
			return;
		}
		lastPotions = held;
		service.onHoldings(POTION_STORAGE, held);
		dirty = true;
	}

	/**
	 * Stored doses as whole potions of the largest size, plus one potion holding what's left
	 * over: 7 doses of prayer potion are a Prayer potion(4) and a Prayer potion(3).
	 *
	 * @param byDose the item for each number of doses (indexes 1-4), or -1 where there isn't one
	 */
	static void addDoses(Map<Integer, Integer> held, int doses, int[] byDose)
	{
		int most = 0;
		for (int d = 1; d < byDose.length; d++)
		{
			if (byDose[d] > 0)
			{
				most = d;
			}
		}
		if (doses <= 0 || most == 0)
		{
			return;
		}
		if (doses >= most)
		{
			held.merge(byDose[most], doses / most, Integer::sum);
		}
		int rest = doses % most;
		if (rest > 0 && byDose[rest] > 0)
		{
			held.merge(byDose[rest], 1, Integer::sum);
		}
	}

	/**
	 * Real items only: bank placeholders and fillers mark empty slots, so they're skipped.
	 */
	private Map<Integer, Integer> holdings(Item[] items)
	{
		Map<Integer, Integer> held = new HashMap<>();
		for (Item item : items)
		{
			int id = item.getId();
			if (id <= 0 || item.getQuantity() <= 0 || id == ItemID.BANK_FILLER
				|| itemManager.getItemComposition(id).getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			held.merge(itemManager.canonicalize(id), item.getQuantity(), Integer::sum);
		}
		return held;
	}

	private long value(Map<Integer, Integer> items)
	{
		long total = 0;
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			total += unitPrice(e.getKey()) * e.getValue();
		}
		return total;
	}

	private long unitPrice(int id)
	{
		if (id == ItemID.COINS)
		{
			return 1;
		}
		if (id == ItemID.PLATINUM)
		{
			return 1000;
		}
		return itemManager.getItemPrice(id);
	}
}

