package com.runejourney.planner;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

public final class Skills
{
	/**
	 * All trainable skills, excluding the OVERALL pseudo-skill.
	 */
	@SuppressWarnings("deprecation")
	public static final List<Skill> ALL = Collections.unmodifiableList(Arrays.asList(
		Arrays.stream(Skill.values()).filter(s -> s != Skill.OVERALL).toArray(Skill[]::new)));

	public static final int MAX_TOTAL_LEVEL = ALL.size() * Experience.MAX_REAL_LEVEL;

	private Skills()
	{
	}

	public static Skill parse(String name)
	{
		if (name == null)
		{
			return null;
		}
		try
		{
			return Skill.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	public static long xp(Map<String, Long> xp, Skill skill)
	{
		Long v = xp.get(skill.name());
		return v == null ? 0 : v;
	}

	/**
	 * Real level (1-99) for an XP amount.
	 */
	public static int level(long xp)
	{
		return Math.min(Experience.MAX_REAL_LEVEL, Experience.getLevelForXp((int) Math.min(xp, Experience.MAX_SKILL_XP)));
	}

	public static int totalLevel(Map<String, Long> xp)
	{
		int total = 0;
		for (Skill s : ALL)
		{
			total += level(xp(xp, s));
		}
		return total;
	}

	public static long xpForLevel(int level)
	{
		return Experience.getXpForLevel(Math.max(1, Math.min(level, Experience.MAX_VIRT_LEVEL)));
	}
}

package com.runejourney.planner;

import lombok.Getter;

/**
 * A way of training a skill. XP/hr depends on the player's XP: {@code rates} is a list of
 * [xpThreshold, xpPerHour] steps, sorted by threshold, where each rate applies from its threshold onwards.
 */
public class TrainingMethod
{
	@Getter
	private String name;
	private long[][] rates;

	TrainingMethod()
	{
	}

	public TrainingMethod(String name, long[][] rates)
	{
		this.name = name;
		this.rates = rates;
	}

	public double rateAt(long xp)
	{
		double rate = rates[0][1];
		for (long[] step : rates)
		{
			if (xp >= step[0])
			{
				rate = step[1];
			}
		}
		return Math.max(1, rate);
	}

	/**
	 * Hours needed to go from one XP amount to another, following the rate steps.
	 */
	public double hours(long fromXp, long toXp)
	{
		double hours = 0;
		long xp = fromXp;
		while (xp < toXp)
		{
			long next = toXp;
			for (long[] step : rates)
			{
				if (step[0] > xp && step[0] < next)
				{
					next = step[0];
				}
			}
			hours += (next - xp) / rateAt(xp);
			xp = next;
		}
		return hours;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.runejourney.planner;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/**
 * Known training methods per skill, loaded from the bundled training_methods.json.
 */
@Slf4j
@Singleton
public class TrainingMethods
{
	private final Map<Skill, List<TrainingMethod>> methods = new EnumMap<>(Skill.class);

	@Inject
	public TrainingMethods(Gson gson)
	{
		try (InputStream in = TrainingMethods.class.getResourceAsStream("/com/runejourney/training_methods.json");
			Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			Map<String, List<TrainingMethod>> loaded = gson.fromJson(reader, new TypeToken<Map<String, List<TrainingMethod>>>()
			{
			}.getType());
			loaded.forEach((name, list) ->
			{
				Skill skill = Skills.parse(name);
				if (skill != null && list != null && !list.isEmpty())
				{
					methods.put(skill, Collections.unmodifiableList(list));
				}
			});
		}
		catch (Exception e)
		{
			log.warn("Unable to load RuneJourney training methods", e);
		}

		// Hitpoints is trained alongside combat; use a single flat estimate
		for (Skill s : Skills.ALL)
		{
			if (!methods.containsKey(s))
			{
				long rate = (long) XpRates.defaultRate(s, Intensity.BALANCED);
				methods.put(s, Collections.singletonList(new TrainingMethod(
					s == Skill.HITPOINTS ? "Alongside combat" : "Typical training", new long[][]{{0, rate}})));
			}
		}
	}

	public List<TrainingMethod> forSkill(Skill skill)
	{
		return methods.getOrDefault(skill, Collections.emptyList());
	}

	public TrainingMethod find(Skill skill, String name)
	{
		for (TrainingMethod m : forSkill(skill))
		{
			if (m.getName().equals(name))
			{
				return m;
			}
		}
		return null;
	}

	/**
	 * The method matching the player's preferred intensity: fastest, slowest, or the middle option,
	 * judged by the rate at their current XP.
	 */
	public TrainingMethod defaultFor(Skill skill, Intensity intensity, long xp)
	{
		List<TrainingMethod> sorted = new ArrayList<>(forSkill(skill));
		if (sorted.isEmpty())
		{
			return null;
		}
		sorted.sort(Comparator.comparingDouble((TrainingMethod m) -> m.rateAt(xp)).reversed());
		switch (intensity)
		{
			case EFFICIENT:
				return sorted.get(0);
			case RELAXED:
				return sorted.get(sorted.size() - 1);
			default:
				return sorted.get(sorted.size() / 2);
		}
	}
}

package com.runejourney.planner;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;

/**
 * Generic mid-to-high level XP/hr assumptions used until RuneJourney has observed the player's own rates.
 * These are deliberately rough; they only need to be in the right ballpark for weekly planning.
 */
public final class XpRates
{
	/**
	 * Observed rates are only trusted after this much active training time.
	 */
	public static final long MIN_OBSERVED_MILLIS = 30 * 60 * 1000L;

	private static final Map<Skill, int[]> RATES = new EnumMap<>(Skill.class);

	static
	{
		// efficient, balanced, relaxed (thousands of XP per hour)
		rate(Skill.ATTACK, 110, 80, 50);
		rate(Skill.STRENGTH, 120, 85, 55);
		rate(Skill.DEFENCE, 110, 80, 50);
		rate(Skill.HITPOINTS, 45, 32, 20);
		rate(Skill.RANGED, 200, 120, 70);
		rate(Skill.PRAYER, 500, 250, 90);
		rate(Skill.MAGIC, 250, 120, 70);
		rate(Skill.COOKING, 450, 250, 150);
		rate(Skill.WOODCUTTING, 150, 90, 60);
		rate(Skill.FLETCHING, 1000, 250, 150);
		rate(Skill.FISHING, 110, 70, 45);
		rate(Skill.FIREMAKING, 300, 200, 150);
		rate(Skill.CRAFTING, 350, 200, 120);
		rate(Skill.SMITHING, 300, 180, 100);
		rate(Skill.MINING, 110, 60, 35);
		rate(Skill.HERBLORE, 400, 250, 150);
		rate(Skill.AGILITY, 90, 65, 50);
		rate(Skill.THIEVING, 250, 150, 90);
		rate(Skill.SLAYER, 90, 60, 40);
		rate(Skill.FARMING, 150, 100, 60);
		rate(Skill.RUNECRAFT, 90, 60, 40);
		rate(Skill.HUNTER, 180, 120, 70);
		rate(Skill.CONSTRUCTION, 900, 450, 250);
		rate(Skill.SAILING, 80, 60, 40);
	}

	private XpRates()
	{
	}

	private static void rate(Skill skill, int efficient, int balanced, int relaxed)
	{
		RATES.put(skill, new int[]{efficient * 1000, balanced * 1000, relaxed * 1000});
	}

	public static double defaultRate(Skill skill, Intensity intensity)
	{
		int[] r = RATES.get(skill);
		if (r == null)
		{
			return 50_000;
		}
		return r[intensity.ordinal()];
	}
}

package com.runejourney.report;

import com.runejourney.model.DayRecord;
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.format.TextStyle;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Value;

/**
 * Turns daily records into chartable series and summary statistics. Pure, so it can be tested and
 * used for both the reports window and exported reports.
 */
public final class Analytics
{
	private Analytics()
	{
	}

	@Value
	public static class Bucket
	{
		LocalDate start;
		LocalDate end;
		String label;
		double value;
		double numerator;
		double hours;
		int activeDays;
	}

	@Value
	public static class Entry
	{
		String key;
		String label;
		double value;
	}

	@Value
	public static class Stats
	{
		double total;
		int activeDays;
		double perActiveDay;
		Bucket best;
		/**
		 * Total for the previous period of the same length, or NaN when there's no data for it.
		 */
		double previousTotal;

		/**
		 * Fractional change from the previous period, or NaN.
		 */
		public double change()
		{
			if (Double.isNaN(previousTotal) || previousTotal == 0)
			{
				return Double.NaN;
			}
			return (total - previousTotal) / Math.abs(previousTotal);
		}
	}

	/**
	 * The period of the same length immediately before {@code from}.
	 */
	public static LocalDate[] previousPeriod(LocalDate from, LocalDate to)
	{
		long days = ChronoUnit.DAYS.between(from, to) + 1;
		return new LocalDate[]{from.minusDays(days), from.minusDays(1)};
	}

	private static Map<LocalDate, DayRecord> byDate(List<DayRecord> days)
	{
		Map<LocalDate, DayRecord> map = new HashMap<>();
		for (DayRecord d : days)
		{
			map.put(LocalDate.parse(d.getDate()), d);
		}
		return map;
	}

	public static List<Bucket> series(List<DayRecord> days, LocalDate from, LocalDate to, Metric metric, String filter,
		Granularity granularity)
	{
		Granularity g = granularity.resolve(from, to);
		Map<LocalDate, DayRecord> map = byDate(days);
		if (metric.isBalance())
		{
			return balanceSeries(map, from, to, metric, g);
		}
		List<Bucket> buckets = new ArrayList<>();
		for (LocalDate start = g.bucketStart(from); !start.isAfter(to); start = g.next(start))
		{
			LocalDate end = g.next(start).minusDays(1);
			if (end.isAfter(to))
			{
				end = to;
			}
			double num = 0;
			double hours = 0;
			int active = 0;
			for (LocalDate d = start.isBefore(from) ? from : start; !d.isAfter(end); d = d.plusDays(1))
			{
				DayRecord r = map.get(d);
				if (r == null)
				{
					continue;
				}
				num += metric.value(r, filter);
				hours += Metric.hours(r);
				if (r.getPlayMillis() > 0)
				{
					active++;
				}
			}
			double value = metric.isPerHour() ? (hours > 0 ? num / hours : 0) : num;
			buckets.add(new Bucket(start, end, g.label(start), value, num, hours, active));
		}
		return buckets;
	}

	/**
	 * Each bucket shows the last balance recorded by its end, carried forward over days with no data.
	 */
	private static List<Bucket> balanceSeries(Map<LocalDate, DayRecord> map, LocalDate from, LocalDate to, Metric metric,
		Granularity g)
	{
		double last = Double.NaN;
		// Start from the latest balance before the range, if any
		LocalDate earliest = map.keySet().stream().min(LocalDate::compareTo).orElse(from);
		for (LocalDate d = earliest; d.isBefore(from); d = d.plusDays(1))
		{
			DayRecord r = map.get(d);
			if (r != null && !Double.isNaN(metric.balance(r)))
			{
				last = metric.balance(r);
			}
		}
		List<Bucket> buckets = new ArrayList<>();
		for (LocalDate start = g.bucketStart(from); !start.isAfter(to); start = g.next(start))
		{
			LocalDate end = g.next(start).minusDays(1);
			if (end.isAfter(to))
			{
				end = to;
			}
			double hours = 0;
			int active = 0;
			for (LocalDate d = start.isBefore(from) ? from : start; !d.isAfter(end); d = d.plusDays(1))
			{
				DayRecord r = map.get(d);
				if (r == null)
				{
					continue;
				}
				double v = metric.balance(r);
				if (!Double.isNaN(v))
				{
					last = v;
				}
				hours += Metric.hours(r);
				if (r.getPlayMillis() > 0)
				{
					active++;
				}
			}
			double value = Double.isNaN(last) ? 0 : last;
			buckets.add(new Bucket(start, end, g.label(start), value, value, hours, active));
		}
		return buckets;
	}

	/**
	 * Running total of a series (per-hour metrics are left as they are).
	 */
	public static List<Bucket> cumulative(List<Bucket> series, Metric metric)
	{
		if (metric.isPerHour() || metric.isBalance())
		{
			return series;
		}
		List<Bucket> out = new ArrayList<>();
		double sum = 0;
		for (Bucket b : series)
		{
			sum += b.getValue();
			out.add(new Bucket(b.getStart(), b.getEnd(), b.getLabel(), sum, b.getNumerator(), b.getHours(), b.getActiveDays()));
		}
		return out;
	}

	public static Stats stats(List<DayRecord> days, LocalDate from, LocalDate to, Metric metric, String filter,
		Granularity granularity, List<DayRecord> previousDays)
	{
		if (metric.isBalance())
		{
			return balanceStats(days, from, to, metric, granularity, previousDays);
		}
		double num = 0;
		double hours = 0;
		int active = 0;
		for (DayRecord r : days)
		{
			LocalDate d = LocalDate.parse(r.getDate());
			if (d.isBefore(from) || d.isAfter(to))
			{
				continue;
			}
			num += metric.value(r, filter);
			hours += Metric.hours(r);
			if (r.getPlayMillis() > 0)
			{
				active++;
			}
		}
		double total = metric.isPerHour() ? (hours > 0 ? num / hours : 0) : num;
		double perDay = metric.isPerHour() ? total : (active > 0 ? num / active : 0);

		Bucket best = null;
		for (Bucket b : series(days, from, to, metric, filter, granularity))
		{
			if (b.getValue() > 0 && (best == null || b.getValue() > best.getValue()))
			{
				best = b;
			}
		}

		double previous = Double.NaN;
		if (previousDays != null && !previousDays.isEmpty())
		{
			LocalDate[] prev = previousPeriod(from, to);
			Stats p = stats(previousDays, prev[0], prev[1], metric, filter, granularity, null);
			previous = p.getTotal();
		}
		return new Stats(total, active, perDay, best, previous);
	}

	/**
	 * For balances: "total" is the latest value, "per active day" is the change over the period, and
	 * the comparison is against where the previous period ended.
	 */
	private static Stats balanceStats(List<DayRecord> days, LocalDate from, LocalDate to, Metric metric,
		Granularity granularity, List<DayRecord> previousDays)
	{
		List<DayRecord> all = new ArrayList<>();
		if (previousDays != null)
		{
			all.addAll(previousDays);
		}
		all.addAll(days);
		List<Bucket> daily = series(all, from, to, metric, null, Granularity.DAY);
		double end = daily.isEmpty() ? 0 : daily.get(daily.size() - 1).getValue();
		double start = daily.stream().mapToDouble(Bucket::getValue).filter(v -> v > 0).findFirst().orElse(0);
		int active = (int) days.stream().filter(d -> d.getPlayMillis() > 0).count();
		Bucket best = null;
		for (Bucket b : series(all, from, to, metric, null, granularity))
		{
			if (b.getValue() > 0 && (best == null || b.getValue() > best.getValue()))
			{
				best = b;
			}
		}
		double previous = Double.NaN;
		if (previousDays != null && !previousDays.isEmpty())
		{
			LocalDate[] prev = previousPeriod(from, to);
			List<Bucket> p = series(previousDays, prev[0], prev[1], metric, null, Granularity.DAY);
			double v = p.isEmpty() ? 0 : p.get(p.size() - 1).getValue();
			previous = v > 0 ? v : Double.NaN;
		}
		return new Stats(end, active, end - start, best, previous);
	}

	/**
	 * Totals split by skill, boss or clue tier, largest first.
	 */
	public static List<Entry> breakdown(List<DayRecord> days, LocalDate from, LocalDate to, Metric metric)
	{
		Map<String, Double> totals = new LinkedHashMap<>();
		for (DayRecord r : days)
		{
			LocalDate d = LocalDate.parse(r.getDate());
			if (d.isBefore(from) || d.isAfter(to))
			{
				continue;
			}
			metric.parts(r).forEach((k, v) -> totals.merge(k, v, Double::sum));
		}
		List<Entry> entries = new ArrayList<>();
		totals.forEach((k, v) ->
		{
			if (v != 0)
			{
				entries.add(new Entry(k, k, v));
			}
		});
		entries.sort((a, b) -> Double.compare(b.getValue(), a.getValue()));
		return entries;
	}

	/**
	 * Average per day of the week, Monday first (per-hour metrics use the rate for that weekday).
	 */
	public static List<Entry> byWeekday(List<DayRecord> days, LocalDate from, LocalDate to, Metric metric, String filter)
	{
		double[] num = new double[7];
		double[] hours = new double[7];
		int[] occurrences = new int[7];
		for (LocalDate d = from; !d.isAfter(to); d = d.plusDays(1))
		{
			occurrences[d.getDayOfWeek().getValue() - 1]++;
		}
		Map<LocalDate, DayRecord> map = byDate(days);
		for (Map.Entry<LocalDate, DayRecord> e : map.entrySet())
		{
			LocalDate d = e.getKey();
			if (d.isBefore(from) || d.isAfter(to))
			{
				continue;
			}
			int i = d.getDayOfWeek().getValue() - 1;
			num[i] += metric.value(e.getValue(), filter);
			hours[i] += Metric.hours(e.getValue());
		}
		List<Entry> entries = new ArrayList<>();
		for (int i = 0; i < 7; i++)
		{
			String name = DayOfWeek.of(i + 1).getDisplayName(TextStyle.SHORT, Locale.ENGLISH);
			double v = metric.isPerHour() ? (hours[i] > 0 ? num[i] / hours[i] : 0) : (occurrences[i] > 0 ? num[i] / occurrences[i] : 0);
			entries.add(new Entry(name, name, v));
		}
		return entries;
	}

	/**
	 * Aligns the previous period's series to the current one bucket by bucket, for overlays.
	 */
	public static List<Bucket> previousSeries(List<DayRecord> previousDays, LocalDate from, LocalDate to, Metric metric,
		String filter, Granularity granularity)
	{
		LocalDate[] prev = previousPeriod(from, to);
		Granularity g = granularity.resolve(from, to);
		return series(previousDays, prev[0], prev[1], metric, filter, g);
	}
}

package com.runejourney.report;

/**
 * Axis helpers shared by the Swing and SVG charts.
 */
public final class ChartMath
{
	private ChartMath()
	{
	}

	/**
	 * A "nice" step for about {@code ticks} gridlines up to {@code max}: 1, 2 or 5 times a power of ten.
	 */
	public static double niceStep(double max, int ticks)
	{
		if (max <= 0)
		{
			return 1;
		}
		double raw = max / ticks;
		double magnitude = Math.pow(10, Math.floor(Math.log10(raw)));
		double residual = raw / magnitude;
		double nice = residual > 5 ? 10 : residual > 2 ? 5 : residual > 1 ? 2 : 1;
		return nice * magnitude;
	}

	public static double niceMax(double max, int ticks)
	{
		double step = niceStep(max, ticks);
		return Math.max(step, Math.ceil(max / step) * step);
	}

	/**
	 * Show every n-th x label so that at most {@code maxLabels} are drawn.
	 */
	public static int labelEvery(int count, int maxLabels)
	{
		return Math.max(1, (int) Math.ceil(count / (double) Math.max(1, maxLabels)));
	}
}

package com.runejourney.report;

import com.runejourney.model.DayRecord;
import com.runejourney.model.LootSource;
import com.runejourney.planner.Skills;
import java.time.LocalDate;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeSet;
import net.runelite.api.Skill;

/**
 * One row per day with every tracked metric, plus per-skill XP, per-boss kills and loot per source, for spreadsheets.
 */
public final class CsvExport
{
	private static final Metric[] COLUMNS = {
		Metric.PLAYTIME, Metric.XP, Metric.LEVELS, Metric.INCOME, Metric.LOOT, Metric.SKILLING_INCOME, Metric.SUPPLIES,
		Metric.PROFIT, Metric.KILLS, Metric.CLUES, Metric.CLUE_LOOT, Metric.COLLECTION_LOG, Metric.COMBAT_TASKS,
		Metric.CA_POINTS, Metric.QUESTS, Metric.PERSONAL_BESTS, Metric.PETS, Metric.SLAYER_TASKS, Metric.DEATHS,
		Metric.NET_WORTH,
	};

	private CsvExport()
	{
	}

	public static String export(List<DayRecord> days, LocalDate from, LocalDate to)
	{
		TreeSet<String> bosses = new TreeSet<>();
		TreeSet<String> skills = new TreeSet<>();
		TreeSet<String> sources = new TreeSet<>();
		for (DayRecord d : days)
		{
			bosses.addAll(d.getBossKills().keySet());
			skills.addAll(d.getSkillXp().keySet());
			sources.addAll(d.getLootBySource().keySet());
		}

		StringBuilder sb = new StringBuilder();
		sb.append("Date");
		for (Metric m : COLUMNS)
		{
			sb.append(',').append(quote(m.getLabel() + (m.getUnit() == Unit.HOURS ? " (hours)" : "")));
		}
		for (Skill s : Skills.ALL)
		{
			if (skills.contains(s.name()))
			{
				sb.append(',').append(quote(s.getName() + " XP"));
			}
		}
		for (String b : bosses)
		{
			sb.append(',').append(quote(b + " kills"));
		}
		for (String s : sources)
		{
			sb.append(',').append(quote(s + " loot"));
		}
		sb.append('\n');

		Map<String, DayRecord> byDate = new java.util.HashMap<>();
		for (DayRecord d : days)
		{
			byDate.put(d.getDate(), d);
		}
		DayRecord empty = new DayRecord();
		for (LocalDate date = from; !date.isAfter(to); date = date.plusDays(1))
		{
			DayRecord d = byDate.getOrDefault(date.toString(), empty);
			sb.append(date);
			for (Metric m : COLUMNS)
			{
				double v = m.value(d, null);
				sb.append(',').append(m.getUnit() == Unit.HOURS ? String.format(Locale.ENGLISH, "%.2f", v) : String.valueOf(Math.round(v)));
			}
			for (Skill s : Skills.ALL)
			{
				if (skills.contains(s.name()))
				{
					sb.append(',').append(d.getSkillXp().getOrDefault(s.name(), 0L));
				}
			}
			for (String b : bosses)
			{
				sb.append(',').append(d.getBossKills().getOrDefault(b, 0));
			}
			for (String s : sources)
			{
				LootSource loot = d.getLootBySource().get(s);
				sb.append(',').append(loot == null ? 0 : loot.getValue());
			}
			sb.append('\n');
		}
		return sb.toString();
	}

	private static String quote(String s)
	{
		return "\"" + s.replace("\"", "\"\"") + "\"";
	}
}

package com.runejourney.report;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;
import java.time.temporal.TemporalAdjusters;
import java.util.Locale;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum Granularity
{
	AUTO("Automatic"),
	DAY("Day"),
	WEEK("Week"),
	MONTH("Month");

	private static final DateTimeFormatter DAY_LABEL = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter MONTH_LABEL = DateTimeFormatter.ofPattern("MMM yy", Locale.ENGLISH);

	private final String label;

	@Override
	public String toString()
	{
		return label;
	}

	/**
	 * Picks a bucket size that gives a readable number of points for the range.
	 */
	public Granularity resolve(LocalDate from, LocalDate to)
	{
		if (this != AUTO)
		{
			return this;
		}
		long days = ChronoUnit.DAYS.between(from, to) + 1;
		if (days <= 45)
		{
			return DAY;
		}
		return days <= 200 ? WEEK : MONTH;
	}

	public LocalDate bucketStart(LocalDate d)
	{
		switch (this)
		{
			case WEEK:
				return d.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));
			case MONTH:
				return d.withDayOfMonth(1);
			default:
				return d;
		}
	}

	public LocalDate next(LocalDate start)
	{
		switch (this)
		{
			case WEEK:
				return start.plusWeeks(1);
			case MONTH:
				return start.plusMonths(1);
			default:
				return start.plusDays(1);
		}
	}

	public String label(LocalDate start)
	{
		switch (this)
		{
			case WEEK:
				return "w/c " + start.format(DAY_LABEL);
			case MONTH:
				return start.format(MONTH_LABEL);
			default:
				return start.format(DAY_LABEL);
		}
	}

	/**
	 * Singular noun for "best day/week/month".
	 */
	public String noun()
	{
		return name().toLowerCase(Locale.ENGLISH);
	}
}

package com.runejourney.report;

import com.runejourney.model.DayRecord;
import com.runejourney.model.ItemTotal;
import com.runejourney.model.LootSource;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.ToDoubleFunction;
import lombok.Value;

/**
 * Which bosses and activities earned the most loot over a period. Loot only: supplies aren't
 * recorded per activity, so this is before supplies.
 */
public final class LootReport
{
	@Value
	public static class Row
	{
		String source;
		/**
		 * Kills, reward claims, caskets opened...
		 */
		int times;
		long total;
		double perTime;
		/**
		 * Fraction of all loot in the period.
		 */
		double share;
		/**
		 * GP per hour from the player's own kill times, or NaN when there aren't enough timed kills.
		 */
		double gpPerHour;
		/**
		 * Loot from this source in the previous period of the same length.
		 */
		long previousTotal;
		String bestItem;
		long bestItemValue;
		/**
		 * Every item it gave in the period, for searching.
		 */
		Map<String, ItemTotal> items;
	}

	/**
	 * One item's share of a source's loot.
	 */
	@Value
	public static class ItemRow
	{
		String name;
		long quantity;
		long value;
		/**
		 * Average value per kill or trip.
		 */
		double perTime;
		/**
		 * Fraction of the source's loot.
		 */
		double share;
	}

	/**
	 * Everything one source paid out over some days.
	 */
	@Value
	public static class SourceDetail
	{
		String source;
		long total;
		int times;
		/**
		 * First and last days it paid out, or null if it never did in these days.
		 */
		String firstDay;
		String lastDay;
		/**
		 * Most valuable first.
		 */
		List<ItemRow> items;
	}

	private LootReport()
	{
	}

	public static SourceDetail detail(List<DayRecord> days, String source)
	{
		LootSource combined = new LootSource();
		String first = null;
		String last = null;
		for (DayRecord d : days)
		{
			LootSource s = d.getLootBySource().get(source);
			if (s == null || (s.getTimes() == 0 && s.getValue() == 0))
			{
				continue;
			}
			combined.add(s);
			if (first == null || d.getDate().compareTo(first) < 0)
			{
				first = d.getDate();
			}
			if (last == null || d.getDate().compareTo(last) > 0)
			{
				last = d.getDate();
			}
		}
		List<ItemRow> items = new ArrayList<>();
		for (Map.Entry<String, ItemTotal> e : combined.getItems().entrySet())
		{
			ItemTotal t = e.getValue();
			items.add(new ItemRow(e.getKey(), t.getQuantity(), t.getValue(),
				combined.getTimes() > 0 ? (double) t.getValue() / combined.getTimes() : t.getValue(),
				combined.getValue() > 0 ? (double) t.getValue() / combined.getValue() : 0));
		}
		// Most valuable first; worthless items (pearls, untradeables) by how many
		items.sort((a, b) -> a.getValue() != b.getValue() ? Long.compare(b.getValue(), a.getValue())
			: Long.compare(b.getQuantity(), a.getQuantity()));
		return new SourceDetail(source, combined.getValue(), combined.getTimes(), first, last, items);
	}

	/**
	 * @param minutesPerKill the player's own average minutes per kill for a source, or NaN / <= 0
	 * when it isn't known
	 * @return one row per source that paid out, most loot first
	 */
	public static List<Row> build(List<DayRecord> days, List<DayRecord> previousDays, ToDoubleFunction<String> minutesPerKill)
	{
		Map<String, LootSource> current = combine(days);
		Map<String, LootSource> previous = combine(previousDays);
		long all = current.values().stream().mapToLong(LootSource::getValue).filter(v -> v > 0).sum();

		List<Row> rows = new ArrayList<>();
		for (Map.Entry<String, LootSource> e : current.entrySet())
		{
			LootSource s = e.getValue();
			if (s.getValue() <= 0)
			{
				continue;
			}
			double perTime = s.getTimes() > 0 ? (double) s.getValue() / s.getTimes() : s.getValue();
			double minutes = minutesPerKill.applyAsDouble(e.getKey());
			double gpPerHour = minutes > 0 ? perTime * 60 / minutes : Double.NaN;

			String bestItem = null;
			long bestValue = 0;
			for (Map.Entry<String, ItemTotal> item : s.getItems().entrySet())
			{
				if (item.getValue().getValue() > bestValue)
				{
					bestItem = item.getKey();
					bestValue = item.getValue().getValue();
				}
			}

			LootSource before = previous.get(e.getKey());
			rows.add(new Row(e.getKey(), s.getTimes(), s.getValue(), perTime, all > 0 ? (double) s.getValue() / all : 0,
				gpPerHour, before == null ? 0 : before.getValue(), bestItem, bestValue, s.getItems()));
		}
		rows.sort((a, b) -> Long.compare(b.getTotal(), a.getTotal()));
		return rows;
	}

	/**
	 * How a source matched a search.
	 */
	@Value
	public static class Match
	{
		/**
		 * The source's own name matched, so all its items are relevant.
		 */
		boolean bySource;
		/**
		 * Items whose names matched, most valuable first.
		 */
		List<String> items;
	}

	/**
	 * Matches a source by its name or the names of items it gave, ignoring case.
	 *
	 * @return null if neither matches; any match for a blank search
	 */
	public static Match match(Row row, String search)
	{
		String q = search == null ? "" : search.trim().toLowerCase(Locale.ENGLISH);
		if (q.isEmpty() || row.getSource().toLowerCase(Locale.ENGLISH).contains(q))
		{
			return new Match(true, new ArrayList<>());
		}
		List<String> items = new ArrayList<>();
		row.getItems().entrySet().stream()
			.filter(e -> e.getKey().toLowerCase(Locale.ENGLISH).contains(q))
			.sorted((a, b) -> Long.compare(b.getValue().getValue(), a.getValue().getValue()))
			.forEach(e -> items.add(e.getKey()));
		return items.isEmpty() ? null : new Match(false, items);
	}

	/**
	 * Whether an item belongs in a search's results.
	 */
	public static boolean itemMatches(String item, String search)
	{
		String q = search == null ? "" : search.trim().toLowerCase(Locale.ENGLISH);
		return q.isEmpty() || item.toLowerCase(Locale.ENGLISH).contains(q);
	}

	private static Map<String, LootSource> combine(List<DayRecord> days)
	{
		Map<String, LootSource> sources = new HashMap<>();
		for (DayRecord d : days)
		{
			d.getLootBySource().forEach((k, v) -> sources.computeIfAbsent(k, x -> new LootSource()).add(v));
		}
		return sources;
	}
}

package com.runejourney.report;

import com.runejourney.model.DayRecord;
import com.runejourney.model.EventType;
import com.runejourney.model.LootSource;
import com.runejourney.planner.Counters;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Something that can be charted over time from daily records.
 */
@Getter
@RequiredArgsConstructor
public enum Metric
{
	XP("XP gained", Unit.COUNT, Filter.SKILL, false, EnumSet.of(EventType.LEVEL, EventType.XP_MILESTONE, EventType.TOTAL_LEVEL)),
	PLAYTIME("Time played", Unit.HOURS, Filter.NONE, false, EnumSet.of(EventType.RECORD, EventType.SESSION)),
	LEVELS("Levels gained", Unit.COUNT, Filter.NONE, false, EnumSet.of(EventType.LEVEL, EventType.TOTAL_LEVEL)),
	NET_WORTH("Net worth", Unit.GP, Filter.NONE, false, EnumSet.of(EventType.RECORD)),
	INCOME("Total income", Unit.GP, Filter.NONE, false, EnumSet.of(EventType.DROP, EventType.CLUE)),
	LOOT("Loot value", Unit.GP, Filter.SOURCE, false, EnumSet.of(EventType.DROP, EventType.CLUE, EventType.PET)),
	SKILLING_INCOME("Skilling income", Unit.GP, Filter.SKILL, false, EnumSet.noneOf(EventType.class)),
	SUPPLIES("Supplies used", Unit.GP, Filter.NONE, false, EnumSet.noneOf(EventType.class)),
	PROFIT("Profit after supplies", Unit.GP, Filter.NONE, false, EnumSet.of(EventType.DROP, EventType.CLUE)),
	KILLS("Boss kills", Unit.COUNT, Filter.BOSS, false, EnumSet.of(EventType.BOSS_KC, EventType.PERSONAL_BEST)),
	CLUES("Clues completed", Unit.COUNT, Filter.CLUE_TIER, false, EnumSet.of(EventType.CLUE)),
	CLUE_LOOT("Clue loot", Unit.GP, Filter.NONE, false, EnumSet.of(EventType.CLUE)),
	COLLECTION_LOG("Collection log slots", Unit.COUNT, Filter.NONE, false, EnumSet.of(EventType.COLLECTION_LOG)),
	COMBAT_TASKS("Combat tasks", Unit.COUNT, Filter.NONE, false, EnumSet.of(EventType.COMBAT_TASK)),
	CA_POINTS("CA points earned", Unit.COUNT, Filter.NONE, false, EnumSet.of(EventType.COMBAT_TASK)),
	QUESTS("Quests completed", Unit.COUNT, Filter.NONE, false, EnumSet.of(EventType.QUEST, EventType.DIARY)),
	PERSONAL_BESTS("Personal bests", Unit.COUNT, Filter.NONE, false, EnumSet.of(EventType.PERSONAL_BEST)),
	PETS("Pets", Unit.COUNT, Filter.NONE, false, EnumSet.of(EventType.PET)),
	SLAYER_TASKS("Slayer tasks", Unit.COUNT, Filter.NONE, false, EnumSet.noneOf(EventType.class)),
	DEATHS("Deaths", Unit.COUNT, Filter.NONE, false, EnumSet.of(EventType.DEATH)),
	XP_PER_HOUR("XP per hour played", Unit.RATE, Filter.SKILL, true, EnumSet.of(EventType.SESSION)),
	GP_PER_HOUR("Income per hour played", Unit.RATE, Filter.NONE, true, EnumSet.of(EventType.DROP)),
	KILLS_PER_HOUR("Kills per hour played", Unit.RATE, Filter.BOSS, true, EnumSet.of(EventType.BOSS_KC));

	/**
	 * What a metric can be narrowed down to.
	 */
	public enum Filter
	{
		NONE, SKILL, BOSS, CLUE_TIER, SOURCE
	}

	private final String label;
	private final Unit unit;
	private final Filter filter;
	/**
	 * Per-hour metrics: the value is the metric divided by hours played.
	 */
	private final boolean perHour;
	/**
	 * Journey events worth listing alongside this metric.
	 */
	private final Set<EventType> relatedEvents;

	@Override
	public String toString()
	{
		return label;
	}

	/**
	 * Balances such as net worth: a period's value is where it ended, not the sum of its days.
	 */
	public boolean isBalance()
	{
		return this == NET_WORTH;
	}

	/**
	 * End-of-day balance, or NaN when it wasn't recorded that day.
	 */
	public double balance(DayRecord d)
	{
		Long v = d.getSnapshot().get(Counters.WEALTH);
		return v == null || v <= 0 ? Double.NaN : v;
	}

	/**
	 * The raw daily amount; for per-hour metrics, the numerator.
	 */
	public double value(DayRecord d, String filter)
	{
		switch (this)
		{
			case XP:
				return filter == null ? d.getXpGained() : d.getSkillXp().getOrDefault(filter, 0L);
			case XP_PER_HOUR:
				// XP gained on other devices has no matching play time here
				if (filter == null)
				{
					return d.getXpGained() - d.getOfflineXp();
				}
				return d.getSkillXp().getOrDefault(filter, 0L) - d.getOfflineSkillXp().getOrDefault(filter, 0L);
			case INCOME:
			case GP_PER_HOUR:
				return d.getLootValue() + d.getSkillingIncome();
			case SKILLING_INCOME:
				return filter == null ? d.getSkillingIncome() : d.getSkillingIncomeBySkill().getOrDefault(filter, 0L);
			case PLAYTIME:
				return hours(d);
			case LEVELS:
				return d.getLevelsGained();
			case LOOT:
				if (filter != null)
				{
					LootSource s = d.getLootBySource().get(filter);
					return s == null ? 0 : s.getValue();
				}
				return d.getLootValue();
			case SUPPLIES:
				return d.getSuppliesCost();
			case PROFIT:
				return d.getLootValue() + d.getSkillingIncome() - d.getSuppliesCost();
			case KILLS:
			case KILLS_PER_HOUR:
				if (filter != null)
				{
					return d.getBossKills().getOrDefault(filter, 0);
				}
				return d.getBossKills().values().stream().mapToInt(Integer::intValue).sum();
			case CLUES:
				return filter == null ? d.getCluesCompleted() : d.getClues().getOrDefault(filter, 0);
			case CLUE_LOOT:
				return d.getClueLootValue();
			case COLLECTION_LOG:
				return d.getCollectionLogSlots();
			case COMBAT_TASKS:
				return d.getCombatTasks();
			case CA_POINTS:
				return d.getCombatTaskPoints();
			case QUESTS:
				return d.getQuestsCompleted();
			case PERSONAL_BESTS:
				return d.getPersonalBests();
			case PETS:
				return d.getPets();
			case SLAYER_TASKS:
				return d.getSlayerTasks();
			case DEATHS:
				return d.getDeaths();
			case NET_WORTH:
			{
				double v = balance(d);
				return Double.isNaN(v) ? 0 : v;
			}
			default:
				return 0;
		}
	}

	public static double hours(DayRecord d)
	{
		return d.getPlayMillis() / 3_600_000d;
	}

	/**
	 * The day's amounts split by skill, boss or clue tier, for metrics that support it.
	 */
	public Map<String, Double> parts(DayRecord d)
	{
		Map<String, Double> parts = new HashMap<>();
		switch (filter)
		{
			case SKILL:
				Map<String, Long> source = this == SKILLING_INCOME ? d.getSkillingIncomeBySkill() : d.getSkillXp();
				source.forEach((k, v) -> parts.put(k, v.doubleValue()));
				return parts;
			case BOSS:
				d.getBossKills().forEach((k, v) -> parts.put(k, v.doubleValue()));
				return parts;
			case CLUE_TIER:
				d.getClues().forEach((k, v) -> parts.put(k, v.doubleValue()));
				return parts;
			case SOURCE:
				d.getLootBySource().forEach((k, v) -> parts.put(k, (double) v.getValue()));
				return parts;
			default:
				return Collections.emptyMap();
		}
	}
}

package com.runejourney.report;

import java.util.List;
import java.util.Locale;

/**
 * Inline SVG charts for exported HTML reports. Hovering a bar or point shows its value.
 */
public final class SvgCharts
{
	private static final int W = 900;
	private static final int H = 260;
	private static final int LEFT = 58;
	private static final int RIGHT = 12;
	private static final int TOP = 14;
	private static final int BOTTOM = 30;
	private static final String GRID = "#3a3226";
	private static final String AXIS_TEXT = "#a79d8b";
	private static final String COMPARE = "#8a8170";

	private SvgCharts()
	{
	}

	public static String timeSeries(List<Analytics.Bucket> series, List<Analytics.Bucket> compare, Unit unit, String color, boolean line)
	{
		StringBuilder s = new StringBuilder();
		s.append("<svg class=\"chart\" viewBox=\"0 0 ").append(W).append(' ').append(H)
			.append("\" preserveAspectRatio=\"none\" role=\"img\">");
		if (series.isEmpty())
		{
			return s.append("</svg>").toString();
		}

		double max = 0;
		for (Analytics.Bucket b : series)
		{
			max = Math.max(max, b.getValue());
		}
		if (compare != null)
		{
			for (Analytics.Bucket b : compare)
			{
				max = Math.max(max, b.getValue());
			}
		}
		double step = ChartMath.niceStep(max, 4);
		double top = ChartMath.niceMax(max, 4);
		int plotW = W - LEFT - RIGHT;
		int plotH = H - TOP - BOTTOM;

		for (double v = 0; v <= top + step / 2; v += step)
		{
			double y = TOP + plotH - v / top * plotH;
			s.append("<line x1=\"").append(LEFT).append("\" x2=\"").append(W - RIGHT).append("\" y1=\"").append(f(y))
				.append("\" y2=\"").append(f(y)).append("\" stroke=\"").append(GRID).append("\"/>");
			s.append("<text x=\"").append(LEFT - 6).append("\" y=\"").append(f(y + 4)).append("\" text-anchor=\"end\" fill=\"")
				.append(AXIS_TEXT).append("\" font-size=\"11\">").append(esc(unit.axis(v))).append("</text>");
		}

		int n = series.size();
		double slot = plotW / (double) n;
		int every = ChartMath.labelEvery(n, 12);
		for (int i = 0; i < n; i++)
		{
			if (i % every == 0)
			{
				double x = LEFT + slot * i + slot / 2;
				s.append("<text x=\"").append(f(x)).append("\" y=\"").append(H - 10).append("\" text-anchor=\"middle\" fill=\"")
					.append(AXIS_TEXT).append("\" font-size=\"11\">").append(esc(series.get(i).getLabel())).append("</text>");
			}
		}

		if (compare != null && !compare.isEmpty())
		{
			s.append("<polyline fill=\"none\" stroke=\"").append(COMPARE).append("\" stroke-width=\"2\" stroke-dasharray=\"5 4\" points=\"");
			for (int i = 0; i < Math.min(n, compare.size()); i++)
			{
				double x = LEFT + slot * i + slot / 2;
				double y = TOP + plotH - compare.get(i).getValue() / top * plotH;
				s.append(f(x)).append(',').append(f(y)).append(' ');
			}
			s.append("\"/>");
		}

		if (line)
		{
			s.append("<polyline fill=\"none\" stroke=\"").append(color).append("\" stroke-width=\"2.5\" points=\"");
			for (int i = 0; i < n; i++)
			{
				double x = LEFT + slot * i + slot / 2;
				double y = TOP + plotH - series.get(i).getValue() / top * plotH;
				s.append(f(x)).append(',').append(f(y)).append(' ');
			}
			s.append("\"/>");
			for (int i = 0; i < n; i++)
			{
				Analytics.Bucket b = series.get(i);
				double x = LEFT + slot * i + slot / 2;
				double y = TOP + plotH - b.getValue() / top * plotH;
				s.append("<circle cx=\"").append(f(x)).append("\" cy=\"").append(f(y)).append("\" r=\"").append(n > 60 ? 2 : 3.5)
					.append("\" fill=\"").append(color).append("\"><title>").append(esc(tooltip(b, compare, i, unit)))
					.append("</title></circle>");
			}
		}
		else
		{
			double barW = Math.max(1, slot * 0.72);
			for (int i = 0; i < n; i++)
			{
				Analytics.Bucket b = series.get(i);
				double h = b.getValue() / top * plotH;
				double x = LEFT + slot * i + (slot - barW) / 2;
				s.append("<rect x=\"").append(f(x)).append("\" y=\"").append(f(TOP + plotH - h)).append("\" width=\"").append(f(barW))
					.append("\" height=\"").append(f(Math.max(0, h))).append("\" rx=\"2\" fill=\"").append(color).append("\"><title>")
					.append(esc(tooltip(b, compare, i, unit))).append("</title></rect>");
			}
		}
		return s.append("</svg>").toString();
	}

	private static String tooltip(Analytics.Bucket b, List<Analytics.Bucket> compare, int i, Unit unit)
	{
		String t = b.getLabel() + ": " + unit.format(b.getValue());
		if (compare != null && i < compare.size())
		{
			t += " (previous: " + unit.format(compare.get(i).getValue()) + ")";
		}
		return t;
	}

	/**
	 * Horizontal bars, largest first.
	 */
	public static String bars(List<Analytics.Entry> entries, Unit unit, String color, int maxRows)
	{
		int rows = Math.min(maxRows, entries.size());
		int rowH = 24;
		int labelW = 170;
		int valueW = 90;
		int height = Math.max(rowH, rows * rowH + 6);
		StringBuilder s = new StringBuilder();
		s.append("<svg class=\"bars\" viewBox=\"0 0 ").append(W).append(' ').append(height).append("\" role=\"img\">");
		double max = 0;
		for (int i = 0; i < rows; i++)
		{
			max = Math.max(max, entries.get(i).getValue());
		}
		double barSpace = W - labelW - valueW - 12;
		for (int i = 0; i < rows; i++)
		{
			Analytics.Entry e = entries.get(i);
			double y = i * rowH + 4;
			double w = max <= 0 ? 0 : Math.max(2, e.getValue() / max * barSpace);
			s.append("<text x=\"").append(labelW - 8).append("\" y=\"").append(f(y + 15)).append("\" text-anchor=\"end\" fill=\"#ece4d4\" font-size=\"13\">")
				.append(esc(e.getLabel())).append("</text>");
			s.append("<rect x=\"").append(labelW).append("\" y=\"").append(f(y + 3)).append("\" width=\"").append(f(w))
				.append("\" height=\"16\" rx=\"3\" fill=\"").append(color).append("\"><title>").append(esc(e.getLabel() + ": " + unit.format(e.getValue())))
				.append("</title></rect>");
			s.append("<text x=\"").append(f(labelW + w + 8)).append("\" y=\"").append(f(y + 15)).append("\" fill=\"").append(AXIS_TEXT)
				.append("\" font-size=\"12\">").append(esc(unit.format(e.getValue()))).append("</text>");
		}
		return s.append("</svg>").toString();
	}

	private static String f(double v)
	{
		return String.format(Locale.ENGLISH, "%.1f", v);
	}

	private static String esc(String s)
	{
		return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
	}
}

package com.runejourney.report;

import com.runejourney.util.Format;
import java.util.Locale;

/**
 * How a metric's values are displayed.
 */
public enum Unit
{
	COUNT,
	GP,
	HOURS,
	RATE;

	public String format(double v)
	{
		switch (this)
		{
			case GP:
				return Format.compact(Math.round(v)) + " gp";
			case HOURS:
				return v <= 0 ? "0 min" : Format.hours(v);
			case RATE:
				return Format.compact(Math.round(v)) + "/hr";
			default:
				if (v != Math.floor(v) && Math.abs(v) < 100)
				{
					return String.format(Locale.ENGLISH, "%.1f", v);
				}
				return Format.compact(Math.round(v));
		}
	}

	/**
	 * Shorter form for chart axes.
	 */
	public String axis(double v)
	{
		switch (this)
		{
			case HOURS:
				return v == Math.floor(v) ? (long) v + "h" : String.format(Locale.ENGLISH, "%.1fh", v);
			case GP:
			case RATE:
			default:
				if (v != Math.floor(v) && Math.abs(v) < 10)
				{
					return String.format(Locale.ENGLISH, "%.1f", v);
				}
				return Format.compact(Math.round(v));
		}
	}
}

package com.runejourney.service;

import com.runejourney.model.DayRecord;
import com.runejourney.model.EventType;
import com.runejourney.model.JourneyEvent;
import com.runejourney.planner.Skills;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;

/**
 * XP gained while RuneJourney wasn't running, e.g. on mobile. The game only shows the new totals at
 * login, so all that's known is that it was gained between the last XP RuneJourney saw and now. A
 * gap that's all today is today's XP; one that began on an earlier day is kept aside rather than
 * landing on today, and only counted by ranges covering the whole gap.
 */
final class AwayXp
{
	static final String NOTE_PREFIX = "While you were away";
	static final String LEVEL_SUFFIX = "(gained while away)";
	private static final long LOGIN_MILLIS = 10_000;

	private AwayXp()
	{
	}

	/**
	 * The first day XP found at login could have been gained.
	 *
	 * @param lastXpAt when RuneJourney last read the player's XP, or 0 if it was never saved
	 */
	static LocalDate windowStart(long lastXpAt, NavigableMap<String, DayRecord> days, LocalDate today)
	{
		if (lastXpAt > 0)
		{
			return Instant.ofEpochMilli(lastXpAt).atZone(ZoneId.systemDefault()).toLocalDate();
		}
		// Saved before this was tracked: the last day anything was played
		DayRecord last = lastPlayed(days, today, true);
		return last == null ? today : LocalDate.parse(last.getDate());
	}

	/**
	 * Whether a range starting on {@code from} covers the whole gap the day's away XP was gained in.
	 * Ranges are only ever asked about days up to their end, so only the start needs checking.
	 */
	static boolean counted(DayRecord day, LocalDate from)
	{
		return day.getAwayFrom() != null && day.getAwayFrom().compareTo(from.toString()) >= 0;
	}

	/**
	 * Days saved before away XP was kept aside have it added to the day of the login that found it.
	 * Moves it back out where the day shows that's what it was: a single "while you were away" note
	 * that came before anything else that day, with the previous play on an earlier day.
	 *
	 * @return whether the day changed
	 */
	static boolean migrate(DayRecord day, NavigableMap<String, DayRecord> days)
	{
		if (day.getOfflineXp() <= 0 || day.getAwayFrom() != null)
		{
			return false;
		}
		JourneyEvent note = null;
		for (JourneyEvent e : day.getEvents())
		{
			if (e.getType() == EventType.NOTE && e.getTitle() != null && e.getTitle().startsWith(NOTE_PREFIX))
			{
				if (note != null)
				{
					return false;
				}
				note = e;
			}
		}
		DayRecord last = lastPlayed(days, LocalDate.parse(day.getDate()), false);
		if (note == null || last == null)
		{
			return false;
		}
		for (JourneyEvent e : day.getEvents())
		{
			// The login that wrote the note also wrote its level-ups and any new week just before it
			if (e.getTime() < note.getTime() - LOGIN_MILLIS)
			{
				return false;
			}
		}

		List<JourneyEvent> levels = new ArrayList<>();
		for (JourneyEvent e : day.getEvents())
		{
			if (e.getType() == EventType.LEVEL && e.getDetail() != null && e.getDetail().endsWith(LEVEL_SUFFIX))
			{
				levels.add(e);
			}
		}
		int levelsGained = 0;
		for (JourneyEvent e : levels)
		{
			e.setAway(true);
			levelsGained += levelsGained(e, day.getOfflineSkillXp());
		}

		day.setXpGained(day.getXpGained() - day.getOfflineXp());
		for (Map.Entry<String, Long> e : day.getOfflineSkillXp().entrySet())
		{
			day.getSkillXp().computeIfPresent(e.getKey(), (k, v) -> v - e.getValue() > 0 ? v - e.getValue() : null);
		}
		day.setLevelsGained(Math.max(0, day.getLevelsGained() - levelsGained));
		day.setAwayXp(day.getOfflineXp());
		day.getAwaySkillXp().putAll(day.getOfflineSkillXp());
		day.setAwayLevels(levelsGained);
		day.setAwayFrom(last.getDate());
		day.setOfflineXp(0);
		day.getOfflineSkillXp().clear();
		return true;
	}

	/**
	 * Levels behind an away level-up event: its detail holds the new XP total, and the XP gained
	 * while away gives the level it started from.
	 */
	private static int levelsGained(JourneyEvent e, Map<String, Long> awaySkillXp)
	{
		try
		{
			long now = Long.parseLong(e.getDetail().substring(0, e.getDetail().indexOf(' ')).replace(",", ""));
			long gained = awaySkillXp.getOrDefault(e.getSkill(), 0L);
			return Math.max(1, Skills.level(now) - Skills.level(now - gained));
		}
		catch (RuntimeException ex)
		{
			return 1;
		}
	}

	private static DayRecord lastPlayed(NavigableMap<String, DayRecord> days, LocalDate before, boolean inclusive)
	{
		for (DayRecord d : days.headMap(before.toString(), inclusive).descendingMap().values())
		{
			if (d.getPlayMillis() > 0)
			{
				return d;
			}
		}
		return null;
	}
}

package com.runejourney.service;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * Recognises game messages that represent Journey-worthy events. Input must already have
 * formatting tags removed.
 */
public final class ChatParser
{
	private static final Pattern KILL_COUNT = Pattern.compile(
		"^Your (?:completed )?(.+?) (?:kill |chest |completion |success |rescue )?count is: ?([\\d,]+)\\.?$");
	private static final Pattern COLLECTION_LOG = Pattern.compile("^New item added to your collection log: (.+)$");
	private static final Pattern QUEST = Pattern.compile("^Congratulations, you've completed a quest: (.+?)\\.?$");
	private static final Pattern COMBAT_TASK = Pattern.compile(
		"you've completed an? (\\w+) combat task: (.+?)(?: \\(([\\d,]+) points?\\))?\\.?$", Pattern.CASE_INSENSITIVE);
	/**
	 * Some game messages carry a machine-readable prefix such as "CA_ID:1234|".
	 */
	private static final Pattern ID_PREFIX = Pattern.compile("^[A-Z_]+:\\d+\\|");
	/**
	 * Colour markers the game embeds in some messages, e.g. "@ach_comp@" before a combat task name.
	 */
	private static final Pattern MARKER = Pattern.compile("@[A-Za-z0-9_]+@");
	private static final Pattern DIARY_TIER = Pattern.compile(
		"^Congratulations! You have completed all of the (\\w+) tasks in the (.+?) area\\..*$");
	private static final Pattern PERSONAL_BEST = Pattern.compile(
		"(\\d+:\\d{2}(?::\\d{2})?(?:\\.\\d{2})?) \\(new personal best\\)", Pattern.CASE_INSENSITIVE);
	private static final Pattern SLAYER_TASK = Pattern.compile("^You've completed ([\\d,]+) tasks?.*$");
	private static final Pattern CLUE = Pattern.compile("^You have completed ([\\d,]+) (\\w+) Treasure Trails?\\.?$");

	private ChatParser()
	{
	}

	public enum Kind
	{
		KILL_COUNT,
		COLLECTION_LOG,
		QUEST,
		COMBAT_TASK,
		DIARY_TIER,
		PERSONAL_BEST,
		PET,
		DUPLICATE_PET,
		SLAYER_TASK,
		CLUE,
	}

	@Value
	public static class Result
	{
		Kind kind;
		/**
		 * Primary subject: boss, item, quest, task or area name, or PB time.
		 */
		String name;
		/**
		 * Secondary detail such as combat task tier or diary tier.
		 */
		String detail;
		int count;
	}

	public static Result parse(String message)
	{
		message = clean(ID_PREFIX.matcher(message.trim()).replaceFirst(""));
		Matcher m = KILL_COUNT.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.KILL_COUNT, normalizeBoss(m.group(1)), null, parseInt(m.group(2)));
		}

		m = COLLECTION_LOG.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.COLLECTION_LOG, m.group(1).trim(), null, 0);
		}

		m = QUEST.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.QUEST, m.group(1).trim(), null, 0);
		}

		m = COMBAT_TASK.matcher(message);
		if (m.find())
		{
			int points = m.group(3) != null ? parseInt(m.group(3)) : defaultTaskPoints(m.group(1));
			return new Result(Kind.COMBAT_TASK, m.group(2).trim(), capitalize(m.group(1)), points);
		}

		m = DIARY_TIER.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.DIARY_TIER, m.group(2).trim(), capitalize(m.group(1)), 0);
		}

		m = PERSONAL_BEST.matcher(message);
		if (m.find())
		{
			return new Result(Kind.PERSONAL_BEST, m.group(1), null, 0);
		}

		if (message.startsWith("You have a funny feeling like you're being followed")
			|| message.startsWith("You feel something weird sneaking into your backpack"))
		{
			return new Result(Kind.PET, null, null, 0);
		}

		if (message.startsWith("You have a funny feeling like you would have been followed"))
		{
			return new Result(Kind.DUPLICATE_PET, null, null, 0);
		}

		m = SLAYER_TASK.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.SLAYER_TASK, null, null, parseInt(m.group(1)));
		}

		m = CLUE.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.CLUE, capitalize(m.group(2)), null, parseInt(m.group(1)));
		}

		return null;
	}

	/**
	 * Removes the game's embedded colour markers from text.
	 */
	public static String clean(String text)
	{
		return text == null ? null : MARKER.matcher(text).replaceAll("").trim();
	}

	private static String normalizeBoss(String name)
	{
		// "Your subdued Wintertodt count is: 12"
		if (name.startsWith("subdued "))
		{
			name = name.substring("subdued ".length());
		}
		return name.isEmpty() ? name : Character.toUpperCase(name.charAt(0)) + name.substring(1);
	}

	/**
	 * Points per combat task tier, for messages that don't state them.
	 */
	private static int defaultTaskPoints(String tier)
	{
		switch (tier.toLowerCase())
		{
			case "easy":
				return 1;
			case "medium":
				return 2;
			case "hard":
				return 3;
			case "elite":
				return 4;
			case "master":
				return 5;
			case "grandmaster":
				return 6;
			default:
				return 0;
		}
	}

	private static int parseInt(String s)
	{
		try
		{
			return Integer.parseInt(s.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private static String capitalize(String s)
	{
		if (s == null || s.isEmpty())
		{
			return s;
		}
		return Character.toUpperCase(s.charAt(0)) + s.substring(1).toLowerCase();
	}
}

package com.runejourney.service;

import com.runejourney.RuneJourneyConfig;
import com.runejourney.planner.Skills;
import com.runejourney.util.Format;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

/**
 * Friendly chat messages for steady progress in a skill, varied so they don't repeat.
 */
final class Encouragement
{
	/**
	 * {amount} is the XP gap, {skill} the skill's name.
	 */
	private static final String[] GENERAL = {
		"That's another {amount} {skill} XP down. Keep it up!",
		"Another {amount} {skill} XP in the bag.",
		"{amount} more {skill} XP. Nice and steady.",
		"You've just put in another {amount} {skill} XP. Great work!",
		"{skill} is coming along nicely: another {amount} XP.",
		"Every bit counts: {amount} more {skill} XP.",
		"Another {amount} {skill} XP. The grind is paying off.",
		"{amount} {skill} XP closer. You've got this.",
		"Look at that, another {amount} {skill} XP done.",
		"Small steps, big progress: {amount} more {skill} XP.",
		"Another {amount} {skill} XP. Your future self says thanks.",
		"{amount} more {skill} XP. Keep that momentum going!",
	};

	private static final Map<Skill, String[]> SKILL_LINES = new EnumMap<>(Skill.class);

	static
	{
