	 * Called on logout: forget in-memory skill state so the next login takes a fresh baseline.
	 */
	public synchronized void resetSessionState()
	{
		finishPlaySession();
		baselineSet = false;
		lastXpTick.clear();
		lastRollDate = null;
		lastKcBoss = null;
		pendingPbTime = null;
