import javax.swing.border.EmptyBorder;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * "What have I actually accomplished today?" Also doubles as the weekly/monthly recap and
 * "since..." comparison view via the range selector.
 */
class TodayTab extends RefreshableTab
{
	@Getter
	@RequiredArgsConstructor
	enum Range
	{
		TODAY("Today"),
		YESTERDAY("Yesterday"),
		THIS_WEEK("This week"),
		LAST_WEEK("Last week"),
		THIS_MONTH("This month"),
		LAST_30_DAYS("Last 30 days"),
		THIS_YEAR("This year"),
		ALL_TIME("Since RuneJourney was installed"),
		CUSTOM("Custom range...");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	private final JourneyService service;
	private final Views views;
	private final ReportWindowManager reportWindows;
	private final WrappedPlayer wrappedPlayer;
	private final JButton wrappedButton = Ui.button("RuneJourney Wrapped", this::openWrapped);
	private final Color buttonBackground = wrappedButton.getBackground();
	private final Color buttonForeground = wrappedButton.getForeground();
	private final JComboBox<Range> rangeBox = new JComboBox<>(Range.values());
	private final JPanel body = Ui.stack(6);
	private static final java.time.format.DateTimeFormatter MENU_DATE =
		java.time.format.DateTimeFormatter.ofPattern("d MMM", java.util.Locale.ENGLISH);
	/**
	 * Rows shown in the loot and supplies breakdowns before the rest are summed as "Other".
	 */
	private static final int BREAKDOWN_ROWS = 8;
	/**
	 * Rows shown before "Show more"; the rest are a click away so the page stays short.
	 */
	private static final int HIGHLIGHT_ROWS = 3;
	private static final int SKILL_ROWS = 5;
	private static final int BOSS_ROWS = 3;
	private static final String HIGHLIGHTS = "highlights";
	private static final String SKILLS = "skills";
	private static final String MONEY = "money";
	private static final String ACTIVITY = "activity";
	private static final String GOLD_HEX = String.format("#%06X", Ui.GOLD.getRGB() & 0xFFFFFF);
	/**
	 * Sections whose "Show more" is open, kept across refreshes.
	 */
	private final Set<String> expanded = new HashSet<>();
	private LocalDate customFrom = LocalDate.now().minusDays(6);
	private LocalDate customTo = LocalDate.now();
	private Range lastRange = Range.TODAY;

	@Inject
	TodayTab(JourneyService service, Views views, ReportWindowManager reportWindows, WrappedPlayer wrappedPlayer)
	{
		this.reportWindows = reportWindows;
		this.wrappedPlayer = wrappedPlayer;
		this.service = service;
		this.views = views;
		setLayout(new BorderLayout(0, 6));
		setOpaque(false);
		rangeBox.addActionListener(e ->
		{
			if (rangeBox.getSelectedItem() == Range.CUSTOM && !chooseCustomRange())
			{
				rangeBox.setSelectedItem(lastRange);
				return;
			}
			lastRange = (Range) rangeBox.getSelectedItem();
			refresh(true);
		});


		JButton charts = Ui.button("Charts", reportWindows::open);
		charts.setToolTipText("Open the reports window: charts, breakdowns and exports for any metric and period");
		Ui.styled(rangeBox);

		JPanel controls = new JPanel(new BorderLayout(4, 0));
		controls.setOpaque(false);
		controls.add(rangeBox, BorderLayout.CENTER);
		controls.add(charts, BorderLayout.EAST);

		wrappedButton.setToolTipText("Relive your week with RuneJourney Wrapped");
		JPanel top = new JPanel(new GridLayout(0, 1, 0, 6));
		top.setOpaque(false);
		top.add(wrappedButton);
		top.add(controls);
		add(top, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
	}

	private boolean chooseCustomRange()
	{
		JTextField fromField = new JTextField(customFrom.toString(), 10);
		JTextField toField = new JTextField(customTo.toString(), 10);
		JPanel form = new JPanel(new GridLayout(0, 2, 6, 6));
		form.add(new JLabel("From (YYYY-MM-DD)"));
		form.add(fromField);
		form.add(new JLabel("To (YYYY-MM-DD)"));
		form.add(toField);
		while (true)
		{
			int ok = JOptionPane.showConfirmDialog(this, form, "Custom range", JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
			if (ok != JOptionPane.OK_OPTION)
			{
				return false;
			}
			LocalDate a = GoalPlanner.parseDate(fromField.getText().trim());
			LocalDate b = GoalPlanner.parseDate(toField.getText().trim());
			if (a == null || b == null || b.isBefore(a))
			{
				JOptionPane.showMessageDialog(this, "Enter two dates as YYYY-MM-DD, with the end on or after the start.",
					"RuneJourney", JOptionPane.WARNING_MESSAGE);
				continue;
			}
			customFrom = a;
			customTo = b;
			return true;
		}
	}

	private void updateWrappedButton()
	{
		boolean isNew = service.isWrappedNew();
		boolean any = !service.wrappedWeeks().isEmpty();
		wrappedButton.setText(isNew ? "Your Week Wrapped is ready!" : "RuneJourney Wrapped");
		wrappedButton.setBackground(isNew ? Ui.GOLD : buttonBackground);
		wrappedButton.setForeground(isNew ? Color.BLACK : buttonForeground);
		wrappedButton.setEnabled(any);
		wrappedButton.setToolTipText(any ? "Relive your week with RuneJourney Wrapped"
			: "Your first Wrapped arrives the Monday after your first week with RuneJourney");
	}

	private void openWrapped()
	{
		List<LocalDate> weeks = service.wrappedWeeks();
		if (weeks.isEmpty())
		{
			return;
		}
		LocalDate latest = service.latestWrappedWeek();
		if (weeks.size() == 1 || (latest != null && service.isWrappedNew()))
		{
			playWrapped(weeks.get(0));
			return;
		}
		JPopupMenu menu = new JPopupMenu();
		for (LocalDate week : weeks.subList(0, Math.min(12, weeks.size())))
		{
			String label = (week.equals(latest) ? "Last week" : "Week of " + Format.date(week))
				+ " (" + week.format(MENU_DATE) + " - " + week.plusDays(6).format(MENU_DATE) + ")";
			JMenuItem item = new JMenuItem(label);
			item.addActionListener(e -> playWrapped(week));
			menu.add(item);
		}
		menu.show(wrappedButton, 0, wrappedButton.getHeight());
	}

	private void playWrapped(LocalDate week)
	{
		service.markWrappedSeen(week);
		wrappedPlayer.play(service.buildWrapped(week));
		updateWrappedButton();
	}

	private LocalDate[] selectedRange()
	{
		Range range = (Range) rangeBox.getSelectedItem();
		LocalDate today = LocalDate.now();
		LocalDate from;
		LocalDate to = today;
		switch (range)
		{
			case CUSTOM:
				from = customFrom;
				to = customTo;
				break;
			case YESTERDAY:
				from = to = today.minusDays(1);
				break;
			case THIS_WEEK:
				from = GoalPlanner.weekStart(today);
				break;
			case LAST_WEEK:
				from = GoalPlanner.weekStart(today).minusWeeks(1);
				to = from.plusDays(6);
				break;
			case THIS_MONTH:
				from = today.with(TemporalAdjusters.firstDayOfMonth());
				break;
			case LAST_30_DAYS:
				from = today.minusDays(29);
				break;
			case THIS_YEAR:
				from = today.with(TemporalAdjusters.firstDayOfYear());
				break;
			case ALL_TIME:
				from = service.firstDay();
				break;
			default:
				from = today;
		}
		return new LocalDate[]{from, to};
	}

	@Override
	void refresh(boolean force)
	{
		updateWrappedButton();
		Range range = (Range) rangeBox.getSelectedItem();
		LocalDate[] selected = selectedRange();
		LocalDate from = selected[0];
		LocalDate to = selected[1];

		RangeSummary r = service.summarize(from, to);
		body.removeAll();

		SessionView session = service.sessionView();
		if (session != null && (range == Range.TODAY || range == Range.THIS_WEEK))
		{
			body.add(views.session(session));
		}

		boolean multiDay = !from.equals(to);
		if (multiDay)
		{
			body.add(Ui.muted(Format.date(from) + " - " + Format.date(to)));
		}
		body.add(tiles(r, multiDay));
		int[] streak = service.playStreaks();
		if (streak[0] > 1)
		{
			body.add(Ui.small(streak[0] + "-day play streak" + (streak[1] > streak[0] ? " (best " + streak[1] + ")" : ", your best!"), Ui.GOLD));
		}
		if (r.getAwayXp() > 0)
		{
			body.add(Ui.muted("Not counted: +" + Format.compact(r.getAwayXp()) + " XP gained while away, some time between "
				+ r.getAwayFrom().format(MENU_DATE) + " and " + r.getAwayTo().format(MENU_DATE) + "."));
		}

		if (r.getPlayMillis() == 0 && r.getHighlights().isEmpty() && r.getXpGained() == 0)
		{
			body.add(Ui.empty(range == Range.TODAY
				? "Nothing recorded yet today. Go make some memories!"
				: "Nothing was recorded in this period."));
			rebuild();
			return;
		}

		highlights(r, multiDay);
		skills(r, multiDay);
		money(r);
		activity(r);
		rebuild();
	}

	/**
	 * The headline numbers: time played, XP, profit and net worth.
	 */
	private JPanel tiles(RangeSummary r, boolean multiDay)
	{
		JPanel grid = new JPanel(new GridLayout(0, 2, 4, 4));
		grid.setOpaque(false);
		grid.add(Ui.tile(Format.duration(r.getPlayMillis()),
			multiDay ? "Played, " + r.getDaysPlayed() + (r.getDaysPlayed() == 1 ? " day" : " days") : "Played", Color.WHITE));
		JPanel xp = Ui.tile(Format.compact(r.getXpGained()), "XP gained", Color.WHITE);
		xp.setToolTipText(Format.number(r.getXpGained()) + " XP");
		grid.add(xp);
		long profit = r.getLootValue() + r.getSkillingIncome() - r.getSuppliesCost();
		grid.add(Ui.tile(gp(profit), "Profit", profit > 0 ? Ui.GOOD : profit < 0 ? Ui.BAD : Color.WHITE));
		Long worth = r.getEndSnapshot().get(Counters.WEALTH);
		Long worthBefore = r.getStartSnapshot().get(Counters.WEALTH);
		if (worth != null)
		{
			long change = worthBefore == null ? 0 : worth - worthBefore;
			grid.add(Ui.tile(Format.compact(worth) + " gp",
				worthBefore == null ? "Net worth" : "Net worth " + (change >= 0 ? "+" : "") + Format.compact(change), Color.WHITE));
		}
		else
		{
			grid.add(Ui.tile(Format.number(r.getLevelsGained()), "Levels gained", Color.WHITE));
		}
		return grid;
	}

	private void highlights(RangeSummary r, boolean multiDay)
	{
		List<JourneyEvent> events = new ArrayList<>();
		if (multiDay && r.getBestMoment() != null)
		{
			events.add(r.getBestMoment());
		}
		for (JourneyEvent e : r.getHighlights())
		{
			if (!(multiDay && e.equals(r.getBestMoment())))
			{
				events.add(e);
			}
		}
		if (events.isEmpty())
		{
			return;
		}
		int hidden = events.size() - HIGHLIGHT_ROWS;
		JLabel more = hidden > 0 ? toggle(HIGHLIGHTS, "Show " + hidden + " more") : null;
		if (more != null)
		{
			more.setVerticalAlignment(SwingConstants.BOTTOM);
		}
		body.add(Ui.row(Ui.header("Highlights"), more));
		events.stream()
			.limit(expanded.contains(HIGHLIGHTS) ? events.size() : HIGHLIGHT_ROWS)
			.forEach(e -> body.add(views.event(e, null)));
	}

	/**
	 * XP by skill, with any level reached alongside. Skills that levelled always show.
	 */
	private void skills(RangeSummary r, boolean multiDay)
	{
		List<Map.Entry<String, Long>> rows = r.getSkillXp().entrySet().stream()
			.filter(e -> e.getValue() > 0 && Skills.parse(e.getKey()) != null)
			.sorted(Map.Entry.<String, Long>comparingByValue().reversed())
			.collect(Collectors.toList());
		if (rows.isEmpty())
		{
			return;
		}
		List<Map.Entry<String, Long>> top = new ArrayList<>();
		for (int i = 0; i < rows.size(); i++)
		{
			if (i < SKILL_ROWS || r.getLevelRanges().containsKey(rows.get(i).getKey()))
			{
				top.add(rows.get(i));
			}
		}
		int hidden = rows.size() - top.size();
		JPanel card = section("Skills", SKILLS, hidden > 0 ? "Show " + hidden + " more" : null);
		for (Map.Entry<String, Long> e : expanded.contains(SKILLS) ? rows : top)
		{
			Skill s = Skills.parse(e.getKey());
			JPanel row = Ui.stat(s.getName(), "+" + Format.compact(e.getValue()));
			JLabel name = (JLabel) row.getComponent(0);
			name.setIcon(views.skillIcon(s));
			int[] levels = r.getLevelRanges().get(e.getKey());
			if (levels != null)
			{
				name.setText("<html>" + s.getName() + " <font color='" + GOLD_HEX + "'>lvl " + levels[1] + "</font></html>");
				withTooltip(row, "Level " + levels[0] + " to " + levels[1] + ", " + Format.number(e.getValue()) + " XP");
			}
			else
			{
				withTooltip(row, Format.number(e.getValue()) + " XP");
			}
			card.add(row);
		}
		if (multiDay && r.getBiggestDay() != null && r.getBiggestDayXp() > 0)
		{
			JLabel best = Ui.muted("Biggest day: " + Format.compact(r.getBiggestDayXp()) + " XP on "
				+ Format.date(LocalDate.parse(r.getBiggestDay())));
			best.setBorder(new EmptyBorder(4, 0, 0, 0));
			card.add(best);
		}
		body.add(card);
	}

	/**
	 * Where the profit came from: totals first, the breakdown on request.
	 */
	private void money(RangeSummary r)
	{
		if (r.getLootValue() == 0 && r.getSkillingIncome() == 0 && r.getSuppliesCost() == 0)
		{
			return;
		}
		JPanel card = section("Money", MONEY, "Show details");
		if (r.getLootValue() != 0)
		{
			card.add(Ui.stat("Loot", Format.compact(r.getLootValue()) + " gp"));
		}
		if (r.getSkillingIncome() != 0)
		{
			card.add(Ui.stat("Skilling", gp(r.getSkillingIncome()), r.getSkillingIncome() < 0 ? Ui.BAD : Color.WHITE));
		}
		if (r.getSuppliesCost() > 0)
		{
			card.add(Ui.stat("Supplies used", gp(-r.getSuppliesCost()), Ui.BAD));
		}
		if (!expanded.contains(MONEY))
		{
			body.add(card);
			return;
		}

		List<Map.Entry<String, LootSource>> sources = r.getLootBySource().entrySet().stream()
			.filter(e -> e.getValue().getValue() > 0)
			.sorted(Comparator.comparingLong((Map.Entry<String, LootSource> e) -> e.getValue().getValue()).reversed())
			.collect(Collectors.toList());
		if (!sources.isEmpty())
		{
			card.add(subheading("Loot by source"));
			sources.stream().limit(BREAKDOWN_ROWS).forEach(e -> card.add(withTooltip(
				Ui.stat(e.getKey(), Format.compact(e.getValue().getValue()) + " gp", ColorScheme.LIGHT_GRAY_COLOR),
				sourceTooltip(e.getValue()))));
			otherRow(card, sources.stream().skip(BREAKDOWN_ROWS).mapToLong(e -> e.getValue().getValue()).sum(),
				sources.size() - BREAKDOWN_ROWS);
		}

		List<Map.Entry<String, Long>> skilling = r.getSkillingIncomeBySkill().entrySet().stream()
			.filter(e -> e.getValue() != 0 && Skills.parse(e.getKey()) != null)
			.sorted(Map.Entry.<String, Long>comparingByValue().reversed())
			.collect(Collectors.toList());
		if (!skilling.isEmpty())
		{
			card.add(subheading("Skilling by skill"));
			for (Map.Entry<String, Long> e : skilling)
			{
				Skill s = Skills.parse(e.getKey());
				JPanel row = Ui.stat(s.getName(), gp(e.getValue()), e.getValue() < 0 ? Ui.BAD : ColorScheme.LIGHT_GRAY_COLOR);
				((JLabel) row.getComponent(0)).setIcon(views.skillIcon(s));
				card.add(row);
			}
		}

		List<Map.Entry<String, ItemTotal>> supplies = r.getSuppliesUsed().entrySet().stream()
			.sorted(Comparator.comparingLong((Map.Entry<String, ItemTotal> e) -> e.getValue().getValue()).reversed())
			.collect(Collectors.toList());
		if (!supplies.isEmpty())
		{
			card.add(subheading("Supplies used"));
			supplies.stream().limit(BREAKDOWN_ROWS).forEach(e -> card.add(Ui.stat(
				e.getKey() + " x" + Format.number(e.getValue().getQuantity()),
				gp(-e.getValue().getValue()), ColorScheme.LIGHT_GRAY_COLOR)));
			otherRow(card, -supplies.stream().skip(BREAKDOWN_ROWS).mapToLong(e -> e.getValue().getValue()).sum(),
				supplies.size() - BREAKDOWN_ROWS);
		}
		body.add(card);
	}

	/**
	 * Kill counts by boss, then counts of everything else done.
	 */
	private void activity(RangeSummary r)
	{
		List<JPanel> rows = new ArrayList<>();
		if (r.getCluesCompleted() > 0)
		{
			rows.add(Ui.stat("Clue scrolls", Format.number(r.getCluesCompleted())
				+ (r.getClueLootValue() > 0 ? ", " + Format.compact(r.getClueLootValue()) + " gp" : "")));
		}
		count(rows, "Slayer tasks", r.getSlayerTasks());
		count(rows, "Collection log", r.getCollectionLogSlots());
		count(rows, "Quests", r.getQuestsCompleted());
		count(rows, "Personal bests", r.getPersonalBests());
		count(rows, "Pets", r.getPets());
		if (r.getCombatTasks() > 0)
		{
			rows.add(Ui.stat("Combat tasks", Format.number(r.getCombatTasks())
				+ (r.getCombatTaskPoints() > 0 ? ", " + Format.number(r.getCombatTaskPoints()) + " pts" : "")));
		}
		if (r.getDeaths() > 0)
		{
			rows.add(Ui.stat("Deaths", Format.number(r.getDeaths()), Ui.BAD));
		}

		List<Map.Entry<String, Integer>> bosses = r.getBossKillsByName().entrySet().stream()
			.sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
			.collect(Collectors.toList());
		if (rows.isEmpty() && bosses.isEmpty())
		{
			return;
		}
		int hidden = Math.max(0, bosses.size() - BOSS_ROWS);
		JPanel card = section("Activity", ACTIVITY, hidden > 0 ? "Show " + hidden + " more" : null);
		bosses.stream()
			.limit(expanded.contains(ACTIVITY) ? bosses.size() : BOSS_ROWS)
			.forEach(e -> card.add(Ui.stat(e.getKey(), Format.number(e.getValue()) + " KC")));
		rows.forEach(card::add);
		body.add(card);
	}

	/**
	 * A card headed by its title, with an optional link to show more that stays open across
	 * refreshes.
	 */
	private JPanel section(String title, String key, String moreText)
	{
		JPanel card = Ui.card();
		JLabel heading = Ui.small(title, Ui.GOLD);
		heading.setFont(FontManager.getRunescapeBoldFont());
		JPanel head = Ui.row(heading, moreText == null && !expanded.contains(key) ? null : toggle(key, moreText));
		head.setBorder(new EmptyBorder(0, 0, 3, 0));
		card.add(head);
		return card;
	}

	private JLabel toggle(String key, String moreText)
	{
		return Ui.link(expanded.contains(key) ? "Show less" : moreText, () ->
		{
			if (!expanded.remove(key))
			{
				expanded.add(key);
			}
			refresh(true);
		});
	}

	private static JLabel subheading(String text)
	{
		JLabel l = Ui.small(text, Ui.MUTED);
		l.setBorder(new EmptyBorder(6, 0, 1, 0));
		return l;
	}

	private static String gp(long value)
	{
		return (value > 0 ? "+" : "") + Format.compact(value) + " gp";
	}

	/**
	 * Sums up whatever didn't fit in a breakdown.
	 */
	private static void otherRow(JPanel card, long value, int count)
	{
		if (count > 0)
		{
			card.add(Ui.stat("Other (" + count + ")", gp(value), ColorScheme.LIGHT_GRAY_COLOR));
		}
	}

	private static JPanel withTooltip(JPanel row, String tooltip)
	{
		row.setToolTipText(tooltip);
		for (java.awt.Component c : row.getComponents())
		{
			((javax.swing.JComponent) c).setToolTipText(tooltip);
		}
		return row;
	}

	/**
	 * How often a source paid out and its most valuable items.
	 */
	private static String sourceTooltip(LootSource s)
	{
		StringBuilder sb = new StringBuilder("<html>").append(Format.number(s.getTimes()))
			.append(s.getTimes() == 1 ? " time" : " times");
		s.getItems().entrySet().stream()
			.filter(e -> e.getValue().getValue() > 0)
			.sorted(Comparator.comparingLong((Map.Entry<String, ItemTotal> e) -> e.getValue().getValue()).reversed())
			.limit(5)
			.forEach(e -> sb.append("<br>").append(Ui.escape(e.getKey())).append(" x").append(Format.number(e.getValue().getQuantity()))
				.append(": ").append(Format.compact(e.getValue().getValue())).append(" gp"));
		return sb.append("</html>").toString();
	}

	private static void count(List<JPanel> rows, String name, int value)
	{
		if (value > 0)
		{
			rows.add(Ui.stat(name, Format.number(value)));
		}
	}
}

package com.runejourney.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Small Swing building blocks shared by the RuneJourney tabs.
 */
final class Ui
{
	static final Color GOLD = new Color(0xE0B040);
	static final Color MUTED = new Color(0x9A9A9A);
	static final Color GOOD = new Color(0x4CAF50);
	static final Color WARN = new Color(0xFFA726);
	static final Color BAD = new Color(0xEF5350);
	/**
	 * Usable width for wrapped text inside a card.
	 */
	static final int TEXT_WIDTH = PluginPanel.PANEL_WIDTH - 60;

	private Ui()
	{
	}

	static JPanel stack(int gap)
	{
		JPanel p = new JPanel(new DynamicGridLayout(0, 1, 0, gap));
		p.setOpaque(false);
		return p;
	}

	static JPanel card()
	{
		JPanel p = stack(3);
		p.setOpaque(true);
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(8, 8, 8, 8));
		return p;
	}

	/**
	 * A card with a coloured stripe down its left edge.
	 */
	static JPanel accentCard(Color accent)
	{
		JPanel p = card();
		p.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			new EmptyBorder(5, 7, 5, 6)));
		return p;
	}

	/*
	 * Type scale, used everywhere in the sidebar:
	 *   header - section headings: bold, gold, sentence case
	 *   title  - the name of a thing (event, goal, suggestion): regular, white
	 *   text / muted / small - everything else: small font
	 * Nothing is upper-cased; the RuneScape fonts read badly in capitals.
	 */

	static JLabel header(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(GOLD);
		l.setBorder(new EmptyBorder(10, 2, 2, 0));
		return l;
	}

	static JLabel title(String text)
	{
		return label(text, FontManager.getRunescapeFont(), Color.WHITE);
	}

	/**
	 * Applies the sidebar font to a form control such as a dropdown or check box.
	 */
	static <T extends JComponent> T styled(T component)
	{
		component.setFont(FontManager.getRunescapeSmallFont());
		return component;
	}

	static JLabel text(String text)
	{
		return label(text, FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
	}

	static JLabel muted(String text)
	{
		return label(text, FontManager.getRunescapeSmallFont(), MUTED);
	}

	static JLabel label(String text, Font font, Color color)
	{
		return label(text, font, color, TEXT_WIDTH);
	}

	static JLabel label(String text, Font font, Color color, int width)
	{
		JLabel l = new JLabel(wrap(text, width));
		l.setFont(font);
		l.setForeground(color);
		return l;
	}

	/**
	 * Wraps text in HTML so long lines break within the sidebar.
	 */
	static String wrap(String text)
	{
		return wrap(text, TEXT_WIDTH);
	}

	static String wrap(String text, int width)
	{
		if (text == null)
		{
			return "";
		}
		return "<html><div style='width:" + width + "px'>" + escape(text) + "</div></html>";
	}

	static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/**
	 * A "label ........ value" row.
	 */
	static JPanel stat(String name, String value)
	{
		return stat(name, value, Color.WHITE);
	}

	static JPanel stat(String name, String value, Color valueColor)
	{
		JPanel row = rowPanel();
		JLabel l = new JLabel(name);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		JLabel v = new JLabel(value);
		v.setFont(FontManager.getRunescapeSmallFont());
		v.setForeground(valueColor);
		v.setHorizontalAlignment(SwingConstants.RIGHT);
		v.setToolTipText(value);
		row.add(l, BorderLayout.WEST);
		row.add(v, BorderLayout.CENTER);
		return row;
	}

	/**
	 * A left/right row that never asks for more than the sidebar's width, so a long value is
	 * shortened with "..." rather than widening (and clipping) the whole view.
	 */
	private static JPanel rowPanel()
	{
		JPanel row = new JPanel(new BorderLayout(6, 0))
		{
			@Override
			public java.awt.Dimension getPreferredSize()
			{
				java.awt.Dimension d = super.getPreferredSize();
				d.width = Math.min(d.width, TEXT_WIDTH);
				return d;
			}
		};
		row.setOpaque(false);
		return row;
	}

	/**
	 * A short single-line label. Unlike {@link #text} it doesn't reserve the full wrapping width,
	 * so it can sit beside other components.
	 */
	static JLabel small(String text, Color color)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		return l;
	}

	/**
	 * A row with a label on the left and another on the right, neither wrapping.
	 */
	static JPanel row(JComponent left, JComponent right)
	{
		JPanel row = rowPanel();
		row.add(left, BorderLayout.WEST);
		if (right != null)
		{
			if (right instanceof JLabel)
			{
				((JLabel) right).setHorizontalAlignment(SwingConstants.RIGHT);
			}
			row.add(right, BorderLayout.CENTER);
		}
		return row;
	}

	static JButton button(String text, Runnable action)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setFocusPainted(false);
		b.addActionListener(e -> action.run());
		return b;
	}

	/**
	 * Makes a card respond to clicks with a hover highlight.
	 */
	static void clickable(JPanel card, Runnable action)
	{
		card.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		Color normal = card.getBackground();
		MouseAdapter listener = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				action.run();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				card.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				card.setBackground(normal);
			}
		};
		card.addMouseListener(listener);
	}

	/**
	 * A headline number with a caption beneath, for the grid at the top of a page.
	 */
	static JPanel tile(String value, String caption, Color valueColor)
	{
		JPanel p = new JPanel(new BorderLayout(0, 2))
		{
			@Override
			public Dimension getPreferredSize()
			{
				// Two share a row, so never ask for more than half the width
				Dimension d = super.getPreferredSize();
				d.width = Math.min(d.width, TEXT_WIDTH / 2);
				return d;
			}
		};
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(6, 8, 6, 6));
		JLabel v = new JLabel(value);
		v.setFont(FontManager.getRunescapeBoldFont());
		v.setForeground(valueColor);
		JLabel c = small(caption, MUTED);
		p.add(v, BorderLayout.NORTH);
		p.add(c, BorderLayout.SOUTH);
		p.setToolTipText(caption + ": " + value);
		return p;
	}

	/**
	 * A section card with a gold heading.
	 */
	static JPanel section(String title)
	{
		JPanel card = card();
		JLabel h = new JLabel(title);
		h.setFont(FontManager.getRunescapeBoldFont());
		h.setForeground(GOLD);
		h.setBorder(new EmptyBorder(0, 0, 3, 0));
		card.add(h);
		return card;
	}

	/**
	 * A clickable text link.
	 */
	static JLabel link(String text, Runnable action)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(GOLD);
		l.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		l.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				action.run();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				l.setForeground(Color.WHITE);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				l.setForeground(GOLD);
			}
		});
		return l;
	}

	static JPanel empty(String message)
	{
		JPanel p = card();
		p.add(muted(message));
		return p;
	}

	static JComponent progress(double fraction, Color color)
	{
		return new ProgressBar(fraction, color);
	}

	private static class ProgressBar extends JComponent
	{
		private final double fraction;
		private final Color color;

		ProgressBar(double fraction, Color color)
		{
			this.fraction = Math.max(0, Math.min(1, fraction));
			this.color = color;
			setPreferredSize(new Dimension(10, 6));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g;
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(ColorScheme.DARK_GRAY_COLOR.darker());
			g2.fillRoundRect(0, 0, getWidth(), getHeight(), 4, 4);
			g2.setColor(color);
			g2.fillRoundRect(0, 0, (int) Math.round(getWidth() * fraction), getHeight(), 4, 4);
		}
	}
}

package com.runejourney.ui;

import com.runejourney.RuneJourneyPlugin;
import com.runejourney.model.JourneyEvent;
import com.runejourney.planner.Skills;
import com.runejourney.service.JourneyService;
import com.runejourney.service.JourneyStore;
import com.runejourney.service.SessionView;
import com.runejourney.util.Format;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

/**
 * Renderers shared between tabs.
 */
@Slf4j
@Singleton
class Views
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm");

	private final SkillIconManager skillIconManager;
	private final JourneyService service;
	private final JourneyStore store;
	private final RuneJourneyPlugin plugin;
	private final Map<Skill, ImageIcon> icons = new EnumMap<>(Skill.class);
	@Setter
	private Runnable onChange = () ->
	{
	};

	@Inject
	Views(SkillIconManager skillIconManager, JourneyService service, JourneyStore store, RuneJourneyPlugin plugin)
	{
		this.skillIconManager = skillIconManager;
		this.service = service;
		this.store = store;
		this.plugin = plugin;
	}

	ImageIcon skillIcon(Skill skill)
	{
		if (skill == null)
		{
			return null;
		}
		return icons.computeIfAbsent(skill, s -> new ImageIcon(skillIconManager.getSkillImage(s, true)));
	}

	/**
	 * A Journey event row. When {@code date} is given the entry can be deleted via right click.
	 */
	JPanel event(JourneyEvent e, String date)
	{
		JPanel card = Ui.accentCard(e.getType().getColor());

		// The stripe colour shows the type; the time sits beside the title to keep rows short
		String time = Instant.ofEpochMilli(e.getTime()).atZone(ZoneId.systemDefault()).format(TIME);
		Skill skill = Skills.parse(e.getSkill());
		JLabel title = Ui.label(e.getTitle(), FontManager.getRunescapeFont(), Color.WHITE, Ui.TEXT_WIDTH - (skill != null ? 52 : 32));
		if (skill != null)
		{
			title.setIcon(skillIcon(skill));
			title.setIconTextGap(5);
		}
		title.setToolTipText(e.getType().getLabel());
		JLabel when = Ui.small(time, Ui.MUTED);
		when.setVerticalAlignment(SwingConstants.TOP);
		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setOpaque(false);
		top.add(title, BorderLayout.CENTER);
		top.add(when, BorderLayout.EAST);
		card.add(top);
		card.setToolTipText(e.getType().getLabel());

		if (e.getDetail() != null)
		{
			card.add(Ui.muted(e.getDetail()));
		}
		if (e.getScreenshot() != null)
		{
			String name = e.getScreenshot();
			card.add(Ui.link("View screenshot", () -> showScreenshot(name, e.getTitle())));
		}

		if (e.getNote() != null)
		{
			card.add(note(e.getNote()));
		}

		// Notes can be added wherever an event is shown; removing it is only offered in the Journey
		String day = date != null ? date : Instant.ofEpochMilli(e.getTime()).atZone(ZoneId.systemDefault()).toLocalDate().toString();
		JPopupMenu menu = new JPopupMenu();
		JMenuItem editNote = new JMenuItem(e.getNote() == null ? "Add note..." : "Edit note...");
		editNote.addActionListener(a -> editNote(card, e, day));
		menu.add(editNote);
		if (e.getNote() != null)
		{
			JMenuItem removeNote = new JMenuItem("Remove note");
			removeNote.addActionListener(a ->
			{
				service.setEventNote(day, e.getTime(), e.getTitle(), null);
				onChange.run();
			});
			menu.add(removeNote);
		}
		card.setComponentPopupMenu(menu);
		inheritPopup(card);

		if (date != null)
		{
			JMenuItem delete = new JMenuItem("Remove from Journey");
			delete.addActionListener(a ->
			{
				int ok = JOptionPane.showConfirmDialog(card, "Remove \"" + e.getTitle() + "\" from your Journey?",
					"RuneJourney", JOptionPane.OK_CANCEL_OPTION);
				if (ok == JOptionPane.OK_OPTION)
				{
					service.deleteEvent(date, e.getTime(), e.getTitle());
					onChange.run();
				}
			});
			menu.addSeparator();
			menu.add(delete);
		}
		return card;
	}

	private static final Color NOTE_COLOR = new Color(0xD7CCC8);
	private static final int MAX_NOTE_LENGTH = 500;

	/**
	 * The player's note, keeping their line breaks.
	 */
	private static JLabel note(String text)
	{
		JLabel l = new JLabel("<html><div style='width:" + Ui.TEXT_WIDTH + "px'>"
			+ Ui.escape(text).replace("\n", "<br>") + "</div></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(NOTE_COLOR);
		l.setBorder(new EmptyBorder(2, 0, 0, 0));
		return l;
	}

	private void editNote(JPanel card, JourneyEvent e, String day)
	{
		javax.swing.JTextArea area = new javax.swing.JTextArea(e.getNote() == null ? "" : e.getNote(), 5, 28);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		JPanel form = new JPanel(new BorderLayout(0, 6));
		form.add(new JLabel(Ui.wrap("A note for \"" + e.getTitle() + "\"", 260)), BorderLayout.NORTH);
		form.add(new javax.swing.JScrollPane(area), BorderLayout.CENTER);
		SwingUtilities.invokeLater(area::requestFocusInWindow);

		int ok = JOptionPane.showConfirmDialog(card, form, e.getNote() == null ? "Add note" : "Edit note",
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
		if (ok != JOptionPane.OK_OPTION)
		{
			return;
		}
		String text = area.getText();
		if (text.length() > MAX_NOTE_LENGTH)
		{
			text = text.substring(0, MAX_NOTE_LENGTH);
		}
		service.setEventNote(day, e.getTime(), e.getTitle(), text);
		onChange.run();
	}

	/**
	 * Right clicks on a card's labels open the card's menu too, not just clicks on its edges.
	 */
	private static void inheritPopup(java.awt.Container c)
	{
		for (java.awt.Component child : c.getComponents())
		{
			if (child instanceof javax.swing.JComponent)
			{
				((javax.swing.JComponent) child).setInheritsPopupMenu(true);
			}
			if (child instanceof java.awt.Container)
			{
				inheritPopup((java.awt.Container) child);
			}
		}
	}

	private void showScreenshot(String name, String title)
	{
		String key = service.getProfileKey();
		ExecutorService executor = plugin.getExecutor();
		if (key == null || executor == null || executor.isShutdown())
		{
			return;
		}
		executor.submit(() ->
		{
			BufferedImage image;
			try
			{
				image = store.readScreenshot(key, name);
			}
			catch (IOException ex)
			{
				log.warn("Unable to read screenshot {}", name, ex);
				image = null;
			}
			BufferedImage result = image;
			SwingUtilities.invokeLater(() ->
			{
				if (result == null)
				{
					JOptionPane.showMessageDialog(null, "That screenshot could not be found.", "RuneJourney", JOptionPane.WARNING_MESSAGE);
					return;
				}
				Image scaled = result;
				if (result.getWidth() > 900)
				{
					scaled = result.getScaledInstance(900, result.getHeight() * 900 / result.getWidth(), Image.SCALE_SMOOTH);
				}
				JOptionPane.showMessageDialog(null, new JLabel(new ImageIcon(scaled)), title, JOptionPane.PLAIN_MESSAGE);
			});
		});
	}

	JPanel session(SessionView s)
	{
		JPanel card = Ui.accentCard(Ui.GOLD);
		card.add(Ui.row(Ui.small("Session in progress", Ui.GOLD), Ui.small(Format.duration(s.getActiveMillis()), Color.WHITE)));
		card.add(Ui.title(s.getGoalName()));
		card.add(Ui.stat("XP gained", "+" + Format.number(s.getXpGained())));
		card.add(Ui.stat("XP/hr", Format.number((long) s.getXpPerHour())));
		if (s.getCurrentProgress() > 0)
		{
			card.add(Ui.stat("Goal progress", Format.percent(s.getStartProgress()) + " -> " + Format.percent(s.getCurrentProgress())));
		}
		if (s.getWeekTarget() > 0)
		{
			card.add(Ui.stat("This week", Format.compact(s.getWeekAchieved()) + " / " + Format.compact(s.getWeekTarget()) + " XP"));
			card.add(Ui.progress(s.getWeekAchieved() / (double) s.getWeekTarget(), Ui.GOLD));
		}
		JPanel actions = new JPanel(new BorderLayout());
		actions.setOpaque(false);
		actions.setBorder(new EmptyBorder(4, 0, 0, 0));
		actions.add(Ui.button("End session", () ->
		{
			service.endSession();
			onChange.run();
		}), BorderLayout.CENTER);
		card.add(actions);
		return card;
	}
}

package com.runejourney.util;

import java.text.NumberFormat;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import net.runelite.api.Skill;

public final class Format
{
	private static final DateTimeFormatter SHORT_DATE = DateTimeFormatter.ofPattern("d MMM yyyy", Locale.ENGLISH);

	private Format()
	{
	}

	public static String number(long n)
	{
		return NumberFormat.getIntegerInstance(Locale.ENGLISH).format(n);
	}

	/**
	 * Compact quantity such as 624k, 4.28m or 1.14b.
	 */
	public static String compact(long n)
	{
		long abs = Math.abs(n);
		String sign = n < 0 ? "-" : "";
		if (abs >= 1_000_000_000L)
		{
			return sign + trim(abs / 1_000_000_000d) + "b";
		}
		if (abs >= 1_000_000L)
		{
			return sign + trim(abs / 1_000_000d) + "m";
		}
		if (abs >= 10_000L)
		{
			return sign + Math.round(abs / 1_000d) + "k";
		}
		return sign + number(abs);
	}

	private static String trim(double v)
	{
		String s = String.format(Locale.ENGLISH, v >= 100 ? "%.0f" : v >= 10 ? "%.1f" : "%.2f", v);
		if (s.contains("."))
		{
			s = s.replaceAll("0+$", "").replaceAll("\\.$", "");
		}
		return s;
	}

	public static String duration(long millis)
	{
		long minutes = millis / 60_000;
		long hours = minutes / 60;
		minutes %= 60;
		if (hours == 0)
		{
			return minutes + " min";
		}
		return hours + "h " + minutes + "m";
	}

	/**
	 * A time as a clock, like the game shows personal bests: "1:12", "12:05" or "1:05:30".
	 */
	public static String clock(double minutes)
	{
		long seconds = Math.max(1, Math.round(minutes * 60));
		long h = seconds / 3600;
		long m = seconds / 60 % 60;
		long s = seconds % 60;
		return h > 0
			? String.format(Locale.ENGLISH, "%d:%02d:%02d", h, m, s)
			: String.format(Locale.ENGLISH, "%d:%02d", m, s);
	}

	public static String hours(double hours)
	{
		if (hours < 1)
		{
			return Math.max(1, Math.round(hours * 60)) + " min";
		}
		if (hours < 10)
		{
			return String.format(Locale.ENGLISH, "%.1fh", hours);
		}
		return Math.round(hours) + "h";
	}

	public static String date(LocalDate date)
	{
		return date == null ? "" : date.format(SHORT_DATE);
	}

	public static String skill(Skill skill)
	{
		return skill.getName();
	}

	public static String percent(double fraction)
	{
		return String.format(Locale.ENGLISH, "%.1f%%", fraction * 100);
	}
}

package com.runejourney.wrapped;

import com.runejourney.model.DayRecord;
import com.runejourney.model.EventType;
import com.runejourney.model.JourneyEvent;
import com.runejourney.planner.Skills;
import com.runejourney.util.Format;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.TextStyle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Random;
import java.util.stream.Collectors;
import lombok.Builder;
import lombok.Singular;
import lombok.Value;
import net.runelite.api.Skill;

/**
 * Turns a week of records into Wrapped slides. Only stats worth celebrating get a slide, and the
 * phrasing, order and theme vary with the week so no two Wrapped feel the same. Pure, so it can be tested.
 */
public final class WrappedBuilder
{
	private static final DateTimeFormatter RANGE = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	public static final int THEMES = 5;

	@Value
	@Builder
	public static class Input
	{
		LocalDate weekStart;
		String player;
		/**
		 * The week's days (missing days are fine).
		 */
		List<DayRecord> days;
		/**
		 * Totals of earlier weeks, oldest first, for "biggest week yet" comparisons.
		 */
		@Singular("earlierWeek")
		List<long[]> earlierWeeks;
		/**
		 * Weekly plan results for this week: [goal name, achieved, target, isMoney].
		 */
		@Singular
		List<Object[]> planResults;
		int playStreak;
		/**
		 * Known item ids by lower-case name (e.g. from imported collection log pages).
		 */
		Map<String, Integer> itemIds;
	}

	private WrappedBuilder()
	{
	}

	/**
	 * [xp, kills, playMillis] for a week, used to compare weeks.
	 */
	public static long[] weekTotals(List<DayRecord> days)
	{
		long xp = 0;
		long kills = 0;
		long play = 0;
		for (DayRecord d : days)
		{
			xp += d.getXpGained();
			kills += d.getBossKills().values().stream().mapToLong(Integer::longValue).sum();
			play += d.getPlayMillis();
		}
		return new long[]{xp, kills, play};
	}

	public static WrappedWeek build(Input in)
	{
		Random rnd = new Random(in.getWeekStart().toEpochDay() * 31 + 7);
		WrappedWeek w = new WrappedWeek();
		w.setWeekStart(in.getWeekStart());
		w.setWeekEnd(in.getWeekStart().plusDays(6));
		w.setPlayer(in.getPlayer());
		w.setTheme((int) Math.floorMod(in.getWeekStart().toEpochDay() / 7, THEMES));

		// ---- Gather the week
		long play = 0;
		long xp = 0;
		long income = 0;
		int deaths = 0;
		int clues = 0;
		int clogSlots = 0;
		int levels = 0;
		int daysPlayed = 0;
		DayRecord longestDay = null;
		Map<String, Long> skillXp = new HashMap<>();
		Map<String, Integer> bosses = new HashMap<>();
		Map<String, int[]> levelRanges = new HashMap<>();
		List<JourneyEvent> events = new ArrayList<>();
		for (DayRecord d : in.getDays())
		{
			play += d.getPlayMillis();
			xp += d.getXpGained();
			income += d.getLootValue() + d.getSkillingIncome();
			deaths += d.getDeaths();
			clues += d.getCluesCompleted();
			clogSlots += d.getCollectionLogSlots();
			levels += d.getLevelsGained();
			if (d.getPlayMillis() > 0)
			{
				daysPlayed++;
				if (longestDay == null || d.getPlayMillis() > longestDay.getPlayMillis())
				{
					longestDay = d;
				}
			}
			d.getSkillXp().forEach((k, v) -> skillXp.merge(k, v, Long::sum));
			d.getBossKills().forEach((k, v) -> bosses.merge(k, v, Integer::sum));
			for (JourneyEvent e : d.getEvents())
			{
				events.add(e);
				if (e.getType() == EventType.LEVEL && e.getSkill() != null && e.getValue() > 0)
				{
					int lvl = (int) e.getValue();
					levelRanges.merge(e.getSkill(), new int[]{lvl - 1, lvl}, (a, b) -> new int[]{Math.min(a[0], b[0]), Math.max(a[1], b[1])});
				}
			}
		}
		int kills = bosses.values().stream().mapToInt(Integer::intValue).sum();

		List<WrappedWeek.Slide> middle = new ArrayList<>();

		// ---- Time played
		if (play > 0)
		{
			WrappedWeek.Slide s = slide(pick(rnd, "This week you played for", "You spent", "Time in Gielinor"),
				play, WrappedWeek.ValueFormat.DURATION, null);
			s.setIcon(WrappedIcons.TIME);
			String days = daysPlayed + (daysPlayed == 1 ? " day" : " days");
			s.setSubtitle(longestDay != null && daysPlayed > 1
				? "across " + days + " · your big one was " + dayName(longestDay) + " (" + Format.duration(longestDay.getPlayMillis()) + ")"
				: "across " + days);
			middle.add(s);
		}

		// ---- XP
		if (xp > 0)
		{
			WrappedWeek.Slide s = slide(pick(rnd, "You gained", "You racked up", "Your skills grew by"),
				xp, WrappedWeek.ValueFormat.COUNT, "XP");
			List<Map.Entry<String, Long>> top = skillXp.entrySet().stream()
				.sorted(Map.Entry.<String, Long>comparingByValue().reversed()).limit(3).collect(Collectors.toList());
			if (!top.isEmpty())
			{
				s.setSubtitle(pick(rnd, "Mostly ", "Led by ", "Your top skill: ") + skillName(top.get(0).getKey())
					+ " (+" + Format.compact(top.get(0).getValue()) + ")");
				s.setIcon(WrappedIcons.skill(top.get(0).getKey()));
				for (Map.Entry<String, Long> e : top)
				{
					line(s, skillName(e.getKey()) + "  +" + Format.compact(e.getValue()), WrappedIcons.skill(e.getKey()));
				}
			}
			middle.add(s);
		}

		// ---- Levels
		if (levels > 0)
		{
			WrappedWeek.Slide s = slide(pick(rnd, "You levelled up", "Level-up fireworks went off"),
				levels, WrappedWeek.ValueFormat.COUNT, levels == 1 ? "time" : "times");
			levelRanges.entrySet().stream()
				.sorted((a, b) -> b.getValue()[1] - a.getValue()[1])
				.limit(4)
				.forEach(e -> line(s, skillName(e.getKey()) + "  " + e.getValue()[0] + " -> " + e.getValue()[1], WrappedIcons.skill(e.getKey())));
			levelRanges.entrySet().stream().max((a, b) -> a.getValue()[1] - b.getValue()[1])
				.ifPresent(e -> s.setIcon(WrappedIcons.skill(e.getKey())));
			boolean has99 = levelRanges.values().stream().anyMatch(r -> r[1] >= 99);
			s.setSubtitle(has99 ? "Including a 99. Legendary." : pick(rnd, "Keep that jingle coming", "Every one of them earned"));
			middle.add(s);
		}

		// ---- Bosses
		if (kills > 0)
		{
			Map.Entry<String, Integer> fav = bosses.entrySet().stream().max(Map.Entry.comparingByValue()).get();
			WrappedWeek.Slide s = slide(pick(rnd, "You killed", "You slayed", "Bosses defeated"),
				kills, WrappedWeek.ValueFormat.COUNT, kills == 1 ? "boss" : "bosses");
			s.setSubtitle("Your favourite was " + fav.getKey() + " (" + Format.number(fav.getValue()) + (fav.getValue() == 1 ? " kill)" : " kills)"));
			s.setIcon(WrappedIcons.boss(fav.getKey()));
			bosses.entrySet().stream().sorted(Map.Entry.<String, Integer>comparingByValue().reversed()).skip(1).limit(3)
				.forEach(e -> line(s, e.getKey() + "  x" + e.getValue(), WrappedIcons.boss(e.getKey())));
			middle.add(s);
		}

		// ---- Income
		if (income > 0)
		{
			WrappedWeek.Slide s = slide(pick(rnd, "You made", "Your coffers grew by", "Loot and profit"),
				income, WrappedWeek.ValueFormat.GP, "gp");
			s.setIcon(WrappedIcons.COINS);
			JourneyEvent best = events.stream().filter(e -> e.getType() == EventType.DROP)
				.max(Comparator.comparingLong(JourneyEvent::getValue)).orElse(null);
			if (best != null && best.getValue() > 0)
			{
				s.setSubtitle("Best drop: " + best.getTitle() + " (" + Format.compact(best.getValue()) + ")");
			}
			middle.add(s);
		}

		// ---- Clues
		if (clues > 0)
		{
			WrappedWeek.Slide s = slide(pick(rnd, "You completed", "Treasure hunted"), clues, WrappedWeek.ValueFormat.COUNT,
				clues == 1 ? "clue scroll" : "clue scrolls");
			s.setSubtitle(pick(rnd, "Uri would be proud", "Another step closer to 3rd age", "The Wise Old Man approves"));
			s.setIcon(WrappedIcons.CLUE);
			middle.add(s);
		}

		// ---- Collection log
		if (clogSlots > 0)
		{
			WrappedWeek.Slide s = slide(pick(rnd, "You added", "Your collection log grew by"), clogSlots, WrappedWeek.ValueFormat.COUNT,
				clogSlots == 1 ? "new slot" : "new slots");
			s.setIcon(WrappedIcons.COLLECTION_LOG);
			events.stream().filter(e -> e.getType() == EventType.COLLECTION_LOG).limit(4)
				.forEach(e -> line(s, e.getTitle(), itemIcon(in, e.getTitle())));
			middle.add(s);
		}

		// ---- Deaths
		if (deaths > 0)
		{
			WrappedWeek.Slide s = slide(pick(rnd, "You died", "Death saw you"), deaths, WrappedWeek.ValueFormat.COUNT,
				deaths == 1 ? "time" : "times");
			s.setSubtitle(deaths >= 20 ? pick(rnd, "Death knows you by name now", "Your gravestone has a loyalty card")
				: deaths >= 5 ? pick(rnd, "Occupational hazard", "The price of greatness") : pick(rnd, "Barely a scratch", "Only a flesh wound"));
			s.setIcon(WrappedIcons.DEATH);
			middle.add(s);
		}

		// ---- Goals completed and weekly plans
		List<JourneyEvent> goals = events.stream().filter(e -> e.getType() == EventType.GOAL_COMPLETED).collect(Collectors.toList());
		for (JourneyEvent g : goals)
		{
			WrappedWeek.Slide s = new WrappedWeek.Slide();
			s.setEyebrow("You completed your goal");
			s.setHeadline(g.getTitle().replaceFirst(" achieved!$", "").replaceFirst("!$", ""));
			s.setSubtitle(g.getDetail() != null ? g.getDetail() : "What a journey");
			s.setIcon(WrappedIcons.GOAL);
			middle.add(s);
		}
		for (Object[] plan : in.getPlanResults())
		{
			long achieved = (long) plan[1];
			long target = (long) plan[2];
			if (target <= 0)
			{
				continue;
			}
			boolean money = (boolean) plan[3];
			WrappedWeek.Slide s = slide(achieved >= target ? "You smashed your weekly plan for" : "Your weekly plan for",
				Double.NaN, WrappedWeek.ValueFormat.NONE, null);
			s.setHeadline((String) plan[0]);
			String amount = money ? Format.compact(achieved) + " / " + Format.compact(target) + " gp"
				: Format.compact(achieved) + " / " + Format.compact(target);
			s.setIcon(WrappedIcons.PLAN);
			s.setSubtitle(amount + (achieved >= target ? " · " + Math.round(achieved * 100.0 / target) + "% of target" : " · next week's plan has been rebalanced"));
			middle.add(s);
		}

		// ---- Records beaten
		List<JourneyEvent> records = events.stream().filter(e -> e.getType() == EventType.RECORD).collect(Collectors.toList());
		if (!records.isEmpty())
		{
			WrappedWeek.Slide s = slide("You broke", records.size(), WrappedWeek.ValueFormat.COUNT,
				records.size() == 1 ? "personal record" : "personal records");
			s.setIcon(WrappedIcons.RECORD);
			records.stream().limit(4).forEach(e -> line(s, e.getTitle(), null));
			middle.add(s);
		}

		// ---- Streak
		if (in.getPlayStreak() >= 3)
		{
			WrappedWeek.Slide s = slide("You're on a streak:", in.getPlayStreak(), WrappedWeek.ValueFormat.COUNT, "days in a row");
			s.setSubtitle(pick(rnd, "Don't break the chain", "Gielinor missed you less than usual"));
			s.setIcon(WrappedIcons.STREAK);
			middle.add(s);
		}

		// ---- Biggest week yet?
		long[] totals = weekTotals(in.getDays());
		if (!in.getEarlierWeeks().isEmpty())
		{
			boolean xpBest = totals[0] > 0 && in.getEarlierWeeks().stream().allMatch(t -> totals[0] > t[0]);
			boolean killBest = totals[1] > 0 && in.getEarlierWeeks().stream().allMatch(t -> totals[1] > t[1]);
			if (xpBest || killBest)
			{
				WrappedWeek.Slide s = new WrappedWeek.Slide();
				s.setEyebrow("Plot twist");
				s.setHeadline(xpBest ? "Your biggest XP week yet" : "Your most bossing ever");
				s.setSubtitle("Out of " + (in.getEarlierWeeks().size() + 1) + " weeks with RuneJourney");
				s.setIcon(WrappedIcons.INTRO);
				middle.add(s);
			}
		}

		// Shuffle the middle a little so each week feels different, keeping XP and time near the start
		List<WrappedWeek.Slide> opening = new ArrayList<>(middle.subList(0, Math.min(2, middle.size())));
		List<WrappedWeek.Slide> rest = new ArrayList<>(middle.subList(opening.size(), middle.size()));
		Collections.shuffle(rest, rnd);
		if (rnd.nextBoolean())
		{
			Collections.reverse(opening);
		}

		// ---- Best moment, near the end
		JourneyEvent moment = bestMoment(events);

		WrappedWeek.Slide intro = new WrappedWeek.Slide();
		intro.setEyebrow("RuneJourney Wrapped");
		intro.setIcon(WrappedIcons.INTRO);
		intro.setHeadline(in.getPlayer() != null ? in.getPlayer() : "Your week");
		intro.setSubtitle(pick(rnd, "Here's how your week went", "Let's look back at your week", "Your week in Gielinor")
			+ " · " + in.getWeekStart().format(RANGE) + " - " + w.getWeekEnd().format(RANGE));
		w.getSlides().add(intro);
		w.getSlides().addAll(opening);
		w.getSlides().addAll(rest);
		if (moment != null)
		{
			WrappedWeek.Slide s = new WrappedWeek.Slide();
			s.setEyebrow("Your moment of the week");
			s.setHeadline(moment.getTitle());
			s.setSubtitle(moment.getDetail());
			s.setScreenshot(moment.getScreenshot());
			s.setIcon(moment.getSkill() != null ? WrappedIcons.skill(moment.getSkill())
				: moment.getType() == EventType.DROP || moment.getType() == EventType.COLLECTION_LOG || moment.getType() == EventType.PET
				? itemIcon(in, moment.getTitle()) : WrappedIcons.GOAL);
			w.getSlides().add(s);
		}

		WrappedWeek.Slide outro = new WrappedWeek.Slide();
		outro.setEyebrow("That's a wrap");
		outro.setHeadline(pick(rnd, "What a week", "See you next week", "Onwards, adventurer"));
		if (play > 0)
		{
			outro.getSummary().add(new String[]{"Played", Format.duration(play)});
		}
		if (xp > 0)
		{
			outro.getSummary().add(new String[]{"XP", Format.compact(xp)});
		}
		if (kills > 0)
		{
			outro.getSummary().add(new String[]{"Boss kills", Format.number(kills)});
		}
		if (income > 0)
		{
			outro.getSummary().add(new String[]{"Income", Format.compact(income)});
		}
		if (levels > 0)
		{
			outro.getSummary().add(new String[]{"Levels", String.valueOf(levels)});
		}
		if (clogSlots > 0)
		{
			outro.getSummary().add(new String[]{"Log slots", String.valueOf(clogSlots)});
		}
		if (clues > 0 && outro.getSummary().size() < 6)
		{
			outro.getSummary().add(new String[]{"Clues", String.valueOf(clues)});
		}
		if (deaths > 0 && outro.getSummary().size() < 6)
		{
			outro.getSummary().add(new String[]{"Deaths", String.valueOf(deaths)});
		}
		outro.setSubtitle("Your next Wrapped arrives on Monday");
		w.getSlides().add(outro);
		return w;
	}

	private static JourneyEvent bestMoment(List<JourneyEvent> events)
	{
		JourneyEvent best = null;
		int bestRank = Integer.MAX_VALUE;
		for (JourneyEvent e : events)
		{
			if (!e.isHighlight())
			{
				continue;
			}
			int rank;
			switch (e.getType())
			{
				case GOAL_COMPLETED:
					rank = 0;
					break;
				case PET:
					rank = 1;
					break;
				case DROP:
					rank = 2;
					break;
				case LEVEL:
					rank = e.getValue() >= 99 ? 1 : 5;
					break;
				case COLLECTION_LOG:
					rank = 3;
					break;
				case PERSONAL_BEST:
					rank = 4;
					break;
				default:
					rank = 6;
			}
			// Prefer moments with a screenshot, then higher value
			if (e.getScreenshot() != null)
			{
				rank -= 1;
			}
			if (rank < bestRank || (rank == bestRank && best != null && e.getValue() > best.getValue()))
			{
				best = e;
				bestRank = rank;
			}
		}
		return best;
	}

	private static void line(WrappedWeek.Slide s, String text, String icon)
	{
		s.getLines().add(text);
		s.getLineIcons().add(icon);
	}

	/**
	 * Icon for an item named in an event: its known id when available, otherwise looked up by name later.
	 */
	private static String itemIcon(Input in, String name)
	{
		String clean = name.replaceFirst("^[\\d,]+ x ", "").replaceFirst("^Pet: ", "");
		Integer id = in.getItemIds() == null ? null : in.getItemIds().get(clean.toLowerCase(Locale.ENGLISH));
		return id != null ? WrappedIcons.item(id) : WrappedIcons.byName(clean);
	}

	private static WrappedWeek.Slide slide(String eyebrow, double value, WrappedWeek.ValueFormat format, String unit)
	{
		WrappedWeek.Slide s = new WrappedWeek.Slide();
		s.setEyebrow(eyebrow);
		s.setValue(value);
		s.setFormat(format);
		s.setUnit(unit);
		return s;
	}

	private static String pick(Random rnd, String... options)
	{
		return options[rnd.nextInt(options.length)];
	}

	private static String skillName(String key)
	{
		Skill s = Skills.parse(key);
		return s == null ? key : s.getName();
	}

	private static String dayName(DayRecord d)
	{
		return LocalDate.parse(d.getDate()).getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH);
	}
}

