	private static void pet(String boss, int itemId)
	{
		BOSS_PETS.put(boss.toLowerCase(Locale.ENGLISH), itemId);
	}

	public static String item(int id)
	{
		return "item:" + id;
	}

	public static String skill(String skill)
	{
		return "skill:" + skill;
	}

	public static String byName(String name)
	{
		// "2 x Dragon bones" -> "Dragon bones"
		return "name:" + name.replaceFirst("^[\\d,]+ x ", "").replaceFirst("^Pet: ", "");
	}

	/**
	 * The boss's pet (or a fitting item), matching variants such as "Theatre of Blood: Hard Mode".
	 */
	public static String boss(String boss)
	{
		String lower = boss.toLowerCase(Locale.ENGLISH);
		Integer best = BOSS_PETS.get(lower);
		if (best == null)
		{
			int bestLength = 0;
			for (Map.Entry<String, Integer> e : BOSS_PETS.entrySet())
			{
				if (lower.startsWith(e.getKey()) && e.getKey().length() > bestLength)
				{
					best = e.getValue();
					bestLength = e.getKey().length();
				}
			}
		}
		return best == null ? BOSS : item(best);
	}
}

package com.runejourney.wrapped;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws Wrapped over the game. While it's showing it takes mouse clicks and a few keys (so clicking
 * through the slides doesn't walk your character around); it never sends input to the game.
 */
@Singleton
class WrappedOverlay extends Overlay implements MouseListener, KeyListener
{
	private final Client client;
	private WrappedPlayer player;

	@Inject
	WrappedOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(Overlay.PRIORITY_HIGHEST);
	}

	void setPlayer(WrappedPlayer player)
	{
		this.player = player;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WrappedPlayer.Frame f = player == null ? null : player.frame();
		if (f == null)
		{
			return null;
		}
		int w = client.getCanvasWidth();
		int h = client.getCanvasHeight();
		player.setLayout(WrappedRenderer.paint(graphics, w, h, f.week, f.index, f.slideMs, f.totalMs, f.screenshot, f.hover, true, player::icon));
		return new Dimension(w, h);
	}

	private boolean active()
	{
		return player != null && player.isInGame();
	}

	private Point canvasPoint()
	{
		net.runelite.api.Point p = client.getMouseCanvasPosition();
		return new Point(p.getX(), p.getY());
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (active())
		{
			player.click(canvasPoint());
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (active())
		{
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		if (active())
		{
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		if (active())
		{
			player.setHover(canvasPoint());
		}
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (active())
		{
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e)
	{
		return e;
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (!active())
		{
			return;
		}
		switch (e.getKeyCode())
		{
			case KeyEvent.VK_ESCAPE:
				player.close();
				e.consume();
				break;
			case KeyEvent.VK_RIGHT:
			case KeyEvent.VK_SPACE:
			case KeyEvent.VK_ENTER:
				player.next();
				e.consume();
				break;
			case KeyEvent.VK_LEFT:
				player.back();
				e.consume();
				break;
			default:
				break;
		}
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}
}

package com.runejourney.wrapped;

import com.runejourney.RuneJourneyConfig;
import com.runejourney.service.JourneyStore;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import com.runejourney.planner.Skills;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.http.api.item.ItemPrice;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Plays a Wrapped: which slide is showing, timing, and whether it's drawn over the game or in
 * its own window. Input arrives from the Swing thread and drawing happens on the client thread, so
 * state is guarded by this object's lock.
 */
@Slf4j
@Singleton
public class WrappedPlayer
{
	private final Client client;
	private final OverlayManager overlayManager;
	private final MouseManager mouseManager;
	private final KeyManager keyManager;
	private final WrappedOverlay overlay;
	private final RuneJourneyConfig config;
	private final JourneyStore store;
	private final ItemManager itemManager;
	private final SkillIconManager skillIconManager;
	/**
	 * Resolved icons by key. Missing icons are cached as EMPTY so lookups aren't repeated every frame.
	 */
	private final Map<String, BufferedImage> iconCache = new ConcurrentHashMap<>();
	private static final BufferedImage EMPTY = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);

	private volatile ExecutorService executor;
	private volatile Supplier<String> profileKey = () -> null;

	private WrappedWeek week;
	private int index;
	private long slideStart;
	private long openedAt;
	private boolean inGame;
	private WrappedWindow window;
	private volatile BufferedImage screenshot;
	private String screenshotName;
	private Point hover;
	private WrappedRenderer.Layout layout;

	@Inject
	WrappedPlayer(Client client, OverlayManager overlayManager, MouseManager mouseManager,
		KeyManager keyManager, WrappedOverlay overlay, RuneJourneyConfig config, JourneyStore store, ItemManager itemManager,
		SkillIconManager skillIconManager)
	{
		this.itemManager = itemManager;
		this.skillIconManager = skillIconManager;
		this.client = client;
		this.overlayManager = overlayManager;
		this.mouseManager = mouseManager;
		this.keyManager = keyManager;
		this.overlay = overlay;
		this.config = config;
		this.store = store;
		overlay.setPlayer(this);
	}

	public void setExecutor(ExecutorService executor, Supplier<String> profileKey)
	{
		this.executor = executor;
		this.profileKey = profileKey;
	}

	/**
	 * Starts playing. Call on the Swing thread.
	 */
	public void play(WrappedWeek w)
	{
		close();
		synchronized (this)
		{
			week = w;
			index = 0;
			openedAt = System.currentTimeMillis();
			slideStart = openedAt;
			inGame = config.wrappedInGame() && client.getGameState() == GameState.LOGGED_IN;
		}
		loadScreenshot();
		// Warm up the icons so they're ready when their slide appears
		for (WrappedWeek.Slide s : w.getSlides())
		{
			icon(s.getIcon());
			s.getLineIcons().forEach(this::icon);
		}

		if (inGame)
		{
			overlayManager.add(overlay);
			mouseManager.registerMouseListener(0, overlay);
			keyManager.registerKeyListener(overlay);
		}
		else
		{
			window = new WrappedWindow(this);
			window.setVisible(true);
		}
	}

	/**
	 * True when playing over the game screen (rather than in a window).
	 */
	public boolean isPlayingInGame()
	{
		return isInGame();
	}

	synchronized boolean isInGame()
	{
		return week != null && inGame;
	}

	/**
	 * The current slide state, advancing automatically when a slide's time is up.
	 */
	synchronized Frame frame()
	{
		if (week == null)
		{
			return null;
		}
		long now = System.currentTimeMillis();
		long elapsed = now - slideStart;
		WrappedWeek.Slide slide = week.getSlides().get(index);
		if (elapsed > WrappedRenderer.durationOf(slide) && index < week.getSlides().size() - 1)
		{
			index++;
			slideStart = now;
			elapsed = 0;
			loadScreenshot();
		}
		BufferedImage img = screenshot;
		String wanted = week.getSlides().get(index).getScreenshot();
		return new Frame(week, index, elapsed, now - openedAt, wanted != null && wanted.equals(screenshotName) ? img : null, hover);
	}

	static final class Frame
	{
		final WrappedWeek week;
		final int index;
		final long slideMs;
		final long totalMs;
		final BufferedImage screenshot;
		final Point hover;

		Frame(WrappedWeek week, int index, long slideMs, long totalMs, BufferedImage screenshot, Point hover)
		{
			this.week = week;
			this.index = index;
			this.slideMs = slideMs;
			this.totalMs = totalMs;
			this.screenshot = screenshot;
			this.hover = hover;
		}
	}

	/**
	 * Game art for an icon key (see {@link WrappedIcons}), or null.
	 */
	BufferedImage icon(String key)
	{
		if (key == null)
		{
			return null;
		}
		BufferedImage img = iconCache.computeIfAbsent(key, this::load);
		return img == EMPTY ? null : img;
	}

	private BufferedImage load(String key)
	{
		try
		{
			if (key.startsWith("skill:"))
			{
				Skill skill = Skills.parse(key.substring("skill:".length()));
				return skill == null ? EMPTY : skillIconManager.getSkillImage(skill, false);
			}
			if (key.startsWith("item:"))
			{
				String[] parts = key.split(":");
				int id = Integer.parseInt(parts[1]);
				int qty = parts.length > 2 ? Integer.parseInt(parts[2]) : 1;
				return itemManager.getImage(id, qty, qty > 1);
			}
			if (key.startsWith("name:"))
			{
				String name = key.substring("name:".length());
				for (ItemPrice price : itemManager.search(name))
				{
					if (price.getName().equalsIgnoreCase(name))
					{
						return itemManager.getImage(price.getId());
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to load Wrapped icon {}", key, e);
		}
		return EMPTY;
	}

	synchronized void setLayout(WrappedRenderer.Layout layout)
	{
		this.layout = layout;
	}

	synchronized void setHover(Point p)
	{
		hover = p;
	}

	/**
	 * A click on the slides: buttons act, anywhere else moves on.
	 */
	void click(Point p)
	{
		WrappedRenderer.Layout l;
		synchronized (this)
		{
			l = layout;
		}
		if (l != null && l.getBack() != null && l.getBack().contains(p))
		{
			back();
		}
		else if (l != null && l.getClose() != null && l.getClose().contains(p) && l.getClose() != l.getNext())
		{
			close();
		}
		else
		{
			next();
		}
	}

	void next()
	{
		boolean finished;
		synchronized (this)
		{
			if (week == null)
			{
				return;
			}
			finished = index >= week.getSlides().size() - 1;
			if (!finished)
			{
				index++;
				slideStart = System.currentTimeMillis();
			}
		}
		if (finished)
		{
			close();
		}
		else
		{
			loadScreenshot();
		}
	}

	void back()
	{
		synchronized (this)
		{
			if (week == null || index == 0)
			{
				return;
			}
			index--;
			slideStart = System.currentTimeMillis();
		}
		loadScreenshot();
	}

	/**
	 * Stops playing. Safe to call from any thread.
	 */
	public void close()
	{
		boolean wasInGame;
		WrappedWindow w;
		synchronized (this)
		{
			if (week == null && window == null)
			{
				return;
			}
			wasInGame = inGame;
			w = window;
			week = null;
			window = null;
			screenshot = null;
			screenshotName = null;
			layout = null;
			hover = null;
		}
		if (wasInGame)
		{
			overlayManager.remove(overlay);
			mouseManager.unregisterMouseListener(overlay);
			keyManager.unregisterKeyListener(overlay);
		}
		if (w != null)
		{
			SwingUtilities.invokeLater(w::dispose);
		}
	}

	private void loadScreenshot()
	{
		String name;
		synchronized (this)
		{
			if (week == null)
			{
				return;
			}
			name = week.getSlides().get(index).getScreenshot();
			if (name == null || name.equals(screenshotName))
			{
				return;
			}
			screenshotName = name;
			screenshot = null;
		}
		String key = profileKey.get();
		ExecutorService exec = executor;
		if (key == null || exec == null || exec.isShutdown())
		{
			return;
		}
		exec.submit(() ->
		{
			try
			{
				BufferedImage img = store.readScreenshot(key, name);
				synchronized (this)
				{
					if (name.equals(screenshotName))
					{
						screenshot = img;
					}
				}
			}
			catch (IOException e)
			{
				log.debug("Unable to load Wrapped screenshot {}", name, e);
			}
		});
	}
}

package com.runejourney.wrapped;

import com.runejourney.util.Format;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import lombok.Getter;
import net.runelite.client.ui.FontManager;

/**
 * Draws a Wrapped slide with time-based animation. Used by both the in-game overlay and the window,
 * so it only depends on a Graphics2D, a size and the elapsed time.
 */
public final class WrappedRenderer
{
	/**
	 * Base time a slide stays up before advancing on its own, plus time per extra line.
	 */
	public static final long SLIDE_MS = 6500;
	public static final long LINE_MS = 700;

	/**
	 * [top, bottom, accent] per theme.
	 */
	private static final Color[][] PALETTES = {
		{new Color(0x1B1035), new Color(0x4A1F6E), new Color(0xF2C14E)},
		{new Color(0x0B2A2F), new Color(0x13705F), new Color(0xB8F2E6)},
		{new Color(0x2B1407), new Color(0x93511A), new Color(0xFFE08A)},
		{new Color(0x0D1B3E), new Color(0x2356A8), new Color(0x9AD1FF)},
		{new Color(0x2A0B0B), new Color(0x8E2525), new Color(0xFFB199)},
	};

	private static final Color DIM = new Color(0, 0, 0, 170);

	/**
	 * Button areas from the last paint, for click handling.
	 */
	@Getter
	public static class Layout
	{
		private Rectangle back;
		private Rectangle next;
		private Rectangle close;
		private Rectangle card;
	}

	private WrappedRenderer()
	{
	}

	public static long durationOf(WrappedWeek.Slide s)
	{
		return SLIDE_MS + Math.max(0, s.getLines().size() - 1) * LINE_MS + (s.getSummary().isEmpty() ? 0 : 2500);
	}

	public static Layout paint(Graphics2D g, int w, int h, WrappedWeek week, int index, long slideMs, long totalMs,
		BufferedImage screenshot, Point hover, boolean dimBackground, Function<String, BufferedImage> icons)
	{
		Layout layout = new Layout();
		Color[] palette = PALETTES[Math.floorMod(week.getTheme(), PALETTES.length)];
		Color accent = palette[2];
		WrappedWeek.Slide slide = week.getSlides().get(index);

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		Composite base = g.getComposite();

		if (dimBackground)
		{
			g.setColor(DIM);
			g.fillRect(0, 0, w, h);
		}

		// Card
		int cw = dimBackground ? Math.min(w - 24, Math.max(460, (int) (w * 0.66))) : w;
		int ch = dimBackground ? Math.min(h - 24, Math.max(380, (int) (h * 0.84))) : h;
		int cx = (w - cw) / 2;
		int cy = (h - ch) / 2;
		layout.card = new Rectangle(cx, cy, cw, ch);
		Shape card = new RoundRectangle2D.Double(cx, cy, cw, ch, dimBackground ? 26 : 0, dimBackground ? 26 : 0);

		// The card pops in on open
		double open = ease(clamp(totalMs / 350.0));
		AffineTransform at = g.getTransform();
		if (open < 1)
		{
			double scale = 0.92 + 0.08 * open;
			g.translate(cx + cw / 2.0, cy + ch / 2.0);
			g.scale(scale, scale);
			g.translate(-(cx + cw / 2.0), -(cy + ch / 2.0));
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) open));
		}

		// Background: gradient that slowly breathes between slides
		double breathe = 0.5 + 0.5 * Math.sin(totalMs / 2400.0);
		Color top = mix(palette[0], palette[1], 0.15 * breathe);
		g.setPaint(new GradientPaint(cx, cy, top, cx + cw * 0.3f, cy + ch, palette[1]));
		g.fill(card);
		java.awt.Shape oldClip = g.getClip();
		g.clip(card);

		// Soft light blobs and drifting sparkles
		drawBlob(g, cx + cw * (0.2 + 0.1 * Math.sin(totalMs / 3100.0)), cy + ch * 0.25, cw * 0.5, accent, 0.10f);
		drawBlob(g, cx + cw * (0.85 + 0.05 * Math.cos(totalMs / 2700.0)), cy + ch * 0.8, cw * 0.45, Color.WHITE, 0.06f);
		for (int i = 0; i < 26; i++)
		{
			long s = (i * 7919L + week.getTheme() * 104729L) & 0xFFFF;
			double speed = 0.012 + (s % 13) * 0.002;
			double px = cx + ((s * 37 % 1000) / 1000.0) * cw + Math.sin((totalMs / 1000.0) + i) * 8;
			double py = cy + ch - ((totalMs * speed + s * 3) % (ch + 40)) + 20;
			float a = 0.15f + (s % 5) * 0.06f;
			int r = 2 + (int) (s % 3);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, a * (float) open));
			g.setColor(i % 3 == 0 ? accent : Color.WHITE);
			g.fillOval((int) px, (int) py, r, r);
		}
		g.setComposite(open < 1 ? AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) open) : base);

		// Progress segments
		int n = week.getSlides().size();
		int pad = Math.max(16, cw / 30);
		int gap = 4;
		int segW = (cw - pad * 2 - gap * (n - 1)) / Math.max(1, n);
		double slideProgress = clamp(slideMs / (double) durationOf(slide));
		for (int i = 0; i < n; i++)
		{
			int sx = cx + pad + i * (segW + gap);
			int sy = cy + pad;
			g.setColor(new Color(255, 255, 255, 60));
			g.fillRoundRect(sx, sy, segW, 4, 4, 4);
			double fill = i < index ? 1 : i == index ? slideProgress : 0;
			g.setColor(Color.WHITE);
			g.fillRoundRect(sx, sy, (int) (segW * fill), 4, 4, 4);
		}

		// Brand
		Font small = FontManager.getRunescapeSmallFont();
		g.setFont(small.deriveFont((float) Math.max(16, ch / 28)));
		g.setColor(new Color(255, 255, 255, 170));
		g.drawString("RuneJourney Wrapped", cx + pad, cy + pad + 26);
		String range = Format.date(week.getWeekStart()) + " - " + Format.date(week.getWeekEnd());
		FontMetrics fmSmall = g.getFontMetrics();
		g.drawString(range, cx + cw - pad - fmSmall.stringWidth(range), cy + pad + 26);

		// Content
		BufferedImage icon = slide.getIcon() == null ? null : icons.apply(slide.getIcon());
		// Slides with lists, summaries or screenshots need the room, so everything above them shrinks
		boolean dense = !slide.getLines().isEmpty() || !slide.getSummary().isEmpty() || slide.getScreenshot() != null;
		int contentTop = cy + (int) (ch * (icon != null ? (dense ? 0.1 : 0.11) : (dense ? 0.14 : 0.2)));
		int contentWidth = cw - pad * 4;
		int centerX = cx + cw / 2;
		int y = contentTop;

		Font regular = FontManager.getRunescapeFont();
		Font bold = FontManager.getRunescapeBoldFont();

		// Buttons sit along the bottom; content must stay above them
		g.setFont(regular.deriveFont((float) Math.max(18, ch / 24)));
		FontMetrics fb = g.getFontMetrics();
		int by = cy + ch - pad - fb.getHeight() - 8;
		g.setFont(small.deriveFont((float) Math.max(14, ch / 32)));
		int hintY = by - 10;
		int contentBottom = hintY - g.getFontMetrics().getHeight() - 6;

		if (icon != null)
		{
			int size = (int) (dense ? Math.min(64, ch * 0.11) : Math.min(104, ch * 0.16));
			// Pops in with a little overshoot, then floats gently
			double t = clamp(slideMs / 550.0);
			double pop = t < 1 ? backEase(t) : 1;
			double bob = Math.sin(totalMs / 520.0) * size * 0.04;
			int iconY = y + size / 2;
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) (0.16 * clamp(t * 2))));
			g.setColor(accent);
			int glow = (int) (size * 1.5 * pop);
			g.fillOval(centerX - glow / 2, iconY - glow / 2, glow, glow);
			g.setComposite(open < 1 ? AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) open) : base);
			drawIcon(g, icon, centerX, (int) (iconY + bob), (int) (size * pop));
			y += size + (int) (ch * 0.02);
		}

		if (slide.getEyebrow() != null)
		{
			double t = ease(clamp(slideMs / 450.0));
			g.setFont(regular.deriveFont((float) Math.max(20, ch / 18)));
			y += g.getFontMetrics().getAscent();
			drawCentered(g, slide.getEyebrow(), centerX, y + (int) ((1 - t) * 14), accent, t);
			y += (int) (ch * 0.03);
		}

		if (!Double.isNaN(slide.getValue()))
		{
			double t = ease(clamp((slideMs - 300) / 1500.0));
			double pop = slideMs < 300 ? 0 : slideMs < 1900 ? 0.9 + 0.1 * t : 1 + 0.06 * Math.max(0, 1 - (slideMs - 1900) / 300.0);
			String text = formatValue(slide.getValue() * t, slide.getFormat());
			float size = (float) Math.max(36, dense ? ch / 7.0 : ch / 5.2);
			g.setFont(bold.deriveFont(size));
			FontMetrics fm = g.getFontMetrics();
			while (fm.stringWidth(formatValue(slide.getValue(), slide.getFormat())) > contentWidth && size > 24)
			{
				size -= 4;
				g.setFont(bold.deriveFont(size));
				fm = g.getFontMetrics();
			}
			y += fm.getAscent();
			AffineTransform before = g.getTransform();
			g.translate(centerX, y - fm.getAscent() / 2.0);
			g.scale(Math.max(0.01, pop), Math.max(0.01, pop));
			g.translate(-centerX, -(y - fm.getAscent() / 2.0));
			drawCentered(g, text, centerX, y, Color.WHITE, clamp((slideMs - 300) / 300.0));
			g.setTransform(before);
			y += fm.getDescent();
		}
		else if (slide.getHeadline() != null)
		{
			double t = ease(clamp((slideMs - 250) / 700.0));
			float size = (float) Math.max(30, ch / 9);
			g.setFont(bold.deriveFont(size));
			List<String> rows = wrap(g, slide.getHeadline(), contentWidth);
			while (rows.size() > 3 && size > 22)
			{
				size -= 4;
				g.setFont(bold.deriveFont(size));
				rows = wrap(g, slide.getHeadline(), contentWidth);
			}
			FontMetrics fm = g.getFontMetrics();
			for (String row : rows)
			{
				y += fm.getAscent();
				drawCentered(g, row, centerX, y + (int) ((1 - t) * 20), Color.WHITE, t);
				y += fm.getDescent() + 4;
			}
		}

		if (slide.getUnit() != null)
		{
			double t = ease(clamp((slideMs - 900) / 500.0));
			g.setFont(regular.deriveFont((float) Math.max(20, dense ? ch / 18 : ch / 14)));
			y += g.getFontMetrics().getAscent();
			drawCentered(g, slide.getUnit(), centerX, y, new Color(255, 255, 255, 230), t);
		}

		if (slide.getSubtitle() != null)
		{
			double t = ease(clamp((slideMs - 1300) / 600.0));
			g.setFont(regular.deriveFont((float) Math.max(18, ch / 22)));
			FontMetrics fm = g.getFontMetrics();
			y += (int) (ch * (dense ? 0.02 : 0.04));
			for (String row : wrap(g, slide.getSubtitle(), contentWidth))
			{
				y += fm.getAscent();
				drawCentered(g, row, centerX, y + (int) ((1 - t) * 10), accent, t);
				y += fm.getDescent();
			}
		}

		// Supporting lines, one after another
		if (!slide.getLines().isEmpty())
		{
			g.setFont(regular.deriveFont((float) Math.max(17, ch / 24)));
			FontMetrics fm = g.getFontMetrics();
			int iconSize = Math.max(24, fm.getHeight() + 6);
			int rowH = Math.max(fm.getHeight(), iconSize) + 6;
			y += (int) (ch * 0.03);
			for (int i = 0; i < slide.getLines().size(); i++)
			{
				if (y + rowH > contentBottom)
				{
					break;
				}
				double t = ease(clamp((slideMs - 1900 - i * 260) / 450.0));
				String line = slide.getLines().get(i);
				String key = i < slide.getLineIcons().size() ? slide.getLineIcons().get(i) : null;
				BufferedImage lineIcon = key == null ? null : icons.apply(key);
				int iconW = lineIcon != null ? iconSize + 6 : 0;
				int lw = fm.stringWidth(line) + 24 + iconW;
				int lx = centerX - lw / 2 - (int) ((1 - t) * 30);
				float alpha = (float) (t * (open < 1 ? open : 1));
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.22f * alpha));
				g.setColor(Color.BLACK);
				g.fillRoundRect(lx, y, lw, rowH - 4, rowH - 4, rowH - 4);
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
				if (lineIcon != null)
				{
					drawIcon(g, lineIcon, lx + 12 + iconSize / 2, y + (rowH - 4) / 2, iconSize);
				}
				g.setColor(Color.WHITE);
				g.drawString(line, lx + 12 + iconW, y + (rowH - 4 + fm.getAscent() - fm.getDescent()) / 2);
				g.setComposite(base);
				y += rowH;
			}
		}

		// Screenshot for the best moment
		if (screenshot != null)
		{
			double t = ease(clamp((slideMs - 1000) / 700.0));
			int maxW = (int) (cw * 0.6);
			int maxH = cy + ch - pad * 4 - y - 20;
			if (maxH > 60)
			{
				double scale = Math.min(maxW / (double) screenshot.getWidth(), maxH / (double) screenshot.getHeight());
				int iw = (int) (screenshot.getWidth() * scale * (0.9 + 0.1 * t));
				int ih = (int) (screenshot.getHeight() * scale * (0.9 + 0.1 * t));
				int ix = centerX - iw / 2;
				int iy = y + 20;
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) t));
				Shape oldClip2 = g.getClip();
				g.clip(new RoundRectangle2D.Double(ix, iy, iw, ih, 16, 16));
				g.drawImage(screenshot, ix, iy, iw, ih, null);
				g.setClip(oldClip2);
				g.setColor(accent);
				g.setStroke(new BasicStroke(2f));
				g.draw(new RoundRectangle2D.Double(ix, iy, iw, ih, 16, 16));
				g.setComposite(base);
			}
		}

		// Summary grid on the last slide
		if (!slide.getSummary().isEmpty())
		{
			int cols = 3;
			int rowsCount = (slide.getSummary().size() + cols - 1) / cols;
			int tileW = Math.min(200, (contentWidth - 20) / cols);
			int space = contentBottom - (y + 24) - 10 * (rowsCount - 1);
			int tileH = Math.max(40, Math.min(ch / 7, space / Math.max(1, rowsCount)));
			// Show only as many rows as fit above the buttons
			int rowsFit = Math.max(1, (contentBottom - (y + 24) + 10) / (tileH + 10));
			int shown = Math.min(slide.getSummary().size(), rowsFit * cols);
			int gridW = cols * tileW + (cols - 1) * 10;
			int gx = centerX - gridW / 2;
			int gy = y + 24;
			for (int i = 0; i < shown; i++)
			{
				double t = ease(clamp((slideMs - 700 - i * 180) / 450.0));
				int tx = gx + (i % cols) * (tileW + 10);
				int ty = gy + (i / cols) * (tileH + 10) + (int) ((1 - t) * 16);
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) (0.28 * t)));
				g.setColor(Color.BLACK);
				g.fillRoundRect(tx, ty, tileW, tileH, 14, 14);
				g.setComposite(base);
				String[] stat = slide.getSummary().get(i);
				float valueSize = (float) Math.min(tileH * 0.42, Math.max(18, tileH / 2.6));
				float labelSize = (float) Math.min(tileH * 0.26, Math.max(13, tileH / 5.0));
				g.setFont(bold.deriveFont(valueSize));
				FontMetrics fv = g.getFontMetrics();
				drawCentered(g, stat[1], tx + tileW / 2, ty + (int) (tileH * 0.12) + fv.getAscent(), Color.WHITE, t);
				g.setFont(small.deriveFont(labelSize));
				drawCentered(g, stat[0], tx + tileW / 2, ty + tileH - (int) (tileH * 0.12), accent, t);
			}
			if (rowsCount > 0)
			{
				y = gy + rowsCount * (tileH + 10);
			}
		}

		// Buttons
		g.setComposite(open < 1 ? AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) open) : base);
		g.setFont(regular.deriveFont((float) Math.max(18, ch / 24)));
		boolean last = index == n - 1;
		layout.next = button(g, last ? "Close" : "Next >", cx + cw - pad, by, true, accent, hover, fb);
		layout.close = last ? layout.next : button(g, "Close", layout.next.x - 10, by, true, accent, hover, fb);
		layout.back = index > 0 ? button(g, "< Back", cx + pad, by, false, accent, hover, fb) : null;
		g.setFont(small.deriveFont((float) Math.max(14, ch / 32)));
		drawCentered(g, "Click to continue · Esc to close", centerX, hintY, new Color(255, 255, 255, 120), 1);

		g.setClip(oldClip);
		g.setTransform(at);
		g.setComposite(base);
		return layout;
	}

	private static Rectangle button(Graphics2D g, String text, int x, int y, boolean alignRight, Color accent, Point hover, FontMetrics fm)
	{
		int bw = fm.stringWidth(text) + 28;
		int bh = fm.getHeight() + 8;
		int bx = alignRight ? x - bw : x;
		Rectangle r = new Rectangle(bx, y, bw, bh);
		boolean over = hover != null && r.contains(hover);
		g.setColor(over ? accent : new Color(255, 255, 255, 40));
		g.fillRoundRect(bx, y, bw, bh, bh, bh);
		g.setColor(over ? Color.BLACK : Color.WHITE);
		g.drawString(text, bx + 14, y + 4 + fm.getAscent());
		return r;
	}

	/**
	 * Draws game art centred on a point, scaled with nearest-neighbour so pixels stay crisp.
	 */
	private static void drawIcon(Graphics2D g, BufferedImage img, int cx, int cy, int size)
	{
		if (img == null || size <= 0 || img.getWidth() <= 0 || img.getHeight() <= 0)
		{
			return;
		}
		double scale = size / (double) Math.max(img.getWidth(), img.getHeight());
		int w = (int) Math.round(img.getWidth() * scale);
		int h = (int) Math.round(img.getHeight() * scale);
		Object old = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(img, cx - w / 2, cy - h / 2, w, h, null);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, old == null ? RenderingHints.VALUE_INTERPOLATION_BILINEAR : old);
	}

	/**
	 * Ease with a small overshoot, for things that pop in.
	 */
	private static double backEase(double t)
	{
		double c1 = 1.70158;
		double c3 = c1 + 1;
		return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
	}

	private static void drawBlob(Graphics2D g, double x, double y, double size, Color c, float alpha)
	{
		Composite old = g.getComposite();
		for (int i = 0; i < 6; i++)
		{
			double s = size * (1 - i * 0.14);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha / 3));
			g.setColor(c);
			g.fillOval((int) (x - s / 2), (int) (y - s / 2), (int) s, (int) s);
		}
		g.setComposite(old);
	}

	private static void drawCentered(Graphics2D g, String text, int cx, int y, Color color, double alpha)
	{
		if (alpha <= 0)
		{
			return;
		}
		Composite old = g.getComposite();
		float a = (float) Math.min(1, alpha);
		if (old instanceof AlphaComposite)
		{
			a *= ((AlphaComposite) old).getAlpha();
		}
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, a));
		FontMetrics fm = g.getFontMetrics();
		int x = cx - fm.stringWidth(text) / 2;
		g.setColor(color);
		g.drawString(text, x, y);
		g.setComposite(old);
	}

	private static List<String> wrap(Graphics2D g, String text, int width)
	{
		List<String> rows = new ArrayList<>();
		FontMetrics fm = g.getFontMetrics();
		StringBuilder row = new StringBuilder();
		for (String word : text.split(" "))
		{
			String next = row.length() == 0 ? word : row + " " + word;
			if (fm.stringWidth(next) > width && row.length() > 0)
			{
				rows.add(row.toString());
				row = new StringBuilder(word);
			}
			else
			{
				row = new StringBuilder(next);
			}
		}
		if (row.length() > 0)
		{
			rows.add(row.toString());
		}
		return rows;
	}

	static String formatValue(double v, WrappedWeek.ValueFormat format)
	{
		long n = Math.round(v);
		switch (format)
		{
			case GP:
				return Format.compact(n);
			case DURATION:
				return Format.duration(n);
			default:
				return Format.number(n);
		}
	}

	private static double clamp(double v)
	{
		return Math.max(0, Math.min(1, v));
	}

	private static double ease(double t)
	{
		return 1 - Math.pow(1 - t, 3);
	}

	private static Color mix(Color a, Color b, double t)
	{
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}
}

package com.runejourney.wrapped;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import lombok.Data;

/**
 * A week's "Wrapped": an ordered set of slides celebrating what the player did.
 */
@Data
public class WrappedWeek
{
	public enum ValueFormat
	{
		NONE, COUNT, GP, DURATION
	}

	@Data
	public static class Slide
	{
		/**
		 * Small line above the headline, e.g. "This week you killed".
		 */
		private String eyebrow;
		/**
		 * Number to count up to, or NaN when the headline is text.
		 */
		private double value = Double.NaN;
		private ValueFormat format = ValueFormat.NONE;
		/**
		 * Text shown instead of a number, e.g. a goal or boss name.
		 */
		private String headline;
		/**
		 * Word under the number, e.g. "bosses".
		 */
		private String unit;
		private String subtitle;
		private List<String> lines = new ArrayList<>();
		/**
		 * Icon keys (see {@link WrappedIcons}) for each line, or null entries for none.
		 */
		private List<String> lineIcons = new ArrayList<>();
		/**
		 * Big illustration shown above the slide's text.
		 */
		private String icon;
		/**
		 * Screenshot file for the "best moment" slide.
		 */
		private String screenshot;
		/**
		 * The final summary slide shows a grid of stats instead of one number.
		 */
		private List<String[]> summary = new ArrayList<>();
	}

	private LocalDate weekStart;
	private LocalDate weekEnd;
	private String player;
	/**
	 * Picks the colour palette, so each week looks different.
	 */
	private int theme;
	private List<Slide> slides = new ArrayList<>();
}

package com.runejourney.wrapped;

import com.runejourney.ui.Icons;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import javax.swing.JComponent;
import javax.swing.JFrame;
import javax.swing.Timer;
import javax.swing.WindowConstants;

/**
 * Plays Wrapped in its own window, used when you're not logged in or have turned off the in-game view.
 */
class WrappedWindow extends JFrame
{
	private final Timer timer;

	WrappedWindow(WrappedPlayer player)
	{
		setTitle("RuneJourney Wrapped");
		setIconImage(Icons.navIcon());
		setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);

		JComponent canvas = new JComponent()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				WrappedPlayer.Frame f = player.frame();
				if (f == null)
				{
					return;
				}
				player.setLayout(WrappedRenderer.paint((Graphics2D) g, getWidth(), getHeight(), f.week, f.index, f.slideMs,
					f.totalMs, f.screenshot, f.hover, false, player::icon));
			}
		};
		canvas.setPreferredSize(new Dimension(900, 600));
		canvas.setFocusable(true);
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				player.click(e.getPoint());
			}

			@Override
			public void mouseMoved(MouseEvent e)
			{
				player.setHover(e.getPoint());
			}
		};
		canvas.addMouseListener(mouse);
		canvas.addMouseMotionListener(mouse);
		canvas.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				switch (e.getKeyCode())
				{
					case KeyEvent.VK_ESCAPE:
						player.close();
						break;
					case KeyEvent.VK_RIGHT:
					case KeyEvent.VK_SPACE:
					case KeyEvent.VK_ENTER:
						player.next();
						break;
					case KeyEvent.VK_LEFT:
						player.back();
						break;
					default:
						break;
				}
			}
		});
		setContentPane(canvas);
		pack();
		setLocationRelativeTo(null);

		// ~60fps while open
		timer = new Timer(16, e -> canvas.repaint());
		timer.start();
		addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosed(WindowEvent e)
			{
				timer.stop();
				player.close();
			}

			@Override
			public void windowOpened(WindowEvent e)
			{
				canvas.requestFocusInWindow();
			}
		});
	}
}

package com.runejourney;

import com.runejourney.model.DayRecord;
import com.runejourney.report.Analytics;
import com.runejourney.report.CsvExport;
import com.runejourney.report.Granularity;
import com.runejourney.report.Metric;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AnalyticsTest
{
	private static DayRecord day(LocalDate date, long xp, double hours, int zulrahKills)
	{
		DayRecord d = new DayRecord(date.toString());
		d.setXpGained(xp);
		d.getSkillXp().put("SLAYER", xp);
		d.setPlayMillis((long) (hours * 3_600_000));
		if (zulrahKills > 0)
		{
			d.getBossKills().put("Zulrah", zulrahKills);
		}
		return d;
	}

	// Monday 7 Sep 2026 to Sunday 20 Sep 2026: two full weeks
	private static final LocalDate FROM = LocalDate.of(2026, 9, 7);
	private static final LocalDate TO = LocalDate.of(2026, 9, 20);

	private static List<DayRecord> sample()
	{
		List<DayRecord> days = new ArrayList<>();
		days.add(day(FROM, 100_000, 2, 10));
		days.add(day(FROM.plusDays(1), 50_000, 1, 0));
		days.add(day(FROM.plusDays(8), 300_000, 3, 20));
		return days;
	}

	@Test
	public void dailySeriesFillsGaps()
	{
		List<Analytics.Bucket> series = Analytics.series(sample(), FROM, TO, Metric.XP, null, Granularity.DAY);
		assertEquals(14, series.size());
		assertEquals(100_000, series.get(0).getValue(), 0);
		assertEquals(0, series.get(2).getValue(), 0);
		assertEquals(300_000, series.get(8).getValue(), 0);
	}

	@Test
	public void weeklyBucketsAndPerHourRates()
	{
		List<Analytics.Bucket> weeks = Analytics.series(sample(), FROM, TO, Metric.XP, null, Granularity.WEEK);
		assertEquals(2, weeks.size());
		assertEquals(150_000, weeks.get(0).getValue(), 0);
		assertEquals(300_000, weeks.get(1).getValue(), 0);

		// 150k over 3 hours in week one
		List<Analytics.Bucket> rates = Analytics.series(sample(), FROM, TO, Metric.XP_PER_HOUR, null, Granularity.WEEK);
		assertEquals(50_000, rates.get(0).getValue(), 0.001);

		List<Analytics.Bucket> cumulative = Analytics.cumulative(weeks, Metric.XP);
		assertEquals(450_000, cumulative.get(1).getValue(), 0);
	}

	@Test
	public void statsCompareWithPreviousPeriod()
	{
		List<DayRecord> previous = new ArrayList<>();
		previous.add(day(FROM.minusDays(3), 225_000, 2, 0));
		Analytics.Stats stats = Analytics.stats(sample(), FROM, TO, Metric.XP, null, Granularity.DAY, previous);
		assertEquals(450_000, stats.getTotal(), 0);
		assertEquals(3, stats.getActiveDays());
		assertEquals(150_000, stats.getPerActiveDay(), 0);
		assertEquals(300_000, stats.getBest().getValue(), 0);
		assertEquals(1.0, stats.change(), 0.0001);
	}

	@Test
	public void breakdownsAndWeekdays()
	{
		List<Analytics.Entry> bosses = Analytics.breakdown(sample(), FROM, TO, Metric.KILLS);
		assertEquals(1, bosses.size());
		assertEquals(30, bosses.get(0).getValue(), 0);

		// Two Mondays in range: 100k and 0 -> average 50k; Tuesday 50k + 300k over 2 Tuesdays
		List<Analytics.Entry> weekdays = Analytics.byWeekday(sample(), FROM, TO, Metric.XP, null);
		assertEquals("Mon", weekdays.get(0).getLabel());
		assertEquals(50_000, weekdays.get(0).getValue(), 0);
		assertEquals(175_000, weekdays.get(1).getValue(), 0);
	}

	@Test
	public void awayXpIsExcludedFromRates()
	{
		DayRecord d = day(FROM, 100_000, 1, 0);
		d.setOfflineXp(40_000);
		d.getOfflineSkillXp().put("SLAYER", 40_000L);
		List<DayRecord> days = new ArrayList<>();
		days.add(d);
		assertEquals(100_000, Analytics.series(days, FROM, FROM, Metric.XP, null, Granularity.DAY).get(0).getValue(), 0);
		assertEquals(60_000, Analytics.series(days, FROM, FROM, Metric.XP_PER_HOUR, null, Granularity.DAY).get(0).getValue(), 0.001);
		assertEquals(60_000, Analytics.series(days, FROM, FROM, Metric.XP_PER_HOUR, "SLAYER", Granularity.DAY).get(0).getValue(), 0.001);
	}

	@Test
	public void netWorthCarriesForwardAndIsNotSummed()
	{
		List<DayRecord> days = new ArrayList<>();
		DayRecord a = day(FROM, 0, 1, 0);
		a.getSnapshot().put("wealth", 500_000_000L);
		DayRecord b = day(FROM.plusDays(9), 0, 1, 0);
		b.getSnapshot().put("wealth", 650_000_000L);
		days.add(a);
		days.add(b);

		List<Analytics.Bucket> daily = Analytics.series(days, FROM, TO, Metric.NET_WORTH, null, Granularity.DAY);
		assertEquals(500_000_000, daily.get(5).getValue(), 0);
		assertEquals(650_000_000, daily.get(13).getValue(), 0);
		List<Analytics.Bucket> weekly = Analytics.series(days, FROM, TO, Metric.NET_WORTH, null, Granularity.WEEK);
		assertEquals(500_000_000, weekly.get(0).getValue(), 0);
		assertEquals(650_000_000, weekly.get(1).getValue(), 0);

		Analytics.Stats stats = Analytics.stats(days, FROM, TO, Metric.NET_WORTH, null, Granularity.DAY, null);
		assertEquals(650_000_000, stats.getTotal(), 0);
		assertEquals(150_000_000, stats.getPerActiveDay(), 0);
	}

	@Test
	public void csvHasOneRowPerDay()
	{
		String csv = CsvExport.export(sample(), FROM, TO);
		String[] lines = csv.split("\n");
		assertEquals(15, lines.length);
		assertTrue(lines[0].contains("\"Zulrah kills\""));
		assertTrue(lines[0].contains("\"Slayer XP\""));
		assertTrue(lines[1].startsWith("2026-09-07,2.00,100000"));
	}
}

package com.runejourney;

import com.runejourney.service.ChatParser;
import static com.runejourney.service.ChatParser.Kind.CLUE;
import static com.runejourney.service.ChatParser.Kind.COLLECTION_LOG;
import static com.runejourney.service.ChatParser.Kind.COMBAT_TASK;
import static com.runejourney.service.ChatParser.Kind.DIARY_TIER;
import static com.runejourney.service.ChatParser.Kind.DUPLICATE_PET;
import static com.runejourney.service.ChatParser.Kind.KILL_COUNT;
import static com.runejourney.service.ChatParser.Kind.PERSONAL_BEST;
import static com.runejourney.service.ChatParser.Kind.PET;
import static com.runejourney.service.ChatParser.Kind.QUEST;
import static com.runejourney.service.ChatParser.Kind.SLAYER_TASK;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class ChatParserTest
{
	@Test
	public void killCounts()
	{
		ChatParser.Result r = ChatParser.parse("Your Zulrah kill count is: 1,284.");
		assertEquals(KILL_COUNT, r.getKind());
		assertEquals("Zulrah", r.getName());
		assertEquals(1284, r.getCount());

		r = ChatParser.parse("Your completed Theatre of Blood count is: 284.");
		assertEquals("Theatre of Blood", r.getName());
		assertEquals(284, r.getCount());

		r = ChatParser.parse("Your Barrows chest count is: 57.");
		assertEquals("Barrows", r.getName());

		r = ChatParser.parse("Your Gauntlet completion count is: 12.");
		assertEquals("Gauntlet", r.getName());
	}

	@Test
	public void personalBests()
	{
		ChatParser.Result r = ChatParser.parse("Fight duration: 1:23.40 (new personal best)");
		assertEquals(PERSONAL_BEST, r.getKind());
		assertEquals("1:23.40", r.getName());

		r = ChatParser.parse("Theatre of Blood completion time: 17:42 (new personal best)");
		assertEquals("17:42", r.getName());

		r = ChatParser.parse("Challenge duration: 1:02:03 (new personal best).");
		assertEquals("1:02:03", r.getName());

		assertNull(ChatParser.parse("Fight duration: 1:23. Personal best: 1:10"));
	}

	@Test
	public void collectionLogQuestsAndDiaries()
	{
		ChatParser.Result r = ChatParser.parse("New item added to your collection log: Avernic defender hilt");
		assertEquals(COLLECTION_LOG, r.getKind());
		assertEquals("Avernic defender hilt", r.getName());

		r = ChatParser.parse("Congratulations, you've completed a quest: Dragon Slayer II");
		assertEquals(QUEST, r.getKind());
		assertEquals("Dragon Slayer II", r.getName());

		r = ChatParser.parse("Congratulations! You have completed all of the elite tasks in the Kandarin area. Speak to someone.");
		assertEquals(DIARY_TIER, r.getKind());
		assertEquals("Kandarin", r.getName());
		assertEquals("Elite", r.getDetail());

		r = ChatParser.parse("Congratulations, you've completed a hard combat task: Just Like That (3 points).");
		assertEquals(COMBAT_TASK, r.getKind());
		assertEquals("Just Like That", r.getName());
		assertEquals("Hard", r.getDetail());
		assertEquals(3, r.getCount());

		// Points fall back to the tier's value when the message doesn't include them
		r = ChatParser.parse("Congratulations, you've completed an elite combat task: Perfect Zulrah.");
		assertEquals(4, r.getCount());

		// Machine-readable prefixes are ignored
		r = ChatParser.parse("CA_ID:1234|Congratulations, you've completed a master combat task: Perfect Olm (Solo) (5 points).");
		assertEquals(COMBAT_TASK, r.getKind());
		assertEquals("Perfect Olm (Solo)", r.getName());
		assertEquals("Master", r.getDetail());
		assertEquals(5, r.getCount());

		// The game marks the task name with a colour marker
		r = ChatParser.parse("Congratulations, you've completed an easy combat task: @ach_comp@Scurrius Novice (1 point).");
		assertEquals("Scurrius Novice", r.getName());
		assertEquals(1, r.getCount());

		r = ChatParser.parse("Congratulations, you've completed a grandmaster combat task: Inferno Grandmaster.");
		assertEquals(6, r.getCount());

		r = ChatParser.parse("Your subdued Wintertodt count is: 250.");
		assertEquals("Wintertodt", r.getName());
		assertEquals(250, r.getCount());
	}

	@Test
	public void petsSlayerAndClues()
	{
		assertEquals(PET, ChatParser.parse("You have a funny feeling like you're being followed.").getKind());
		assertEquals(PET, ChatParser.parse("You feel something weird sneaking into your backpack.").getKind());
		assertEquals(DUPLICATE_PET, ChatParser.parse("You have a funny feeling like you would have been followed...").getKind());

		ChatParser.Result r = ChatParser.parse("You've completed 482 tasks and received 15 points, giving you a total of 1,020; return to a Slayer master.");
		assertEquals(SLAYER_TASK, r.getKind());
		assertEquals(482, r.getCount());

		r = ChatParser.parse("You have completed 57 elite Treasure Trails.");
		assertEquals(CLUE, r.getKind());
		assertEquals("Elite", r.getName());

		assertNull(ChatParser.parse("Welcome to Old School RuneScape."));
	}
}

