package com.runejourney.service;

import com.google.gson.Gson;
import com.runejourney.RuneJourneyConfig;
import com.runejourney.model.DayRecord;
import com.runejourney.model.EventType;
import com.runejourney.model.JourneyEvent;
import com.runejourney.model.ProfileData;
import com.runejourney.planner.BossData;
import com.runejourney.planner.TrainingMethods;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AwayXpTest
{
	// Runecraft over a weekend on mobile: level 94 to 96
	private static final long RC_BEFORE = 8_659_400;
	private static final long RC_AFTER = 9_761_580;
	private static final long RC_GAINED = RC_AFTER - RC_BEFORE;

	private final RuneJourneyConfig config = new RuneJourneyConfig()
	{
		@Override
		public boolean chatAnnouncements()
		{
			return false;
		}
	};
	private final LocalDate today = LocalDate.now();

	private JourneyService service(ProfileData profile, TreeMap<String, DayRecord> days)
	{
		Gson gson = new Gson();
		JourneyService service = new JourneyService(null, null, config, gson, null, new TrainingMethods(gson), new BossData(gson));
		service.install("test", new JourneyStore.Loaded(profile, days));
		return service;
	}

	private static Map<String, Long> runecraft(long xp)
	{
		Map<String, Long> m = new HashMap<>();
		m.put("RUNECRAFT", xp);
		return m;
	}

	private static ProfileData lastSeen(long at)
	{
		ProfileData profile = new ProfileData();
		profile.setLastXp(runecraft(RC_BEFORE));
		profile.setLastXpAt(at);
		return profile;
	}

	private long millis(LocalDate date)
	{
		return date.atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli() + 60_000;
	}

	private static DayRecord played(LocalDate date)
	{
		DayRecord d = new DayRecord(date.toString());
		d.setPlayMillis(3_600_000);
		return d;
	}

	@Test
	public void xpFromAnEarlierDayIsNotToday()
	{
		JourneyService service = service(lastSeen(millis(today.minusDays(3))), new TreeMap<>());
		service.setBaseline(runecraft(RC_AFTER), 1);

		RangeSummary day = service.summarize(today, today);
		assertEquals(0, day.getXpGained());
		assertEquals(0, day.getLevelsGained());
		assertFalse(day.getLevelRanges().containsKey("RUNECRAFT"));
		assertEquals(RC_GAINED, day.getAwayXp());
		assertEquals(today.minusDays(3), day.getAwayFrom());
		assertEquals(today, day.getAwayTo());

		// A range covering the whole gap counts it
		RangeSummary span = service.summarize(today.minusDays(3), today);
		assertEquals(RC_GAINED, span.getXpGained());
		assertEquals(RC_GAINED, (long) span.getSkillXp().get("RUNECRAFT"));
		assertEquals(2, span.getLevelsGained());
		assertTrue(span.getLevelRanges().containsKey("RUNECRAFT"));
		assertEquals(0, span.getAwayXp());

		// One starting inside it doesn't
		assertEquals(0, service.summarize(today.minusDays(2), today).getXpGained());
	}

	@Test
	public void xpFromEarlierTodayIsToday()
	{
		JourneyService service = service(lastSeen(millis(today)), new TreeMap<>());
		service.setBaseline(runecraft(RC_AFTER), 1);

		RangeSummary day = service.summarize(today, today);
		assertEquals(RC_GAINED, day.getXpGained());
		assertEquals(2, day.getLevelsGained());
		assertEquals(0, day.getAwayXp());
	}

	@Test
	public void olderProfilesUseTheLastDayPlayed()
	{
		TreeMap<String, DayRecord> days = new TreeMap<>();
		days.put(today.minusDays(4).toString(), played(today.minusDays(4)));
		JourneyService service = service(lastSeen(0), days);
		service.setBaseline(runecraft(RC_AFTER), 1);

		RangeSummary day = service.summarize(today, today);
		assertEquals(0, day.getXpGained());
		assertEquals(today.minusDays(4), day.getAwayFrom());
	}

	/**
	 * A day saved before away XP was kept aside, as the login on {@code date} would have left it.
	 */
	private DayRecord oldLoginDay(LocalDate date, long noteTime)
	{
		DayRecord d = new DayRecord(date.toString());
		d.setPlayMillis(3_600_000);
		d.setXpGained(RC_GAINED + 50_000);
		d.getSkillXp().put("RUNECRAFT", RC_GAINED);
		d.getSkillXp().put("WOODCUTTING", 50_000L);
		d.setOfflineXp(RC_GAINED);
		d.getOfflineSkillXp().put("RUNECRAFT", RC_GAINED);
		d.setLevelsGained(2);
		// Written by the same login a few milliseconds before the note
		d.getEvents().add(new JourneyEvent(noteTime - 5, EventType.WEEKLY_PLAN, "Week complete", null, null, null, false, 0));
		JourneyEvent level = new JourneyEvent(noteTime - 2, EventType.LEVEL, "Level 96 Runecraft",
			"9,761,580 XP (gained while away)", "RUNECRAFT", null, false, 96);
		d.getEvents().add(level);
		d.getEvents().add(new JourneyEvent(noteTime, EventType.NOTE, "While you were away: +1.1m XP",
			"Runecraft +1.1m", null, null, false, 0));
		d.getEvents().add(new JourneyEvent(noteTime + 60_000, EventType.DROP, "Log brace", null, null, null, true, 0));
		return d;
	}

	@Test
	public void savedDaysAreMovedOutOfTheLoginDay()
	{
		TreeMap<String, DayRecord> days = new TreeMap<>();
		days.put(today.minusDays(3).toString(), played(today.minusDays(3)));
		DayRecord login = oldLoginDay(today, millis(today));
		days.put(today.toString(), login);
		JourneyService service = service(lastSeen(millis(today)), days);

		assertEquals(50_000, login.getXpGained());
		assertNull(login.getSkillXp().get("RUNECRAFT"));
		assertEquals(0, login.getLevelsGained());
		assertEquals(RC_GAINED, login.getAwayXp());
		assertEquals(2, login.getAwayLevels());
		assertEquals(today.minusDays(3).toString(), login.getAwayFrom());
		assertEquals(0, login.getOfflineXp());

		RangeSummary day = service.summarize(today, today);
		assertEquals(50_000, day.getXpGained());
		assertFalse(day.getLevelRanges().containsKey("RUNECRAFT"));
	}

	@Test
	public void savedDaysAreLeftAloneWhenUnsure()
	{
		TreeMap<String, DayRecord> days = new TreeMap<>();
		days.put(today.minusDays(3).toString(), played(today.minusDays(3)));

		// Something happened earlier that day, so the gap may have been from earlier today
		DayRecord earlier = oldLoginDay(today, millis(today) + 120_000);
		earlier.getEvents().add(new JourneyEvent(millis(today), EventType.DROP, "Dragon bones", null, null, null, false, 0));
		days.put(today.toString(), earlier);
		assertFalse(AwayXp.migrate(earlier, days));

		// Two gaps were added together
		DayRecord twice = oldLoginDay(today, millis(today));
		twice.getEvents().add(new JourneyEvent(millis(today) + 120_000, EventType.NOTE, "While you were away: +5k XP",
			null, null, null, false, 0));
		days.put(today.toString(), twice);
		assertFalse(AwayXp.migrate(twice, days));

		// Nothing played before it
		TreeMap<String, DayRecord> first = new TreeMap<>();
		DayRecord only = oldLoginDay(today, millis(today));
		first.put(today.toString(), only);
		assertFalse(AwayXp.migrate(only, first));
		assertEquals(RC_GAINED + 50_000, only.getXpGained());
	}
}

package com.runejourney.service;

import com.runejourney.RuneJourneyConfig;
import java.util.HashSet;
import java.util.Random;
import java.util.Set;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class EncouragementTest
{
	private final RuneJourneyConfig defaults = new RuneJourneyConfig()
	{
	};

	@Test
	public void slowerSkillsCheerMoreOften()
	{
		assertEquals(250_000, Encouragement.interval(defaults, Skill.AGILITY));
		assertEquals(250_000, Encouragement.interval(defaults, Skill.RUNECRAFT));
		assertEquals(500_000, Encouragement.interval(defaults, Skill.ATTACK));
		assertEquals(1_000_000, Encouragement.interval(defaults, Skill.CRAFTING));
		assertEquals(1_000_000, Encouragement.interval(defaults, Skill.SMITHING));
		assertEquals(0, Encouragement.interval(defaults, null));
	}

	@Test
	public void firesOncePerGap()
	{
		assertFalse(Encouragement.crossed(250_000, 1_100_000, 1_249_999));
		assertTrue(Encouragement.crossed(250_000, 1_249_990, 1_250_010));
		assertFalse(Encouragement.crossed(250_000, 1_250_010, 1_260_000));
		// 0 turns it off for that skill
		assertFalse(Encouragement.crossed(0, 0, 50_000_000));
	}

	@Test
	public void messagesVaryAndNeverRepeatBackToBack()
	{
		Encouragement e = new Encouragement(new Random(7));
		Set<String> seen = new HashSet<>();
		String previous = null;
		for (int i = 0; i < 200; i++)
		{
			String m = e.message(Skill.AGILITY, 250_000, 5_000_000);
			assertTrue(m, m.contains("250k") && m.contains("Agility"));
			String line = e.lastLine();
			assertNotEquals(previous, line);
			previous = line;
			seen.add(line);
		}
		assertTrue("expected plenty of variety, got " + seen.size(), seen.size() >= 10);
	}

	@Test
	public void followUpsAreAccurate()
	{
		Encouragement e = new Encouragement(new Random(1));
		boolean sawLevel = false;
		for (int i = 0; i < 100; i++)
		{
			// 5,346,332 XP is exactly level 90, so the next level is 91
			String m = e.message(Skill.MINING, 250_000, 5_346_332);
			if (m.contains("XP to level"))
			{
				assertTrue(m, m.contains("to level 91"));
				sawLevel = true;
			}
		}
		assertTrue(sawLevel);
	}
}

package com.runejourney.service;

import com.google.gson.Gson;
import com.runejourney.RuneJourneyConfig;
import com.runejourney.model.DayRecord;
import com.runejourney.model.EventType;
import com.runejourney.model.JourneyEvent;
import com.runejourney.planner.BossData;
import com.runejourney.planner.TrainingMethods;
import java.time.LocalDate;
import java.util.TreeMap;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Before;
import org.junit.Test;

public class EventNoteTest
{
	private static final String TODAY = LocalDate.now().toString();
	private static final long TIME = 1_000L;

	private JourneyService service;
	private final Gson gson = new Gson();

	@Before
	public void setUp()
	{
		RuneJourneyConfig config = new RuneJourneyConfig()
		{
		};
		service = new JourneyService(null, null, config, gson, null, new TrainingMethods(gson), new BossData(gson));
		TreeMap<String, DayRecord> days = new TreeMap<>();
		DayRecord d = new DayRecord(TODAY);
		d.setPlayMillis(60_000);
		d.getEvents().add(new JourneyEvent(TIME, EventType.DEATH, "Oh dear, you are dead!", null, null, null, false, 0));
		d.getEvents().add(new JourneyEvent(TIME, EventType.COLLECTION_LOG, "Guardian's eye", null, null, null, true, 0));
		days.put(TODAY, d);
		service.install("test", new JourneyStore.Loaded(null, days));
	}

	private JourneyEvent shown(String title)
	{
		return service.journeyDays(5, null, false).stream()
			.flatMap(d -> d.getEvents().stream())
			.filter(e -> e.getTitle().equals(title))
			.findFirst().orElseThrow(AssertionError::new);
	}

	@Test
	public void notesAreAddedEditedAndRemoved()
	{
		service.setEventNote(TODAY, TIME, "Oh dear, you are dead!", "  Forgot to pray at Zuk  ");
		assertEquals("Forgot to pray at Zuk", shown("Oh dear, you are dead!").getNote());
		// Only the matching event gets it, even at the same time
		assertNull(shown("Guardian's eye").getNote());

		service.setEventNote(TODAY, TIME, "Oh dear, you are dead!", "Forgot to pray at Zuk.\nNext time!");
		assertEquals("Forgot to pray at Zuk.\nNext time!", shown("Oh dear, you are dead!").getNote());

		service.setEventNote(TODAY, TIME, "Oh dear, you are dead!", "   ");
		assertNull(shown("Oh dear, you are dead!").getNote());
	}

	@Test
	public void notesSurviveSaving()
	{
		JourneyEvent e = new JourneyEvent(TIME, EventType.PET, "Tangleroot", null, null, null, true, 0);
		e.setNote("Finally!");
		JourneyEvent loaded = gson.fromJson(gson.toJson(e), JourneyEvent.class);
		assertEquals("Finally!", loaded.getNote());

		// Events saved before notes existed load without one
		JourneyEvent old = gson.fromJson("{\"time\":1,\"type\":\"PET\",\"title\":\"Tangleroot\"}", JourneyEvent.class);
		assertNull(old.getNote());
	}
}

package com.runejourney.service;

import com.google.gson.Gson;
import com.runejourney.RuneJourneyConfig;
import com.runejourney.model.Goal;
import com.runejourney.model.GoalItem;
import com.runejourney.model.GoalType;
import com.runejourney.planner.BossData;
import com.runejourney.planner.Counters;
import com.runejourney.planner.GoalProgress;
import com.runejourney.planner.Skills;
import com.runejourney.planner.TrainingMethods;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class GrandExchangePurchaseTest
{
	private static final int TWISTED_BOW = 20997;

	private JourneyService service;

	@Before
	public void setUp()
	{
		RuneJourneyConfig config = new RuneJourneyConfig()
		{
			@Override
			public boolean chatAnnouncements()
			{
				return false;
			}

			@Override
			public boolean screenshotGoals()
			{
				return false;
			}
		};
		Gson gson = new Gson();
		service = new JourneyService(null, null, config, gson, null, new TrainingMethods(gson), new BossData(gson));
		service.install("test", new JourneyStore.Loaded(null, new TreeMap<>()));
		Map<String, Long> xp = new HashMap<>();
		for (Skill s : Skills.ALL)
		{
			xp.put(s.name(), Skills.xpForLevel(80));
		}
		service.setBaseline(xp, 1);
	}

	private Goal purchaseGoal(int quantity, long price)
	{
		Goal g = new Goal();
		g.setType(GoalType.PURCHASE);
		g.setName("Buy Twisted bow");
		g.setCounter(Counters.CASH);
		g.getItems().add(new GoalItem(TWISTED_BOW, "Twisted bow"));
		g.setQuantity(quantity);
		g.setTargetCount(price * quantity);
		assertNull(service.createGoal(g));
		return g;
	}

	private GoalProgress progress(String id)
	{
		return service.goalProgress().stream().filter(p -> p.getGoal().getId().equals(id)).findFirst().get();
	}

	@Test
	public void affordingIsReadyButBuyingCompletes()
	{
		Goal g = purchaseGoal(1, 1_200_000_000L);
		service.onCash(true, 1_300_000_000L);
		assertEquals(GoalProgress.Status.READY, progress(g.getId()).getStatus());
		assertFalse(progress(g.getId()).isComplete());

		// Offer placed, then filled
		service.onGrandExchangeOffer(0, TWISTED_BOW, "Twisted bow", true, false, 0, 0);
		assertFalse(progress(g.getId()).isComplete());
		service.onGrandExchangeOffer(0, TWISTED_BOW, "Twisted bow", true, false, 1, 1_190_000_000L);
		assertTrue(progress(g.getId()).isComplete());
		assertTrue(service.goal(g.getId()).getStory().contains("Paid|1.19b gp"));
	}

	@Test
	public void loginReplayIsNotCountedTwice()
	{
		Goal g = purchaseGoal(5, 1_000_000L);
		service.onGrandExchangeOffer(2, TWISTED_BOW, "Twisted bow", true, false, 3, 3_000_000L);
		assertEquals(3, service.goal(g.getId()).getPurchasedQuantity());

		// The game replays the same offer on the next login
		service.resetSessionState();
		service.onGrandExchangeOffer(2, TWISTED_BOW, "Twisted bow", true, false, 3, 3_000_000L);
		assertEquals(3, service.goal(g.getId()).getPurchasedQuantity());

		// The rest fills later; collecting empties the slot
		service.onGrandExchangeOffer(2, TWISTED_BOW, "Twisted bow", true, false, 5, 5_000_000L);
		assertTrue(progress(g.getId()).isComplete());
